begin;
select pg_advisory_xact_lock(hashtextextended('theory-knowledge-network',0));
lock table public.theories in share row exclusive mode;
do $guard$ begin
if (select count(*) from public.theories where status='published') <> 947 then raise exception 'Catalogue changed'; end if;
if (select md5(string_agg(to_jsonb(t)::text,'|' order by id)) from public.theories t where status='published') is distinct from 'c29637f918e3ab30b1613958fa26815f' then raise exception 'Reviewed content changed'; end if;
end $guard$;
create temporary table theory_depth_edit (id text primary key,title text,summary text,quotation jsonb) on commit drop;
insert into theory_depth_edit select * from jsonb_populate_recordset(null::theory_depth_edit,'[{"id":"kb_399","title":"印象形成理論","summary":"言葉や振る舞いなどを組み合わせて、相手がどんな人かを判断するという理論。\n同じ無口な人でも、「落ち着いている」と聞くか「冷たい」と聞くかで、見え方は変わる。人物評は一つの特徴で固めず、その後の行動でも確かめるとよい。","quotation":null},{"id":"kb_881","title":"認知的閉鎖欲求","summary":"曖昧なままでいるより、早く答えを決めて安心したくなる気持ち。\n返事を待つ間に「嫌われた」と決めつける場面など。結論を急ぎたくなったら、まだ分からないことと、確かめられることを書き分ける。","quotation":null},{"id":"kb_597","title":"利用可能性ヒューリスティック","summary":"思い出しやすい出来事ほど、実際にもよく起こると思うこと。\n身近で一度失敗を見ただけで、「この方法はよく失敗する」と感じる場合など。印象の強さと、実際の件数や割合を分けて考える。","quotation":null},{"id":"kb_875","title":"錯誤相関","summary":"本当は関係のない二つのことを、結びついていると思い込むこと。\n苦手な相手が遅刻したときだけ記憶に残り、「あのタイプは時間にルーズだ」と結びつける場合など。当てはまらなかった例にも目を向ける。","quotation":null},{"id":"kb_752","title":"解釈レベル理論","summary":"遠いことは大まかな意味で、近いことは具体的な手順で考えやすいという理論。\n来年の勉強は「成長のため」と考え、明日の勉強は「何ページ読むか」と考える場面など。目標の意味と、直近の一歩を行き来すると計画が具体化する。","quotation":null},{"id":"kb_265","title":"認知的不協和","summary":"考えと行動の矛盾を不快に感じ、つじつまが合うように考えを変えること。\n高い買い物で失敗したとき、「高いから価値がある」と理由を足す場合など。自分を納得させる説明と、実際に得られたものを分けて振り返る。","quotation":null},{"id":"kb_556","title":"忙しさバイアス","summary":"成果よりも、忙しく動いていること自体を高く評価してしまうこと。\n長時間残業した人を、短時間で同じ成果を出した人より評価する場面など。働いた時間に加え、何が終わり、誰の役に立ったかを見る。","quotation":null},{"id":"kb_421","title":"一貫性ヒューリスティック","summary":"言動が一貫している人を、信頼できる人だと判断しやすいこと。\nいつも同じ基準で約束を守る人には、安心して頼みやすい。ただし一貫していることだけで、判断の正しさまで保証されるわけではない。","quotation":null},{"id":"kb_430","title":"感情ヒューリスティック","summary":"好き嫌いや不安を、物事の正しさや危険さを判断する手がかりにすること。\n感じのよい説明者の提案は、欠点まで小さく見えやすい。気持ちを手がかりにしつつ、費用や条件は別に確かめると判断の偏りに気づける。","quotation":null},{"id":"kb_452","title":"権威バイアス","summary":"肩書や地位のある人の意見を、根拠を確かめず正しいと思うこと。\n有名人の発言でも、その分野に詳しいとは限らない。誰が言ったかに加え、何を根拠にしているか、専門の範囲内かを確かめる。","quotation":null},{"id":"kb_046","title":"行為者・観察者バイアス","summary":"自分の行動は事情で説明し、他人の行動は性格で説明しやすいこと。\n自分の返信の遅さは忙しさ、相手の遅さは不誠実さで説明する場合など。相手にも自分と同じように、外から見えない事情があり得る。","quotation":null},{"id":"kb_027","title":"誤帰属理論","summary":"感情や体の反応が起きた理由を、別の相手や出来事に取り違えること。\n寝不足のいら立ちを「この人とは合わない」と受け取る場合など。相手への評価を固める前に、疲れや空腹など自分の状態も振り返る。","quotation":null},{"id":"kb_231","title":"コントロール幻想","summary":"偶然で決まる結果まで、自分の行動で変えられると思うこと。\nくじを自分で選ぶと、当たりやすくなったように感じる場面など。工夫が結果に働く部分と、偶然に任せる部分を切り分ける。","quotation":null},{"id":"kb_396","title":"自己高揚バイアス","summary":"自分の能力や人柄を、実際より好意的に評価すること。\n自分は周囲より公平だと思っていても、身近な人への甘さには気づきにくい。自己評価に、具体的な記録や他者からの意見を添えると見直しやすい。","quotation":null},{"id":"kb_708","title":"自己奉仕バイアス","summary":"成功は自分の実力、失敗は周囲の事情によるものだと考えること。\n試験に受かれば実力、不合格なら問題が悪かったと考える場合など。よい結果でも悪い結果でも、自分の工夫と外部の条件を両方見る。","quotation":null},{"id":"kb_710","title":"自信過剰効果","summary":"自分の知識や予測は、実際以上に正確だと信じること。\n「一時間で終わる」と見積もった作業が、毎回長引く場面など。自信の強さより、過去に予想がどれだけ当たったかを基準にする。","quotation":null},{"id":"kb_400","title":"情報ギャップ理論","summary":"「知りたいのに分からない」という隙間が、好奇心を生むという理論。\n答えの一部が見えるクイズや、続きが気になる話がその例。説明では先に小さな問いを示すと、相手が何を知りたいかを持ちやすい。","quotation":null},{"id":"kb_718","title":"真実性錯覚","summary":"何度も聞いた話を、根拠がなくても本当らしく感じること。\n同じうわさを何度も目にすると、複数の証拠があるように感じる場合など。繰り返しの回数より、元の情報源が同じでないかを確かめる。","quotation":null},{"id":"kb_720","title":"正常性バイアス","summary":"危険の兆候があっても「いつもどおりだ」と受け流してしまうこと。\n警報が出ても「前回は何もなかった」と準備を後回しにする場面など。いざというときの判断を、その場の安心感だけに任せないための視点になる。","quotation":null},{"id":"kb_723","title":"説明深度の錯覚","summary":"分かっているつもりでも、説明してみると理解の浅さに気づくこと。\n普段使う道具でも、仕組みを順に説明しようとすると言葉が止まることがある。理解を確かめたいときは、専門語を使わず誰かに説明してみる。","quotation":null},{"id":"kb_587","title":"選択されなかった道の理想化","summary":"選ばなかった道のよい面だけを想像し、現実より美化すること。\n辞めなかった仕事や選ばなかった進路には、経験していない苦労が見えにくい。今の道の欠点だけでなく、別の道にもあったはずの負担を考える。","quotation":null},{"id":"kb_811","title":"第三者効果","summary":"広告や報道の影響は、自分より他人のほうが受けると思うこと。\n「自分は広告に流されない」と思いながら、繰り返し見た商品を選ぶ場合など。他人への影響を論じる前に、自分の選択のきっかけも振り返る。","quotation":null},{"id":"kb_812","title":"敵対的メディア効果","summary":"対立する話題の報道を、自分の立場に不利な内容だと感じやすいこと。\n同じ記事を読んだ両陣営が、ともに「相手びいきだ」と感じる場合など。記事の事実と、自分が望んだ扱いとの違いを見分ける手がかりになる。","quotation":null},{"id":"kb_707","title":"偽の合意効果","summary":"自分の意見や選択は、多くの人も同じだと思うこと。\n「普通は連絡を毎日する」と思っても、相手の普通は違うかもしれない。暗黙の了解で進めず、頻度や期限などを言葉で確かめる。","quotation":null},{"id":"kb_814","title":"偽の独自性効果","summary":"自分のよい性質や習慣は、他の人には珍しいと思うこと。\n自分だけが丁寧に準備していると思っていても、他の人の準備は見えていないことがある。目立つ成果だけで、周囲の努力の少なさを判断しない。","quotation":null},{"id":"kb_577","title":"認知的オフローディング","summary":"覚えることや段取りをメモや道具に任せ、頭の負担を減らすこと。\n予定を頭で覚え続ける代わりに、カレンダーへ入れる場面など。記録する場所を決めておけば、思い出すことより目の前の作業に注意を使える。","quotation":null},{"id":"kb_574","title":"認知的柔軟性","summary":"状況に合わせて、見方ややり方を切り替えられる力。\n説明が通じないとき、言い直すだけでなく図や実例に変える場面など。一つの方法にこだわらず、相手や条件に応じて手段を増やす。","quotation":null},{"id":"kb_511","title":"ネガティビティ・バイアス","summary":"よい情報より悪い情報のほうが、注意や記憶に強く残りやすいこと。\n十件の感謝より、一件の批判ばかり気になる場面など。改善点は拾いつつ、うまくいった記録も同じ場所で見返すと全体を捉えやすい。","quotation":null},{"id":"kb_820","title":"ノセボ効果","summary":"副作用への不安や否定的な予想によって、不快な症状が生じたり強まったりすること。\n悪い反応の説明を聞いた後、体の小さな変化が気になり続ける場合など。症状は思い込みと決めつけず、必要な情報と気になる変化を医療者に確かめる。","quotation":null},{"id":"kb_719","title":"バイアスの盲点","summary":"自分より他人のほうが、思い込みに左右されていると思うこと。\n相手の偏見は見えても、自分の好き嫌いは「客観的な判断」だと感じる場合など。反対の立場でも同じ基準を使うかを確かめてみる。","quotation":null},{"id":"kb_387","title":"薄片判断","summary":"短い会話やわずかな表情だけで、相手の人物像を推測すること。\n初対面で「話しやすそう」と感じる判断も、その一つ。最初の感触は仮の見立てとして持ち、別の場面の振る舞いも見て更新する。","quotation":null},{"id":"kb_450","title":"パターン認識","summary":"出来事の共通点や繰り返しから、規則や傾向を見つけること。\n何度も起きる連絡ミスから、引き継ぎの抜けに気づく場面など。共通点を見つけた後は、偶然の一致でないか、別の例でも確かめる。","quotation":null},{"id":"kb_559","title":"場の理論","summary":"行動は性格だけでなく、その人を取り巻く環境によっても変わるという理論。\n発言の少ない人でも、少人数なら意見を話せることがある。人を変えようとする前に、人数や座席、話す順番を変える余地も探せる。","quotation":null},{"id":"kb_586","title":"反実仮想","summary":"「もし別の選択をしていたら」と、起こらなかった可能性を考えること。\n失敗を振り返り「先に確認していれば」と考える場面など。過去を責め続ける代わりに、次回変えられる条件を一つ取り出すと改善につながる。","quotation":null},{"id":"kb_029","title":"ピーク・エンドの法則","summary":"体験を、最も印象的な瞬間と最後の場面から評価しやすいこと。\n会合では長さだけでなく、心が動いた場面や別れ際の対応も記憶に残る。ただし最後を整えれば、途中の不快な体験が帳消しになるわけではない。","quotation":null},{"id":"kb_236","title":"フォーカシング・イリュージョン","summary":"一つの条件を、人生全体の幸福を決めるほど重要だと思うこと。\n「転職できれば全部うまくいく」と、仕事以外の生活を見落とす場合など。注目している条件を一度外し、人間関係や健康など他の条件も並べる。","quotation":null},{"id":"kb_819","title":"プラセボ効果","summary":"治療そのものの成分以外に、期待や安心感なども症状の変化に影響すること。\n治療への説明や信頼関係も、本人が感じる変化に関わることがある。期待だけで病気が治るという意味ではなく、治療の効果は比較して確かめる必要がある。","quotation":null},{"id":"kb_429","title":"ホット・コールド共感ギャップ","summary":"落ち着いているときと、怒りや欲求が強いときの判断の違いを見誤ること。\n空腹でないときに決めた食事の予定を、空腹になると守りにくい場面など。気持ちが強く動く場面を想定し、余裕のあるうちに対処を決めておく。","quotation":null},{"id":"kb_810","title":"楽観バイアス","summary":"自分にはよいことが起こり、悪いことは起こりにくいと思うこと。\n「自分だけは締切に間に合う」と、遅延の可能性を小さく見る場面など。期待は持ちながら、遅れた場合の余白や代案も用意する。","quotation":null},{"id":"kb_716","title":"小数の法則","summary":"少ない事例だけで、全体の傾向まで分かったと思うこと。\n数人の感想だけで「みんな満足している」と決める場合など。人数に加え、どんな人から集めた意見かも確かめる。","quotation":null},{"id":"kb_712","title":"代表性ヒューリスティック","summary":"典型的なイメージに似ているかで、起こりやすさを判断すること。\n几帳面そうな見た目だけで職業や性格を推測する場面など。イメージとの一致に加え、実際の人数の割合や行動の記録も見る。","quotation":null},{"id":"kb_105","title":"バーナム効果","summary":"誰にでも当てはまる説明を、自分だけに当てはまると思うこと。\n「社交的な面もあるが、一人の時間も大切」と言われ、特別に理解されたと感じる場合など。その説明が他の人にも広く当てはまらないか考える。","quotation":null},{"id":"kb_959","title":"ウェーバーの法則","summary":"もとの刺激が大きいほど、違いに気づくために大きな変化が必要になるという法則。\n静かな部屋の小さな音は目立っても、雑踏では気づきにくい。変化を伝えたいときは、変えた量だけでなく、もとの状態も考える手がかりになる。","quotation":null},{"id":"kb_960","title":"感覚順応","summary":"同じ音やにおいなどに触れ続けると、感じ方の強さが変わること。\n部屋に入った直後のにおいを、しばらくすると意識しなくなる場面など。慣れて感じなくなったことと、刺激がなくなったことは分けて考える。","quotation":null},{"id":"kb_961","title":"知覚的構え","summary":"期待や経験によって、目に入るものの受け取り方が変わること。\n「怖い人」と聞いてから会うと、静かな表情まで険しく見える場合など。先に聞いた評判が、どこに注目するかを変えていないか振り返る。","quotation":null},{"id":"kb_962","title":"ゲシュタルトの群化原理","summary":"近くにあるものや似たものを、一つのまとまりとして見るという原理。\n資料の見出しと本文を近づけ、別の話題の間には余白を置く使い方ができる。枠を増やす前に、間隔や並びで関係を示すと読み取りやすい。","quotation":null},{"id":"kb_964","title":"予測符号化理論","summary":"脳は情報を予想し、実際との違いから予想を修正するという理論。\n聞き慣れた言葉なら、雑音があっても続きを補って聞ける場面など。便利な予想は聞き違いも生むため、大切な内容は復唱して確かめる。","quotation":null},{"id":"kb_969","title":"絶対閾","summary":"音や光などの存在に気づける、最小限の刺激の強さ。\n小さな通知音が聞こえるかは、周囲の雑音や本人の状態でも変わる。気づいてほしい合図は、音だけでなく表示など複数の手がかりで伝えられる。","quotation":null},{"id":"kb_971","title":"心的回転","summary":"形や物の向きを、頭の中で回して比べること。\n家具が部屋に入るか、図形の向きを変えて考える場面など。頭の中で比べにくいときは、図を回したり模型を使ったりして補える。","quotation":null},{"id":"kb_981","title":"二重過程理論","summary":"判断には、直感的に答える働きと、立ち止まって考える働きがあるという理論。\n慣れた買い物は直感で選び、大きな契約は条件を並べて考える場面など。すべてを熟考するより、見直す必要のある判断に時間を残す視点になる。","quotation":null},{"id":"kb_982","title":"属性置換","summary":"難しい問いを、気づかずに答えやすい別の問いに置き換えること。\n「この人に仕事を任せられるか」を「感じがよいか」で答える場合など。判断前に、本来確かめたい問いを言葉に戻してみる。","quotation":null},{"id":"kb_983","title":"信念バイアス","summary":"結論がもっともらしいと、理由の筋道まで正しいと思うこと。\n自分の賛成する結論なら、説明の飛躍を見逃す場合など。逆の結論でも、その理由づけを受け入れられるか考えると点検しやすい。","quotation":null},{"id":"kb_984","title":"認知欲求","summary":"難しいことを考えるのが好きで、自分から考えようとする傾向。\n説明を読む人の中にも、理由を深く知りたい人と、まず結論を知りたい人がいる。相手の関心を確かめ、説明の深さを調整する際の視点になる。","quotation":null},{"id":"kb_985","title":"イデオモーター効果","summary":"思い描いた動きが、自覚のない小さな体の動きになること。\n振り子を見つめて動きを想像すると、手の微小な動きで揺れる場合など。本人に動かした自覚がないことだけでは、外からの不思議な力の証拠にはならない。","quotation":null},{"id":"kb_023","title":"感情伝染","summary":"表情や声、態度を通じて、周囲の感情が自分にも移ること。\n一人のいら立った口調で、集まり全体が緊張する場面など。周囲の気分に飲まれそうなときは、自分の声や話す速さを整える余地がある。","quotation":null},{"id":"kb_905","title":"キャノン＝バード理論","summary":"感情と体の反応は、刺激に対して同時並行で生じるという理論。\n驚いた瞬間に、怖さと動悸がともに現れるという捉え方。体の変化が先に起き、その解釈から感情が生まれるという説明と比べると違いが分かる。","quotation":null},{"id":"kb_602","title":"拡張・形成理論","summary":"喜びや興味が視野と行動の幅を広げ、知識や人間関係を育てるという理論。\n楽しい会話から、新しい活動や人とのつながりに踏み出す場面など。目先の気分のよさが、後で頼れる経験や関係を増やす入口になるという見方。","quotation":null},{"id":"kb_234","title":"感情予測の誤り","summary":"将来の喜びや苦しさが、どれほど強く長く続くかを見誤ること。\n「断られたらずっと立ち直れない」と想像しても、その後の日常までは思い描けていないことがある。出来事の直後と、一か月後を分けて考える。","quotation":null},{"id":"kb_235","title":"インパクト・バイアス","summary":"将来の出来事が気持ちに与える影響を、実際より大きく見積もること。\n失敗の瞬間ばかり想像すると、気持ちの回復や周囲の支えを見落としやすい。つらさの大きさだけでなく、続く長さも分けて見積もる。","quotation":null},{"id":"kb_268","title":"快楽順応","summary":"よい変化にも悪い変化にも慣れ、幸福感が元の水準に近づくこと。\n欲しかった物も、手に入れてしばらくすると日常の一部になる。次を増やす前に、今あるものの使い方や楽しみ方を変える余地を探せる。","quotation":null},{"id":"kb_158","title":"感情＝社会的情報理論","summary":"相手の感情表現を、その人の意図や状況を知る手がかりにするという理論。\n困った表情を見て説明を補ったり、喜ぶ反応から関心を知ったりする場面など。表情の意味は状況でも変わるので、必要なら本人に確かめる。","quotation":null},{"id":"kb_601","title":"予期的味わい","summary":"これからの楽しみを想像し、起きる前から喜びを味わうこと。\n旅行の計画を立て、行きたい場所を話す時間も楽しみになる。結果だけを待たず、準備や想像の時間にも喜びを見つける視点になる。","quotation":null},{"id":"kb_203","title":"不確実性不耐性","summary":"先が分からないこと自体を脅威と感じ、心配や確認を続けること。\n返信が来るまで何度も画面を開いても、先のことが分かるとは限らない。確認で分かる範囲と、分からないまま待つ必要のある範囲を見分ける。","quotation":null},{"id":"kb_204","title":"心配の回避理論","summary":"強い感情を避けるための心配が、かえって心配を長引かせるという理論。\n「もし失敗したら」と考え続け、実際の悲しさや不安に触れるのを避ける場合など。対策が一つも増えていないなら、心配と問題解決を分けて捉えられる。","quotation":null},{"id":"kb_206","title":"認知的注意症候群","summary":"不安なことを探し、心配や考え直しを繰り返して、つらさが長引く状態。\n体の変化や相手の反応を監視し続けると、不安を感じる材料ばかり集まることがある。何を考えるかに加え、注意をどこへ向け続けているかを見る。","quotation":null},{"id":"kb_205","title":"メタ認知モデル","summary":"「この考えは危険だ」「止められない」という思いが、不安を長引かせるという考え方。\n考えが浮かんだこと自体を恐れると、消そうとしてさらに気になる場合など。考えの内容だけでなく、その考えにどんな意味を与えたかに注目する。","quotation":null},{"id":"kb_216","title":"反すう理論","summary":"同じ問題を考え続けることが、解決よりも気分の悪化につながるという理論。\n「なぜ自分はだめなのか」を繰り返しても、次の行動は決まりにくい。「何が起きたか」「次に何を変えるか」と問いを具体化する手がかりになる。","quotation":null},{"id":"kb_213","title":"破局的思考","summary":"最悪の結果ばかり想像し、それには対処できないと思うこと。\n一度の失敗から「信用をすべて失う」と話が広がる場合など。最悪の予想と、今確認できる事実、使える対処を別々に並べる。","quotation":null},{"id":"kb_208","title":"回避学習","summary":"避けて安心できた経験から、次も避けるようになること。\n発表を断るとその場は楽でも、次の発表がさらに怖くなる場合など。短い安心と、後の選択肢が増えたかを分けて振り返る。","quotation":null},{"id":"kb_214","title":"確率過大評価","summary":"悪い出来事が起こる可能性を、実際より高く見積もること。\n一度の不採用から「次も必ず落ちる」と感じる場合など。不安の強さを、そのまま起こる確率の高さと取り違えないための視点になる。","quotation":null},{"id":"kb_212","title":"感情推論","summary":"「不安だから危険だ」と、気持ちを事実の証拠にすること。\n「申し訳ない気がするから、自分が悪いはずだ」と考える場面にも表れる。感情は大切な反応として扱い、事実関係は別に確かめる。","quotation":null},{"id":"kb_220","title":"経験回避","summary":"嫌な気持ちを避けることを優先し、行動の選択肢を狭めること。\n緊張したくないために、人と会う機会をすべて断る場合など。気持ちを消すことが優先され、大切にしたい活動まで遠ざかっていないか振り返る。","quotation":null},{"id":"kb_215","title":"コスト過大評価","summary":"悪い出来事が起きた場合の損失や苦痛を、実際より大きく見積もること。\n小さな言い間違いで、関係が取り返しのつかないほど壊れると予想する場面など。起きる可能性と、起きた後に修正できる範囲を分けて考える。","quotation":null},{"id":"kb_565","title":"ストレス緩衝仮説","summary":"他者の支えが、ストレスによる悪影響を和らげるという考え方。\n同じ課題でも、相談できる人がいると一人で抱えずに済むことがある。助言、共感、実際の手伝いのうち、今必要な支えを具体化すると頼みやすい。","quotation":null},{"id":"kb_228","title":"ストレス評価理論","summary":"ストレスは、出来事だけでなく「対処できるか」という受け止め方でも変わるという理論。\n同じ依頼でも、期限や助けを選べるかで負担感は変わる。何が脅威かに加え、時間・情報・支援のどれがあれば取り組めるかを考える。","quotation":null},{"id":"kb_211","title":"抑制学習モデル","summary":"恐れていたことが起きない経験から安全を学び、恐怖を抑えるという考え方。\n怖さが一度で消えることより、「怖くても予想した結果にはならなかった」という学びに注目する。治療では状態に合わせて、専門家と安全な取り組み方を決める。","quotation":null},{"id":"kb_240","title":"レジリエンス理論","summary":"困難からの回復を、本人の力と周囲の支えの両方から考える理論。\n傷つかない強さだけを求めず、休息や相談、生活を立て直す工夫も回復の力として見る。一人で耐え続けることと、回復できることは同じではない。","quotation":null},{"id":"kb_254","title":"曖昧な喪失","summary":"失ったのか、まだつながっているのかが分からず、区切りをつけられない状態。\n行方が分からない人や、心身の変化で以前と同じ関係を持てない相手への思いなど。白黒つかない状態のつらさを理解し、結論を急がないための視点になる。","quotation":null},{"id":"kb_255","title":"権利を認められない悲嘆","summary":"周囲に喪失を認めてもらえず、悲しんだり支えを求めたりしにくい状態。\n周囲に知られていない関係の別れなどは、悲しみを話す場所まで失いやすい。周囲が認めるかどうかと、本人にとっての喪失の重さを分けて受け止める。","quotation":null},{"id":"kb_588","title":"喪失の二重過程モデル","summary":"悲しみに向き合う時間と、生活を立て直す時間を行き来して回復するという考え方。\n思い出して泣く日も、日常の用事に集中する日もある。気分が行き来することを後戻りと決めつけず、その時々に必要な時間として捉える。","quotation":null},{"id":"kb_245","title":"シャッタード・アサンプション","summary":"大きな被害や喪失で、世界の安全や公平さへの信頼が崩れること。\n「努力すれば報われる」と信じてきた人が、理不尽な被害で何を信じればよいか分からなくなる場合など。単なる気分の落ち込みとは違う揺らぎに目を向ける。","quotation":null},{"id":"kb_243","title":"意味生成モデル","summary":"経験と信じてきたことのずれを、新しい意味づけで受け止め直すという考え方。\n挫折を「自分には価値がない」の証拠にするか、「進め方を変える出来事」と見るかで、その後の向き合い方は変わる。納得できる意味を急いで決める必要はない。","quotation":null},{"id":"kb_581","title":"意味世界の崩壊","summary":"喪失や挫折によって、それまで信じていた人生の前提が通用しなくなること。\n仕事や関係を失ったとき、予定だけでなく生き方の筋道まで見失う場合など。すぐ次の目標を示すより、何が支えだったかを一緒に確かめる視点になる。","quotation":null},{"id":"kb_248","title":"汚染物語","summary":"後の悪い経験によって、過去のよい出来事まで台無しだったと捉えること。\n別れた後に「あの楽しい時間も全部嘘だった」と考える場面など。今の結末と、その時点で確かに感じていたことを分けて振り返る余地がある。","quotation":null},{"id":"kb_563","title":"死の顕現性","summary":"死を意識すると、自分の価値や信念、所属集団を強く守ろうとすること。\n命の限りを意識したとき、所属や正しさへのこだわりが強まる場面を考えられる。自分や相手の強い反応を、表面の意見だけで理解しないための視点になる。","quotation":null},{"id":"kb_247","title":"償還物語","summary":"つらい経験を、その後の成長や価値ある結果につながる物語として捉えること。\n失敗をきっかけに働き方を見直した、と語る場合など。本人が見いだす意味を尊重する見方であり、周囲が「よい経験だった」と押しつけるものではない。","quotation":null},{"id":"kb_210","title":"曝露療法","summary":"恐れる状況に安全な形で向き合い、新しい経験を重ねる治療法。\n避けていた場面を、本人の状態に合わせた段階で経験し直す。怖さを我慢させる方法ではなく、専門家と目標や進め方を調整して行う。","quotation":null},{"id":"kb_901","title":"認知行動療法","summary":"考え方と行動の両方を見直し、困り事への対処を学ぶ心理療法。\n出来事、浮かんだ考え、感情、行動のつながりを整理し、別の捉え方や行動を試す。無理に前向きにするのでなく、困り事の循環を具体的に見直していく。","quotation":null},{"id":"kb_238","title":"ストレス接種訓練","summary":"ストレスの仕組みと対処法を学び、段階的な練習で備える方法。\nたとえば本番前に、緊張への気づき方や対処を小さな練習で確かめておく。負荷を強くすること自体が目的ではなく、使える対処を増やす点を重視する。","quotation":null},{"id":"kb_272","title":"ロゴセラピー","summary":"自分の人生に意味を見いだすことを重視する心理療法。\n変えられない困難の中でも、誰かとの関わりや、自分が選ぶ態度に意味を探す。苦しみに意味をつける義務ではなく、本人が大切にしたいものを考える視点。","quotation":null},{"id":"kb_227","title":"感情ラベリング","summary":"「怒り」「焦り」「寂しさ」など、感情に言葉で名前をつけること。\nひとまとめに「つらい」とするより、「断られて寂しい」「予定が崩れて焦る」と表す。気持ちの違いが見えると、休息や相談など必要な対応も考えやすい。","quotation":null},{"id":"kb_217","title":"具体性訓練","summary":"漠然とした自己批判を、具体的な出来事や次の行動の検討に変える方法。\n「いつも失敗する」を、「昨日の説明で確認が一つ抜けた」と言い換える場面など。直せる行動が見える粒度まで、出来事を小さく捉え直す。","quotation":null},{"id":"kb_226","title":"セルフ・ディスタンシング","summary":"自分の問題を、少し離れた第三者の立場から考える方法。\n「友人が同じ状況なら、何と声をかけるか」と考える場面など。感情のただ中から少し距離を取り、選べる対応を探す手がかりになる。","quotation":null},{"id":"kb_224","title":"脱中心化","summary":"考えや感情を、自分そのものではなく、一時的に心に浮かぶものとして見ること。\n「自分はだめだ」ではなく、「だめだという考えが浮かんでいる」と捉える。考えを消そうとするより、それだけで行動を決めずにいられる余地をつくる。","quotation":null},{"id":"kb_230","title":"二次的コントロール","summary":"変えられない状況に対し、自分の受け止め方や行動を調整すること。\n天候は変えられなくても、予定や服装は変えられる場面など。相手や環境を動かす工夫が難しいとき、自分が調整できる側に目を向ける。","quotation":null},{"id":"kb_580","title":"反すうの中断","summary":"同じことを考え続ける状態から、注意や行動を切り替えて離れること。\n同じ問いに戻っていると気づいたら、場所を移す、手を動かすなど注意の向け先を変える工夫がある。問題を放置することと、考える時間を区切ることを分ける。","quotation":null},{"id":"kb_202","title":"行動活性化","summary":"達成感や大切なことにつながる活動を増やし、落ち込みと回避の循環を変える方法。\n気分の回復を待つだけでなく、負担に合った小さな活動を予定し、その後の気分を確かめる。治療では本人の状態に合わせ、活動と休息の組み合わせを考える。","quotation":null},{"id":"kb_986","title":"感情調整プロセスモデル","summary":"感情への対処を、状況の選び方、注意、受け止め方、反応などに分けて考える理論。\n苦手な集まりを短くする、話題を変える、受け取り方を見直すなど、対処できる地点は複数ある。表情を抑えるだけに頼らず、早い段階の工夫も探せる。","quotation":null},{"id":"kb_987","title":"情動粒度","summary":"自分の感情を、焦り、怒り、落胆などに細かく見分ける力。\n同じ「嫌だ」でも、不安と怒りでは必要な対処が違う。体の感覚や出来事をたどり、より近い言葉を選ぶと、自分の状態を伝えやすくなる。","quotation":null},{"id":"kb_988","title":"感情構成理論","summary":"感情は、体の感覚と経験、そのときの状況から組み立てられるという理論。\n動悸が、場面によって緊張にも期待にも感じられることなどを考える理論。体の反応に一つの意味を固定せず、状況や受け取り方にも目を向ける。","quotation":null},{"id":"kb_989","title":"社会的評価不安","summary":"他人に悪く評価されることを、強く心配すること。\n会議での小さな言い間違いを、周囲がいつまでも覚えていると心配する場面など。相手の実際の反応と、自分の中で繰り返す予想を区別する。","quotation":null},{"id":"kb_259","title":"自己概念明確性","summary":"自分の性格や価値観を、はっきり一貫して理解できている度合い。\n何を大事にし、何が苦手かを自分の言葉で説明できることが一つの手がかり。状況に合わせて変わる部分があっても、すべてを矛盾と考える必要はない。","quotation":null},{"id":"kb_257","title":"自己不一致理論","summary":"今の自分と、理想や「こうあるべき自分」のずれが、落ち込みや不安を生むという理論。\n「なりたい自分」に届かない悲しさと、「すべきこと」を果たせない不安を分けて考える。今の目標が、自分の望みか他者への義務感かを確かめる入口になる。","quotation":null},{"id":"kb_020","title":"自己検証理論","summary":"人は褒められるだけでなく、自分の思う自分らしさを認めてもらいたいという理論。\n自分を慎重な人だと思う人には、「大胆だね」より「丁寧に確かめたね」のほうがしっくりくることがある。褒め言葉も、本人の自己理解とすれ違う場合がある。","quotation":null},{"id":"kb_420","title":"自己知覚理論","summary":"自分の行動を見て、「自分はこう思っているのだ」と気持ちを推測するという理論。\n頼まれて手伝ううちに、「自分はこの活動が好きなのかもしれない」と感じる場合など。気持ちがはっきりしないとき、実際に選んでいる行動を手がかりにする。","quotation":null},{"id":"kb_869","title":"プロテウス効果","summary":"仮想空間で使うアバターの見た目に、自分の振る舞いが影響されること。\n堂々とした姿のアバターで、いつもより積極的に話す場合など。見た目だけで誰もが変わるわけではないが、役割の感じ方も行動に関わるという視点になる。","quotation":null},{"id":"kb_883","title":"モラル・ライセンシング","summary":"よいことをした実感を、その後のよくない行動の言い訳にすること。\n「昨日たくさん手伝ったから、今日は約束を破ってもよい」と考える場面など。過去の善行と、今の行動を選ぶ理由を別々に点検する。","quotation":null},{"id":"kb_251","title":"アイデンティティ移行","summary":"役割や環境の変化に合わせて、自分らしさをつくり直していくこと。\n学生から社会人になると、使える時間や期待される振る舞いも変わる。前の自分を捨てるより、引き継ぐものと新しく覚えるものを整理する過程として捉える。","quotation":null},{"id":"kb_249","title":"アイデンティティ喪失","summary":"役割や所属を失い、自分が何者か分からなくなること。\n退職で、仕事だけでなく人と会う機会や自信の支えまで失う場合など。次の肩書を急ぐ前に、失った役割が何を満たしていたかを見つめる。","quotation":null},{"id":"kb_589","title":"アイデンティティ・フォークロージャー","summary":"十分に試したり迷ったりせず、周囲に与えられた進路や価値観を自分のものにすること。\n「家族が望むから」という理由だけで進路を決め、他の可能性を試していない場合など。選び直すときは、従ってきた期待と自分の関心を分けてみる。","quotation":null},{"id":"kb_727","title":"インポスター現象","summary":"実績があっても自分の力だと認められず、評価が誤りだと知られるのを恐れること。\n成功を運や周囲のおかげだけで説明し、次は見抜かれると不安になる場合など。感謝とは別に、自分が行った工夫や判断も記録しておくと振り返りやすい。","quotation":null},{"id":"kb_239","title":"学習性無力感","summary":"何をしても変わらない経験が続き、変えられる状況でも諦めてしまうこと。\n意見を聞いてもらえない経験が続き、聞いてくれる場でも黙ってしまう場合など。本人の意欲だけを責めず、行動で状況が変わる経験を取り戻す視点になる。","quotation":null},{"id":"kb_244","title":"仮定世界理論","summary":"世界は安全で意味があり、自分にも価値があるという信頼が生活を支えるという理論。\n約束が守られる、困れば助けを求められるという前提が、日々の行動を支える。大きな喪失では、その前提自体の立て直しが必要になることがある。","quotation":null},{"id":"kb_256","title":"可能自己","summary":"将来なりたい自分や、なりたくない自分についてのイメージ。\n「相談される先輩になりたい」など、未来の自分像が今の行動の目安になる。理想像に、今日できる小さな行動を一つ結びつけると使いやすい。","quotation":null},{"id":"kb_582","title":"基本的前提の動揺","summary":"困難な経験によって、安全や公平さ、人への信頼が揺らぐこと。\n理不尽な扱いに遭い、「頑張れば守られる」という感覚が揺れる場合など。以前の常識で励ますだけでは届かない理由を理解する手がかりになる。","quotation":null},{"id":"kb_021","title":"自己拡張理論","summary":"人との関係を通じて、新しい経験や能力を自分に取り込みたいという理論。\n友人に誘われて未知の趣味を始め、自分の世界が広がる場面など。関係の中に小さな新体験を持つことが、互いの発見につながる。","quotation":null},{"id":"kb_558","title":"自己更新","summary":"経験に合わせて、技能や考え方、自分らしさを見直し続けること。\n昔うまくいった方法も、環境が変われば使いにくくなる。変えたくない価値観と、変えてよい手順を分けると、経験を活かしながら学び直せる。","quotation":null},{"id":"kb_478","title":"自己注目理論","summary":"自分に注意が向くと、理想や基準とのずれを直そうとするという理論。\n発表中に自分の声や表情ばかり気になり、話の内容に集中しにくくなる場合もある。自分を点検する時間と、相手や課題を見る時間の配分を考える。","quotation":null},{"id":"kb_258","title":"自己複雑性","summary":"自分を複数の役割で捉えると、一つの失敗で自分全体を否定しにくいという考え方。\n仕事で失敗しても、友人、家族、趣味の仲間としての自分は残っている。役割ごとの経験を持つことが、一つの評価で生活全体を決めない支えになる。","quotation":null},{"id":"kb_590","title":"拙速な再同一化","summary":"役割を失った不安から、急いで新しい肩書や自分像に飛びつくこと。\n退職直後に、よく知らない活動へ全力でのめり込む場面など。新しい居場所を一度で決めず、小さく試しながら自分に合うか確かめる余地を持つ。","quotation":null},{"id":"kb_815","title":"ソシオメーター理論","summary":"自尊心は、人に受け入れられているかを知らせる指標だという理論。\n仲間外れにされたと感じると、自分の価値まで低く思える場合など。自尊心の変化を、自分の能力だけでなく、今いる関係の状態からも捉える。","quotation":null},{"id":"kb_271","title":"存在的真空","summary":"人生の意味や目的が見つからず、空虚さや退屈を感じる状態。\n予定は埋まっていても、「何のために続けているのか」が分からないことがある。忙しさを足す前に、心が動く経験や大切にしたい関係を振り返る入口になる。","quotation":null},{"id":"kb_725","title":"統制の所在","summary":"結果を、自分の行動によるものと見るか、運や他者によるものと見るかという傾向。\n努力で変えられる部分を見る人も、運や立場の影響を強く見る人もいる。場面ごとに両方を点検すると、自責にも他責にも偏りすぎず次を考えやすい。","quotation":null},{"id":"kb_882","title":"テロ管理理論","summary":"死への不安を、信念や文化、自分の価値を信じることで和らげるという理論。\n死を意識したとき、文化や集団への帰属が安心の支えになるという見方。強い信念へのこだわりを考える視点の一つで、個人の反応を一律には説明しない。","quotation":null},{"id":"kb_246","title":"ナラティブ・アイデンティティ","summary":"過去と現在、未来を一つの物語につなげて、自分を理解すること。\n転職を「逃げた経験」と語るか「働き方を選び直した経験」と語るかで、自分への理解は変わる。出来事を消さず、別のつながり方を探すことができる。","quotation":null},{"id":"kb_270","title":"補償的コントロール理論","summary":"自分で状況を動かせないとき、強い制度や指導者に安心を求めるという理論。\n見通しが立たない時期に、断言する人へ強く惹かれる場面など。安心できる説明かどうかと、根拠が確かかどうかを分けて受け取る。","quotation":null},{"id":"kb_250","title":"役割退出理論","summary":"中心だった役割を離れ、新しい生活や自分像へ移っていくという理論。\n退職や介護の終了では、役目を終える手続きと、気持ちが離れる時期は一致しないことがある。残したい経験と、新しくつくる日常の両方を考える。","quotation":null},{"id":"kb_252","title":"リミナリティ","summary":"以前の役割を離れ、新しい役割にはまだ落ち着いていない状態。\n前の仕事は辞めたが、次の居場所にはまだなじんでいない時期など。宙ぶらりんな感覚をすぐ失敗とせず、試行錯誤の途中として捉える言葉になる。","quotation":null},{"id":"kb_111","title":"印象管理理論","summary":"周囲にどう見られるかを考え、言動や外見を調整するという理論。\n面接では実績を強調し、友人には親しみやすさを見せる場面など。相手に合わせる工夫と、事実を偽ることの境目を考える視点にもなる。","quotation":null},{"id":"kb_112","title":"自己呈示理論","summary":"望む自分像を相手に伝えるため、見せる情報や行動を選ぶという理論。\n丁寧な仕事をする人と伝えたいなら、口で言うだけでなく、確認や納期の守り方で示せる。見せたい姿と日々の行動が合っているかを見る。","quotation":null},{"id":"kb_115","title":"自他知識非対称性モデル","summary":"自分がよく分かる特徴と、他人のほうが気づく特徴があるという考え方。\n自分の不安は自分が知りやすい一方、話し方の癖は周囲が気づきやすい。自己理解を深めるには、内面の記録と具体的な他者の意見を組み合わせられる。","quotation":null},{"id":"kb_122","title":"反射的栄光浴","summary":"成功した人や集団とのつながりを強調し、自分の評価も高めようとすること。\n応援するチームが勝った後に「自分たちが勝った」と話す場面など。つながりを誇る気持ちと、自分自身が担った貢献を分けて見る。","quotation":null},{"id":"kb_221","title":"心理的柔軟性","summary":"嫌な気持ちがあっても、それに支配されず、大切なことに沿って動ける力。\n緊張が残っていても、伝えたいことのために一言発言する場面など。気持ちが整うのを待つだけでなく、大切な方向へどんな一歩を選べるかを考える。","quotation":null},{"id":"kb_262","title":"学習性楽観主義","summary":"失敗を「一時的で、限られた、変えられること」と捉え直す考え方。\n「自分は何をしてもだめ」を、「今回は準備時間が足りなかった」と捉え直す場面など。失敗を無視せず、範囲と変えられる原因を具体化する。","quotation":null},{"id":"kb_990","title":"自尊心の随伴性","summary":"自分の価値を、他人の承認や仕事の成功など特定の結果に結びつけること。\n仕事で褒められた日は安心し、評価されない日は自分全体を否定する場合など。一つの結果に価値を預けすぎていないかを見直す手がかりになる。","quotation":null},{"id":"kb_992","title":"達成動機理論","summary":"成功したい気持ちと、失敗を避けたい気持ちから、挑戦の選び方を考える理論。\n実力を試せる課題を選ぶ人も、失敗が目立たない課題を選ぶ人もいる。選んだ難しさだけでなく、何を期待し何を恐れているかを見る。","quotation":null},{"id":"kb_030","title":"社会的交換理論","summary":"人間関係を、得られるものと負担の釣り合いから考える理論。\n話を聞いてもらえる喜びと、いつも一方だけが聞く疲れは、関係の続けやすさに関わる。お金以外の時間、気遣い、安心も含めて釣り合いを捉える。","quotation":null},{"id":"kb_031","title":"衡平理論","summary":"負担と見返りの割合が互いに釣り合うと、公平だと感じるという理論。\n家事を同じ量で分けても、使える時間が違えば不公平に感じることがある。量の等しさだけでなく、事情に対してどう負担を配るかを話し合う視点になる。","quotation":null},{"id":"kb_034","title":"投資モデル","summary":"関係を続ける理由を、満足度、他の相手の魅力、これまで注いだものから考える理論。\n長く一緒にいたから離れにくいことと、今の関係に満足していることは別に考えられる。続ける理由を分けてみると、自分が何を大切にしているか見えやすい。","quotation":null},{"id":"kb_005","title":"類似性魅力効果","summary":"価値観や趣味などが似ている相手に、親しみを感じやすいこと。\n同じ趣味や大切にすることが分かると、初対面でも話の足場ができる。共通点を探す際は、無理に合わせず、実際に重なる部分を拾う。","quotation":null},{"id":"kb_007","title":"好意の返報性","summary":"好意を向けられると、自分も好意を返したくなること。\n感謝や親しみを言葉にすると、相手も好意を示しやすくなる場合がある。ただし好意を示したことは、相手に応答や親密さを求める権利にはならない。","quotation":null},{"id":"kb_095","title":"ガスライティング","summary":"事実や記憶を繰り返し否定し、相手に自分の判断を疑わせる心理的な操作。\n「そんなことは言っていない」と否定され続け、自分の記憶に自信を失う場合など。単発の記憶違いと決めつけず、繰り返しの経緯を記録し、第三者にも相談できる。","quotation":null},{"id":"kb_428","title":"葛藤回避の逆説","summary":"衝突を避けて黙ることが、不満をため、より大きな対立を招くこと。\n小さな不満を我慢し続け、別のきっかけで一気に噴き出す場面など。安全に話せる関係では、出来事と希望を小さいうちに伝える余地を探す。","quotation":null},{"id":"kb_391","title":"カメレオン効果","summary":"相手の動きを無意識にまねすることで、親しみや会話の滑らかさが増すこと。\n相手が身を乗り出すと自分も近づくなど、会話の中で自然に起こる。露骨に動きをまねることより、相手の調子に注意を向ける視点として使う。","quotation":null},{"id":"kb_426","title":"関係維持行動","summary":"好意を伝える、話し合う、分担するといった、関係を続けるための行動。\n忙しいときに予定を共有する、負担の偏りを話し合うことも含まれる。仲のよさを気持ちだけに任せず、続けるための小さな行動として捉える。","quotation":null},{"id":"kb_038","title":"関係のエスカレーション・モデル","summary":"人間関係が、出会いから親密さや生活の共有へ進むという考え方。\n軽い挨拶から、個人的な話や一緒の活動へ関わりが増える場面など。進む速さや望む近さは人で違うため、関係の段階を一方だけで決めない。","quotation":null},{"id":"kb_039","title":"関係破綻・修復モデル","summary":"関係の悪化を、不満、距離の広がり、対立、修復や別れの流れで捉える考え方。\n不満を抱える時期と、距離を置いた後では、必要な話し合いも違う。今どの地点で行き違っているかを整理し、修復の意思が双方にあるかを見る。","quotation":null},{"id":"kb_044","title":"帰属的葛藤","summary":"相手の行動を悪意や性格のせいと受け取り、対立を深めること。\n返信の遅れを「自分を軽んじているから」と受け取ると、責める言い方になりやすい。行動の事実と、その理由についての推測を分ける。","quotation":null},{"id":"kb_434","title":"期待違反理論","summary":"予想と違う振る舞いをされると、相手への評価を見直すという理論。\n普段そっけない人の気遣いが、強く印象に残る場面など。驚きがよい評価になるかは、元の関係や行動の内容によって変わる。","quotation":null},{"id":"kb_444","title":"キック・ザ・ドッグ効果","summary":"強い相手に返せない怒りを、反撃しにくい別の相手にぶつけること。\n上司に叱られた怒りを、帰宅後に家族へ向ける場面など。今目の前にいる相手と、感情のきっかけになった相手が同じかを振り返る。","quotation":null},{"id":"kb_816","title":"拒絶感受性","summary":"拒絶を恐れ、曖昧な反応まで「拒まれた」と受け取りやすいこと。\n短い返事を見ただけで、「嫌われた」と受け取って距離を置く場合など。解釈を確定する前に、他の事情でも説明できないかを考える。","quotation":null},{"id":"kb_821","title":"近接性効果","summary":"近くにいて接する機会が多い人ほど、関係が生まれやすいこと。\n席が近い人や同じ時間に会う人とは、挨拶や雑談の入口が生まれやすい。会う回数が増えることと、相性や信頼が育つことは分けて見ておく。","quotation":null},{"id":"kb_026","title":"ゲイン・ロス効果","summary":"初めから褒める人より、低い評価から高い評価に変わった人に惹かれること。\n評価の上昇が「自分を認めてくれた」という印象になる場合がある。初めに冷たく扱えばよいという方法ではなく、評価の変化に注目する考え方。","quotation":null},{"id":"kb_015","title":"言語スタイル同調","summary":"言葉遣いや話す調子が似ることで、会話の一体感が生まれること。\n専門語の多い説明を相手の使う言葉に置き換えると、話を進めやすい。口癖をそっくりまねるより、分かりやすさや丁寧さの程度を合わせる。","quotation":null},{"id":"kb_390","title":"行動同調","summary":"会話を交わすうちに、姿勢や声、話す速さが互いに似てくること。\n話す速さや相づちの間隔が、やり取りの中で近づくことがある。一方だけが無理をしていないかも見ながら、心地よい会話の速さを探す。","quotation":null},{"id":"kb_818","title":"心の理論","summary":"他人には自分と違う知識や気持ちがあると理解し、行動を推測する力。\n自分には当然の情報でも、相手はまだ知らないかもしれない。説明が通じないとき、理解力を疑う前に、前提の情報が共有されているか確かめる。","quotation":null},{"id":"kb_032","title":"コミューナル関係・交換関係","summary":"必要に応じて支え合う関係と、見返りを釣り合わせる関係を分ける考え方。\n友人の看病をその都度精算しようとすると、関係の期待とずれる場合がある。助け合う場面か、役割や対価を決める場面かを互いに確かめる。","quotation":null},{"id":"kb_035","title":"最小関心原理","summary":"関係を失いたくない気持ちが強い側ほど、譲歩しやすくなるという原理。\n「嫌われたくない」ために、無理な条件も受け入れる場面など。わざと冷たく振る舞うより、自分にも断る選択肢を持てるかに目を向ける。","quotation":null},{"id":"kb_446","title":"三角関係化","summary":"二人の間の不満や緊張を、第三者を巻き込んで処理しようとすること。\n当事者に話さず、共通の友人へ不満を伝えて味方を求める場面など。安全が保てるなら、誰と何を解決する話なのかを整理して対話の経路を選ぶ。","quotation":null},{"id":"kb_410","title":"支援適合理論","summary":"支援は多さよりも、相手が必要としていることに合うかが大切だという考え方。\n話を聴いてほしい人へ助言ばかりすると、善意でも負担になる。「今は聴いてほしいか、一緒に方法を考えたいか」を尋ねると支援を合わせやすい。","quotation":null},{"id":"kb_018","title":"質問好意効果","summary":"関心を持って質問し、話をよく聴く人ほど好かれやすいこと。\n相手の答えを受けて「それでどうなったの」と聞くと、関心が伝わりやすい。質問の数を増やすより、答えを踏まえることや話したくない範囲を尊重する。","quotation":null},{"id":"kb_824","title":"社会的ベースライン理論","summary":"信頼できる人がいるだけで、困難に向き合う負担が軽くなるという理論。\n難しい用事に、一人で行くより信頼する人と行くほうが心強い場面など。人の支えを特別な援助だけでなく、普段の負担を分け合う土台として見る。","quotation":null},{"id":"kb_447","title":"情報境界理論","summary":"個人的な情報を、誰にどこまで伝えてよいか決めるという考え方。\n打ち明け話を聞くことと、他の人へ伝えてよいことは同じではない。相談を受けたら、共有してよい相手や範囲を確かめておくと行き違いを防ぎやすい。","quotation":null},{"id":"kb_730","title":"所属欲求","summary":"受け入れられる居場所や、続いていく関係を求める気持ち。\n役に立つかどうかだけでなく、そこにいてよいと感じられることも居場所を支える。人が集団に合わせすぎる場面を、受け入れられたい気持ちからも理解できる。","quotation":null},{"id":"kb_037","title":"親密性平衡モデル","summary":"距離や視線を調整し、心地よい親密さを保とうとするという理論。\n隣に座る距離が近くなると、視線を少し外して調整する場面など。親しさは距離だけで測らず、相手が心地よくいられる複数の合図を見る。","quotation":null},{"id":"kb_424","title":"信頼修復理論","summary":"損なわれた信頼を、謝罪や償い、その後の行動で取り戻すという考え方。\n謝る言葉に加え、損失への対応や、同じ問題を防ぐ行動が必要になる。相手がすぐ信じ直すことを求めず、確かめられる変化を重ねる。","quotation":null},{"id":"kb_439","title":"信頼の段階的回復","summary":"小さな約束を守る経験を重ねて、信頼を少しずつ取り戻すこと。\n大きな約束を一度するより、連絡の時刻など小さな約束を繰り返し守る場面など。回復の速さを決めるのは、約束する側だけではない。","quotation":null},{"id":"kb_050","title":"心理的リアクタンス","summary":"自由を奪われたと感じると、反発して取り戻そうとする心理。\n「絶対にこうして」と言われるほど、反対したくなる場面など。依頼では理由を伝え、選べる範囲を残すと、相手が自分で判断しやすい。","quotation":null},{"id":"kb_898","title":"カリギュラ効果","summary":"禁止されると、かえって見たい、知りたいと思うこと。\n「見てはいけない」とだけ言われた内容が、気になり続ける場面など。注意を伝えるなら、禁止の強さだけでなく理由や代わりの選択肢も示す。","quotation":null},{"id":"kb_397","title":"脆弱性の相互性","summary":"自分の弱さや不安を打ち明けると、相手も心を開きやすくなること。\n「実は少し緊張している」と話したことで、相手も不安を話せる場合など。打ち明ける量や内容は、関係の近さと相手の余裕に合わせる。","quotation":null},{"id":"kb_566","title":"相対的剥奪","summary":"他人や期待した水準と比べて、不公平や不足を感じること。\n生活が以前よりよくなっても、周囲の変化が大きいと取り残されたと感じる場合がある。何と比べて不足を感じているかを言葉にすると整理しやすい。","quotation":null},{"id":"kb_006","title":"相補性","summary":"互いの違いや得意分野が補い合い、よい関係や成果につながること。\n案を広げる人と、実行の段取りを整える人が協力する場面など。違いがあるだけで補い合えるとは限らず、役割や意思疎通を合わせる必要がある。","quotation":null},{"id":"kb_096","title":"DARVO","summary":"加害を指摘された側が、否定し、相手を攻撃し、自分を被害者にすり替えること。\n問題の事実を確かめたいのに、「責められて傷ついた」という話へ置き換わる場合など。反応だけで断定せず、元の出来事と論点の移り方を記録する。","quotation":null},{"id":"kb_022","title":"対人魅力の報酬理論","summary":"一緒にいて心地よさや利益を得られる相手ほど、好意を持つという理論。\n安心して話せる、笑える、理解されるといった経験も、関係の中の報酬になる。何かを与えれば好かれるという取引ではなく、一緒にいる体験に注目する。","quotation":null},{"id":"kb_094","title":"ダブルバインド","summary":"矛盾した要求を受け、どちらに従っても責められ、その矛盾も指摘できない状態。\n「何でも話して」と言われながら、意見を話すと怒られる場面など。要求同士の食い違いを言葉にし、安全に確認できる相手や第三者の助けを探す。","quotation":null},{"id":"kb_012","title":"知覚されたパートナー応答性","summary":"相手が自分を理解し、尊重し、気遣ってくれていると感じること。\n相談への答えが正しくても、気持ちを受け止めてもらえないと満たされないことがある。解決案を示す前に、何を大切にしている話かを確かめる。","quotation":null},{"id":"kb_028","title":"吊り橋効果","summary":"恐怖や緊張のドキドキを、相手に惹かれる気持ちと取り違えること。\n緊張する状況での高まりと、相手への持続的な好意は区別して見る必要がある。落ち着いた場面でも一緒にいたいかが、自分の気持ちを確かめる手がかりになる。","quotation":null},{"id":"kb_093","title":"共依存","summary":"相手の問題を抱えることで自分の価値を感じ、不健全な関係を支え合うこと。\n相手のためと言いながら、問題をすべて肩代わりし、双方が離れにくくなる場合など。助ける範囲と本人の責任を見直す言葉であり、一つの行動だけで人を診断しない。","quotation":null},{"id":"kb_043","title":"ネガティブ感情の相互性","summary":"怒りや敵意を向けられると、同じように返したくなること。\nきつい口調へさらに強い言葉を返すと、元の問題より対立が大きくなる。すぐ同じ強さで返さず、話す時刻や場所を変える選択肢も持てる。","quotation":null},{"id":"kb_056","title":"フェイスワーク","summary":"自分や相手の面子を守り、傷ついた尊厳を取り戻す働きかけ。\n人前で間違いを指摘する代わりに、個別に確認する対応など。事実を曖昧にせず、相手が訂正や再出発をしやすい伝え方を探す。","quotation":null},{"id":"kb_010","title":"不確実性低減理論","summary":"初対面の不安を減らすため、質問や観察で相手を知ろうとするという理論。\n出身や仕事など、答えやすい話題から共通点を探す場面など。相手を早く知ろうとして、個人情報や話したくないことまで聞き出さないようにする。","quotation":null},{"id":"kb_025","title":"プラットフォール効果","summary":"能力のある人が小さな失敗を見せると、かえって親しみを感じること。\n頼れる人のちょっとした言い間違いに、人間らしさを感じる場合など。信頼の土台がないと印象は違うため、失敗を演出する方法とは考えない。","quotation":null},{"id":"kb_019","title":"ベン・フランクリン効果","summary":"誰かを助けたことをきっかけに、その相手を好きになりやすくなること。\n小さな相談に答えてもらったことが、関わりの入口になる場合など。相手が断れる依頼にとどめ、手伝いの負担や感謝も忘れない。","quotation":null},{"id":"kb_823","title":"マッチング仮説","summary":"恋愛では、外見の魅力などが近い相手同士で関係が成立しやすいという考え方。\n相手からも受け入れられそうかという見込みが、接近の仕方に関わるという見方。外見だけで相性や関係の価値を決めるための基準ではない。","quotation":null},{"id":"kb_419","title":"ミケランジェロ現象","summary":"理想の自分を理解し支えてくれる相手といると、その姿に近づきやすくなること。\n相手の望む挑戦を応援し、小さな進歩に気づく関わりが一例。自分の理想に相手を変えるのでなく、本人がなりたい姿を確かめることが土台になる。","quotation":null},{"id":"kb_014","title":"ミラーリング効果","summary":"相手の表情や動きに自然に合わせることで、親近感が生まれること。\n相手がゆっくり話すなら、自分も少し速度を落とすなどの合わせ方がある。不自然な模倣より、声や間合いに気を配る姿勢を大切にする。","quotation":null},{"id":"kb_422","title":"予測可能性","summary":"相手がどう反応するかを、前もって見通せること。\n同じ相談に対する基準が毎回変わると、周囲は頼むこと自体に身構えやすい。できることや断る条件を共有すると、関わりの見通しをつくれる。","quotation":null},{"id":"kb_600","title":"ライキング・ギャップ","summary":"会話の後、相手からの好意を実際より低く見積もること。\n会話後に自分の言い間違いばかり思い出し、相手が楽しんだ可能性を見落とす場合など。自分の反省を、相手の評価そのものと受け取らない。","quotation":null},{"id":"kb_114","title":"現実的正確性モデル","summary":"相手の特徴に気づき、その意味を正しく読むことで、人物判断が正確になるという理論。\n丁寧さを判断するにも、その特徴が表れる行動を見る機会が必要になる。一度の感触だけでなく、約束や確認の場面で得た手がかりを重ねる。","quotation":null},{"id":"kb_460","title":"個人化","summary":"集団の一員としてだけでなく、その人固有の経験や特徴から理解すること。\n「営業の人」ではなく、その人の経験や考えを聞いて理解する場面など。属性による予想を、本人から得た情報で更新していく。","quotation":null},{"id":"kb_472","title":"バランス理論","summary":"人や物への好き嫌いに食い違いがあると、つじつまを合わせたくなるという理論。\n好きな友人が自分の苦手な人と親しいと、落ち着かなくなる場面など。好悪を無理にそろえず、それぞれの関係に違う事情があると考える余地を持つ。","quotation":null},{"id":"kb_403","title":"ロジャーズの受容","summary":"相手の気持ちや経験を、本人にとって意味のあるものとして尊重すること。\n「そんなことで悲しまないで」と直す前に、その人には何がつらかったのかを聴く。気持ちを尊重することと、すべての行動に賛成することは区別できる。","quotation":null},{"id":"kb_024","title":"アクティブ・コンストラクティブ・レスポンディング","summary":"相手のうれしい報告に、関心と喜びを示して積極的に応じること。\n「よかったね」で終わらず、「どこが一番うれしかった」と話を広げる場面など。成果をすぐ自分の話へ奪わず、相手の喜びを一緒に味わう。","quotation":null},{"id":"kb_405","title":"感情焦点型コミュニケーション","summary":"出来事の正誤より、相手がどう感じたかにも注目して話すこと。\n「何が起きたか」とともに、「そのときどう感じたか」を尋ねる。事実の確認と気持ちの理解を両方扱うと、言い争いの奥の困り事を見つけやすい。","quotation":null},{"id":"kb_097","title":"グレーロック法","summary":"挑発に感情や情報を多く返さず、淡々と接して関わりを減らす方法。\n必要な連絡だけを短く返し、挑発的な話題を広げない対応など。相手が激しく反応するおそれもあるため、身の安全や周囲の支援を優先して関わり方を考える。","quotation":null},{"id":"kb_099","title":"ドア・イン・ザ・フェイス","summary":"大きな依頼を断られた後に小さな依頼を出し、受け入れてもらいやすくする方法。\n断った後に依頼が小さくなると、こちらも譲るべきだと感じる場合がある。頼まれた側は、最初の案との比較だけでなく、今の依頼そのものが妥当かを考える。","quotation":null},{"id":"kb_098","title":"フット・イン・ザ・ドア","summary":"小さな依頼を受けてもらった後に、大きな依頼をする方法。\n一度協力すると、その後の頼みも断りにくく感じる場合がある。先に応じたことと、新しい依頼へ応じるかは、その都度別に選べる。","quotation":null},{"id":"kb_100","title":"ローボール・テクニック","summary":"好条件で決めた後は、条件が悪くなっても撤回しにくい心理を利用する方法。\n申し込み後に追加料金が分かっても、決め直す手間から続けてしまう場合など。条件が変わった時点で、初めからその条件でも選ぶかを問い直す。","quotation":null},{"id":"kb_388","title":"非言語コミュニケーション","summary":"表情や声、姿勢、視線など、言葉以外で気持ちや意図を伝えること。\n同じ「大丈夫」でも、声や表情によって安心にも無理にも聞こえる。合図だけで本心を断定せず、言葉と食い違うときは丁寧に確かめる。","quotation":null},{"id":"kb_871","title":"マガーク効果","summary":"聞こえる音と口の動きが食い違うと、別の音に聞こえること。\n会話の聞き取りには、耳からの音だけでなく見える情報も関わる。聞き違いが起きたときは、相手の注意不足だけで説明せず、口元や音声の条件も見直せる。","quotation":null},{"id":"kb_859","title":"グライスの協調原理","summary":"互いに協力して話している前提で、言外の意味も読み取るという考え方。\n「明日は早いんです」という返事を、誘いへの遠回しな断りと読む場面など。言外の意味は共通の前提に依存するため、大切な確認は推測だけに任せない。","quotation":null},{"id":"kb_789","title":"共通基盤理論","summary":"互いに何を知っているか確かめ、共通の理解をつくりながら会話するという理論。\n「いつもの資料」で通じるかは、共有している経験によって違う。説明の最初に目的や用語をそろえ、相手の反応を見ながら理解を確かめる。","quotation":null},{"id":"kb_788","title":"コミュニケーション適応理論","summary":"話し方を相手に近づけたり違いを示したりして、関係を調整するという理論。\n相手に合わせた丁寧さが親しみを示すことも、自分らしい話し方が立場を示すこともある。合わせすぎて不自然にならない範囲で、伝わり方を調整する。","quotation":null},{"id":"kb_860","title":"ポライトネス理論","summary":"相手の面子や自由を守るため、距離や立場に合わせて言い方を変えるという理論。\n「今すぐやって」より「今日中にお願いできる？」と選択の余地を示す場面など。遠回しにしすぎて要件が消えないよう、配慮と明確さを両立させる。","quotation":null},{"id":"kb_784","title":"精緻化可能性モデル","summary":"説得を、内容で納得する道と、話し手の好感や肩書で判断する道に分ける理論。\n関心と余裕があれば理由を検討し、余裕がなければ見た目や評判を頼りにしやすい。説明では相手の状況を見て、結論と根拠を読み取りやすく示す。","quotation":null},{"id":"kb_413","title":"会話の連鎖","summary":"質問が返答を呼ぶように、一つの発言が次の発言につながること。\n答えの一部を拾って次の質問へつなげると、唐突な話題転換を減らせる。用意した質問を消化するより、直前の言葉に応じる姿勢を意識する。","quotation":null},{"id":"kb_787","title":"社会的判断理論","summary":"新しい意見を、今の自分が受け入れられる範囲と比べて判断するという理論。\n立場が大きく違う提案は、内容を考える前に受けつけにくいことがある。まず一致する点を確かめ、どこから意見が分かれるかを具体化する。","quotation":null},{"id":"kb_857","title":"スリーパー効果","summary":"話の出所への不信が薄れ、時間がたってから内容の影響が強まること。\n怪しい出所だと思った話でも、後には内容だけ覚えている場合がある。時間がたっても、どこで聞いた話かを確かめ直すことが大切になる。","quotation":null},{"id":"kb_786","title":"接種理論","summary":"弱い反論とその答えを先に知ると、後の説得に流されにくくなるという理論。\n「この方法にはこんな反論もある」と、その理由と答えを事前に考える場面など。一方的に結論を覚えるより、弱点や反論に触れて理解を深める。","quotation":null},{"id":"kb_856","title":"ナラティブ・トランスポーテーション","summary":"物語に入り込むことで、反論する意識が弱まり、考えや態度が変わること。\n登場人物に感情移入し、その人物の見方を自然に受け入れる場合など。物語の説得力と、現実の主張を支える証拠は分けて確かめる。","quotation":null},{"id":"kb_861","title":"二段階流れ仮説","summary":"情報が、発信元から身近な人の解釈や紹介を経て広がるという考え方。\nニュースそのものより、信頼する友人の紹介で関心を持つ場合など。情報を届ける際は、誰が身近な言葉で伝え直すかにも目を向けられる。","quotation":null},{"id":"kb_461","title":"情報源効果","summary":"同じ話でも、誰が伝えるかで説得力や印象が変わること。\n同じ助言でも、経験者の言葉か広告の言葉かで受け止め方は変わる。話し手への信頼と、内容を裏づける証拠を両方確かめる。","quotation":null},{"id":"kb_785","title":"ヒューリスティック・システマティック・モデル","summary":"判断には、簡単な手がかりを頼る方法と、内容を詳しく考える方法があるという理論。\n評判で候補を絞った後に、仕様を詳しく比べるなど、二つの方法を併用する場合もある。手がかりだけで済ませてよい判断かを見極める視点になる。","quotation":null},{"id":"kb_928","title":"共感的正確性","summary":"相手が本当に考えたり感じたりしていることを、正確に読み取る力。\n相手が笑っていても、本当は気を遣っている場合がある。「楽しそうだった」で終えず、言葉や状況を踏まえて本人に確認し、推測を修正する。","quotation":null},{"id":"kb_1007","title":"対人距離理論","summary":"人との距離の取り方から、関係や文化の違いを考える理論。\n自分には自然な近さでも、相手には窮屈に感じられることがある。少し離れる動きなどを見ながら調整し、距離だけで親しさを決めつけない。","quotation":null},{"id":"kb_058","title":"社会的アイデンティティ理論","summary":"所属集団を自分の一部と感じ、その評価から自尊心を得るという理論。\n所属する会社や学校への批判を、自分への批判のように感じる場面など。集団への評価と、自分個人の価値を切り分ける手がかりになる。","quotation":null},{"id":"kb_059","title":"自己カテゴリー化理論","summary":"自分をある集団の一員と意識すると、その集団の基準に沿って行動するという理論。\n普段は個人の意見で動く人も、部署の代表になると部署の利益を優先する場合がある。今どの「私たち」が意識されているかに注目する。","quotation":null},{"id":"kb_062","title":"最小条件集団パラダイム","summary":"わずかな基準で分けただけの集団でも、仲間をひいきすること。\n好みの違いなどで分けただけでも、自分の側に有利な配分を選ぶことがある。仲間への安心感が、公平な判断とは限らないことを考えられる。","quotation":null},{"id":"kb_060","title":"内集団バイアス","summary":"自分の集団の人を、外の人より好意的に扱うこと。\n同じ失敗でも、身内なら事情をくみ、外の人なら厳しく責める場面など。相手の所属を入れ替えても同じ評価になるかを確かめる。","quotation":null},{"id":"kb_061","title":"外集団同質性効果","summary":"自分の集団には個人差を見ても、外の集団は皆同じように感じること。\n知らない部署を「あの人たちは全員そうだ」とまとめてしまう場合など。代表的な一人の印象を広げず、個々の違いや役割を知る機会を持つ。","quotation":null},{"id":"kb_063","title":"同調効果","summary":"周囲に合わせて、自分の意見や行動を変えること。\n周囲が賛成していると、自分の疑問を引っ込める場面など。皆の意見を聞く前に自分の考えを一度書いておくと、変化した理由を振り返りやすい。","quotation":null},{"id":"kb_888","title":"社会的インパクト理論","summary":"他者からの影響は、その人の力、近さ、人数で変わるという理論。\n遠い大勢の声より、目の前の信頼する人の一言が強く響く場合もある。人数だけでなく、発言者との距離や立場も影響の条件として見る。","quotation":null},{"id":"kb_459","title":"規範的影響","summary":"仲間外れになりたくない気持ちから、周囲の意見や行動に合わせること。\n本音は違っても、場を乱したくなくて賛成する場合など。本当に納得したのか、その場を保つために合わせたのかを分けて振り返る。","quotation":null},{"id":"kb_734","title":"情報的社会的影響","summary":"正解が分からないとき、他人の判断を正しさの手がかりにすること。\n初めての場所で、皆が並ぶ列を正しい受付だと思う場面など。周囲も手探りかもしれないので、大切な場面では案内や担当者にも確認する。","quotation":null},{"id":"kb_104","title":"社会的証明","summary":"多くの人が選んでいるものを、よいものや正しいものだと判断すること。\n利用者数や口コミの多さが、選ぶ際の安心材料になる。多くの人が選んだ理由と、自分が必要とする条件が一致するかも確かめる。","quotation":null},{"id":"kb_477","title":"一貫性原理","summary":"以前の発言や選択と、その後の行動を一致させようとすること。\n人前で約束したことは、状況が変わっても撤回しにくくなる場合がある。約束を大切にしながら、前提が変わったときは理由を伝えて見直せる。","quotation":null},{"id":"kb_733","title":"権威への服従","summary":"正当な権威の命令だと受け取り、自分の良心に反しても従うこと。\n上位者の指示だと、自分の疑問を抑えてしまう場面など。権限があることと、指示が妥当であることを分け、確認や相談の経路を持つ。","quotation":null},{"id":"kb_731","title":"ステレオタイプ脅威","summary":"自分の集団への悪いイメージを意識し、不安から実力を出しにくくなること。\n「この属性の人は苦手だ」と意識させられると、課題以外の心配に注意を使う場合がある。能力を見る場では、属性に関する不用意な前置きを避ける。","quotation":null},{"id":"kb_106","title":"情報カスケード","summary":"他人の選択をまねすることが連鎖し、同じ判断が広がること。\n皆が選んだ店を、全員が詳しく調べた結果だと思い込む場合など。選択が多いことと、独立した情報が多いことを分けて考える。","quotation":null},{"id":"kb_782","title":"閾値モデル","summary":"周囲がどのくらい動いたら自分も動くかで、集団行動を考える理論。\n誰も動かない中では動けなくても、数人が始めれば参加する人もいる。集団を動かすには、全員を同時に説得する以外の始め方も考えられる。","quotation":null},{"id":"kb_485","title":"共通内集団アイデンティティ","summary":"対立する相手も同じ大きな仲間だと捉え、偏見を和らげる考え方。\n部署同士が対立していても、同じ顧客の課題を解く仲間と見る場面など。違いを消すのでなく、協力できる上位の目的を探す。","quotation":null},{"id":"kb_481","title":"謙遜規範","summary":"自分の成果を控えめに語ることが、望ましいとされる基準。\n成果を直接語ると自慢に聞こえる場では、担当した役割や工夫を事実で伝える方法がある。控えめさのために、貢献まで見えなくしていないかも考える。","quotation":null},{"id":"kb_473","title":"自己成就予言","summary":"予想を信じて動くことで、相手や状況が変わり、予想が現実になること。\n「嫌われている」と思って避けると、相手もよそよそしくなり、予想が確かに見える場合など。最初の予想が自分の態度をどう変えたかを振り返る。","quotation":null},{"id":"kb_732","title":"脱個人化","summary":"匿名や集団の中で自分への意識が弱まり、その場の流れに沿って動くこと。\n匿名の場では、その集団の攻撃的な雰囲気にも協力的な雰囲気にも同調し得る。匿名だから必ず悪くなるとせず、場の基準や反応に注目する。","quotation":null},{"id":"kb_066","title":"沈黙の螺旋","summary":"少数派だと感じて黙る人が増え、多数派の声がますます大きく見えること。\n反対意見が見えないことを、反対する人がいない証拠と受け取る場合など。個別に尋ねたり匿名で意見を集めたりすると、声の大きさ以外の状況が見える。","quotation":null},{"id":"kb_484","title":"同調圧力","summary":"集団の期待が、異なる意見を言いにくくすること。\n明確に強制されなくても、「ここでは反対できない」と感じることがある。意見を集める側は、異論を言った後に不利益がないかまで考える。","quotation":null},{"id":"kb_457","title":"同調行動","summary":"自分の意見よりも、周囲に合わせた発言や行動を選ぶこと。\n会議で最初の発言に合わせ、違う案を出さない場面など。協調のために合わせる部分と、確認が必要な論点を区別しておける。","quotation":null},{"id":"kb_458","title":"内集団シグナル","summary":"言葉や習慣、服装などで、同じ集団の仲間だと伝えること。\n共通の専門語や作法は、初対面でも仲間だと感じる手がかりになる。初めて来た人に伝わらない言葉が、参加の壁になっていないかも見直す。","quotation":null},{"id":"kb_470","title":"排斥理論","summary":"集団からの無視や拒絶が、居場所や自尊心を脅かすという理論。\n返事がない、集まりに呼ばれないという経験も、本人には重い負担になり得る。「気にしすぎ」で片づけず、出来事と必要な支えを確かめる。","quotation":null},{"id":"kb_729","title":"バンドワゴン効果","summary":"皆が支持していると知って、自分も同じ側に動きたくなること。\n人気の上昇を知って「自分も選ぼう」と思う場面など。多数派である安心感と、選択肢そのものの価値を分けて比べる。","quotation":null},{"id":"kb_762","title":"ホーソン効果","summary":"見られている意識や、調査への参加によって行動が変わること。\n記録される期間だけ丁寧に対応するなど、普段とは違う行動が出る場合がある。調査で見えた変化を、仕組みの効果だけと早合点しないための視点。","quotation":null},{"id":"kb_925","title":"接触仮説","summary":"対等な立場で協力する経験が、異なる集団への偏見を減らすという考え方。\n共通の課題に、対等な立場で協力して取り組むことが重要になる。ただ顔を合わせる回数を増やすだけで、必ず偏見が減るという意味ではない。","quotation":null},{"id":"kb_926","title":"現実的葛藤理論","summary":"限られた利益の取り合いが、集団同士の敵意を強めるという理論。\n予算や席が少ない状況では、相手の獲得を自分たちの損と感じやすい。人柄への批判に進む前に、取り合っている条件や共通の利益を整理する。","quotation":null},{"id":"kb_927","title":"ステレオタイプ内容モデル","summary":"集団への印象を、温かさと能力の高さの二軸で考える理論。\n親しみやすさと、仕事を任せられそうかは別の印象として生まれる。集団のイメージで個人を決めず、具体的な行動から見直すためにも使える。","quotation":null},{"id":"kb_994","title":"道徳的切り離し","summary":"正当化や責任逃れによって、悪い行動への心の歯止めを外すこと。\n「皆もしている」「命令だった」と考え、相手への害を見えにくくする場合など。言い換えや責任の分散で、実際の行動が隠れていないか点検する。","quotation":null},{"id":"kb_995","title":"ルーピング効果","summary":"人への分類が本人の行動を変え、その変化が分類の意味にも戻ってくること。\nある呼び名で扱われた人が、その期待に合わせたり反発したりして、呼び名の理解まで変わる。分類を固定した説明ではなく、人との相互作用として見る。","quotation":null},{"id":"kb_996","title":"ラベリング理論","summary":"人に付いた呼び名や周囲の扱いが、その人の立場や行動を変えるという理論。\n「問題児」と呼ばれ続け、挑戦の機会まで減るような場面を考えられる。人そのものの評価と、今直したい行動を分けて伝える視点になる。","quotation":null},{"id":"kb_997","title":"スティグマ","summary":"ある特徴への偏見によって、その人全体が低く扱われること。\n病気や出身など、一つの情報から能力や人柄まで低く見られる場合など。特徴への先入観が、仕事や関係の機会を狭めていないかを見る。","quotation":null},{"id":"kb_998","title":"トマスの定理","summary":"人々が現実だと信じて動けば、その信念が現実の結果を生むという考え方。\n根拠の薄いうわさでも、人々が信じて店を避ければ売上に影響する。信じられていることと事実を区別しつつ、その信念が生む行動にも目を向ける。","quotation":null},{"id":"kb_999","title":"象徴的相互作用論","summary":"物事の意味は人とのやり取りで生まれ、その意味に沿って人は動くという考え方。\n同じ贈り物でも、相手との関係によって感謝にも負担にも感じられる。物や言葉の意味を固定せず、その場でどう受け取られたかを確かめる。","quotation":null},{"id":"kb_1000","title":"社会的表象理論","summary":"集団で共有するイメージや知識が、物事の理解を方向づけるという理論。\n同じ技術を「便利な道具」と見る集団も、「仕事を奪うもの」と見る集団もある。説明では、相手がすでに持つイメージを知ることが入口になる。","quotation":null},{"id":"kb_1001","title":"道徳的パニック","summary":"特定の人や出来事への不安が、報道や反応を通じて急激に膨らむこと。\n目立つ事件から、ある集団全体が危険だと語られる場面など。報道の勢いと実際の規模、誰が問題を定義しているかを分けて見る。","quotation":null},{"id":"kb_1002","title":"他者化","summary":"相手を「私たちとは違う人々」とみなし、共感や権利の外に置くこと。\n「あの人たちは普通の人とは違う」とまとめると、個人の事情が見えにくくなる。集団名だけで語らず、相手も生活を営む一人だと捉え直す。","quotation":null},{"id":"kb_1003","title":"共有現実理論","summary":"自分と相手が、同じように理解し感じていると実感すること。\n出来事について「自分もそう感じた」と確かめ合うと、理解への安心が生まれる。ただし二人が同意したことだけで、外の事実まで正しいと決まるわけではない。","quotation":null},{"id":"kb_1004","title":"相互独立的・相互協調的自己観","summary":"自分を、独立した個人として見るか、人との関係から見るかという違い。\n自分の希望を先に話す人も、周囲との調和から話す人もいる。どちらかを人柄の優劣にせず、何を判断の起点にしているかを知る手がかりにする。","quotation":null},{"id":"kb_1006","title":"社会的役割理論","summary":"行動の違いを、その人が担う社会的な役割や期待から考える理論。\n同じ人でも、責任者か参加者かで発言の仕方は変わる。性格だけを理由にせず、与えられた責任や周囲の期待も含めて行動を理解する。","quotation":null},{"id":"kb_017","title":"カクテルパーティー効果","summary":"騒がしい中でも、自分の名前など関心のある情報に気づけること。\n複数の会話がある場で、自分の名前だけ耳に入る場面など。注意はすべてに均等には向かないため、重要な連絡は呼びかけてから伝えると確認しやすい。","quotation":null},{"id":"kb_870","title":"ストループ効果","summary":"文字の意味が邪魔をして、文字の色を答えにくくなること。\n赤いインクの「青」という字で、意味と色の答えがぶつかる課題が典型例。資料では、色と文言が矛盾すると読み手の負担を増やすことを考えられる。","quotation":null},{"id":"kb_872","title":"非注意性盲目","summary":"一つのことに集中すると、目の前の別のものを見落とすこと。\n件数を数えることに夢中で、画面の目立つ変化に気づかない場面など。見えているはずと思わず、重要な確認は見る目的を切り替えて行う。","quotation":null},{"id":"kb_873","title":"変化盲","summary":"場面の切り替わりなどで、目の前の変化を見落とすこと。\n画面が切り替わる間に、配置や内容が変わっても気づかないことがある。変更を伝える際は、前後を並べたり、変わった場所を明示したりすると確かめやすい。","quotation":null},{"id":"kb_874","title":"注意の瞬き","summary":"一つの情報に注意した直後、続く情報を一時的に捉えにくくなること。\n数字が続けて現れる中で、最初の目標を捉えた直後の目標を見落とす課題など。大切な情報を一瞬に詰め込まず、受け取る間を置く視点になる。","quotation":null},{"id":"kb_738","title":"エビングハウスの忘却曲線","summary":"覚えたことは初めに多く忘れ、その後は忘れる速さが緩やかになるという関係。\n一度読んだ内容も、時間がたつとそのままには残らない。忘れ方は内容や学び方で違うため、決まった割合を当てはめず、思い出す練習で確かめる。","quotation":null},{"id":"kb_879","title":"検索誘導性忘却","summary":"ある情報を何度も思い出すと、関連する別の情報を思い出しにくくなること。\nよく話す出来事ばかり思い出し、同じ時期の別の経験が出にくくなる場合など。振り返りでは、いつもの話題に加えて違う手がかりも使ってみる。","quotation":null},{"id":"kb_739","title":"系列位置効果","summary":"順番に示された情報は、途中より最初と最後が記憶に残りやすいこと。\n長い説明の途中に置いた大切な条件は、印象が薄くなることがある。要点を最初に示し、最後に確認するなど、順番も伝え方の一部として考える。","quotation":null},{"id":"kb_744","title":"処理水準理論","summary":"形や音だけでなく、意味を深く考えるほど覚えやすいという理論。\n用語を眺めるだけでなく、「自分の生活ならどんな例か」を考える学び方など。丸暗記に意味や関連を加えると、取り出す手がかりを増やせる。","quotation":null},{"id":"kb_743","title":"符号化特定性原理","summary":"覚えたときの手がかりがあると、思い出しやすいという原理。\n誰とどこで話したかをたどると、内容を思い出せる場合など。覚えるときに、後で必要になる場面や問いも結びつけておくと使いやすい。","quotation":null},{"id":"kb_876","title":"誤情報効果","summary":"後から聞いた誤情報が、経験した出来事の記憶に混ざること。\n出来事の後に誘導的な質問をされ、聞いた内容を見たように思い出す場合など。大切な記録は、他人の説明を聞く前に、自分が見た範囲を書き残す。","quotation":null},{"id":"kb_877","title":"ソースモニタリング","summary":"覚えていることが、実体験、伝聞、想像のどこから来たかを確かめること。\n実際に聞いた約束なのか、自分がそうなると想像しただけかを振り返る場面など。内容とともに、いつ誰から知ったかも残すと混同を点検しやすい。","quotation":null},{"id":"kb_826","title":"文脈依存記憶","summary":"覚えたときと似た場所や環境では、思い出しやすくなること。\n忘れ物に気づき、元の部屋に戻ると思い出す場面など。思い出せないときは、内容だけを追わず、そのときの場所や手順もたどれる。","quotation":null},{"id":"kb_827","title":"状態依存記憶","summary":"覚えたときと似た体や気分の状態では、思い出しやすくなること。\n気分や体調も、記憶を呼び出す手がかりの一部になる場合がある。大事な内容は特定の状態だけに頼らず、複数の状況で思い出す練習をしておける。","quotation":null},{"id":"kb_878","title":"気分一致記憶","summary":"今の気分に合う過去の出来事を、思い出しやすくなること。\n落ち込んでいるときに、過去の失敗ばかり浮かぶ場面など。その時点で浮かぶ記憶だけで、人生全体の評価を決めないための手がかりになる。","quotation":null},{"id":"kb_742","title":"二重符号化理論","summary":"言葉とイメージを組み合わせると、記憶の手がかりが増えるという理論。\n道順を文章と簡単な地図で示すように、異なる手がかりを持たせる。絵を増やすこと自体より、言葉と図が同じ内容の理解を助けているかを見る。","quotation":null},{"id":"kb_746","title":"チャンク化","summary":"複数の情報を、意味のあるまとまりにして覚えること。\n電話番号を数桁ずつに区切るなど、意味や規則で情報をまとめる。初心者にはまとまりが見えにくいため、説明では分け方の理由も示すとよい。","quotation":null},{"id":"kb_441","title":"外部記憶","summary":"覚えるべき情報を、メモや記録など頭の外に残すこと。\n決定事項を議事録に残せば、人による記憶の違いも確かめられる。残すだけで安心せず、どこを見れば見つかるかまで決めておく。","quotation":null},{"id":"kb_831","title":"記憶の再固定化","summary":"思い出した記憶が、新しい情報の影響を受けて保存し直されること。\n思い出すたびに、その記憶が完全に同じ形で再生されるとは限らない。自信のある記憶でも、後から聞いた話が混ざっていないかを確かめる視点になる。","quotation":null},{"id":"kb_393","title":"自己関連づけ効果","summary":"自分の経験や関心に結びつけた情報ほど、覚えやすいこと。\n新しい理論を、最近の会話や自分の失敗に結びつけて読む場面など。身近な例を一つ持つと、用語だけより意味を取り出しやすい。","quotation":null},{"id":"kb_741","title":"生成効果","summary":"答えを読むだけより、自分で考えて出すほうが覚えやすいこと。\n解説を開く前に答えを予想し、その後で確かめる学び方など。間違いを直す時間も含め、自分で取り出す機会をつくる。","quotation":null},{"id":"kb_830","title":"転移適合処理","summary":"後で使う場面に近いやり方で学ぶと、成果が出やすいこと。\n会話で使いたい言葉なら、読むだけでなく実際に声に出して練習する。何を覚えたかに加え、どんな形で使う予定かから学び方を選べる。","quotation":null},{"id":"kb_493","title":"認知負荷理論","summary":"一度に頭で扱える量には限りがあり、情報が多すぎると理解を妨げるという理論。\n説明と操作を一度に大量に渡すと、内容が正しくても追いきれなくなる。手順を分け、不要な表示を減らし、覚えておく量を小さくする。","quotation":null},{"id":"kb_740","title":"フォン・レストルフ効果","summary":"並んだものの中で、一つだけ違うものが記憶に残りやすいこと。\n同じ書式の資料で一か所だけ色が違うと、その場所が目に残る。強調を増やしすぎると違いが消えるため、本当に重要な部分を絞る。","quotation":null},{"id":"kb_829","title":"流暢性の錯覚","summary":"すらすら読めることを、何も見ずに思い出せる力と取り違えること。\n見覚えのあるページを読んで「覚えた」と思っても、閉じると説明できない場合など。読み直した回数より、何も見ずに答えられるかを確かめる。","quotation":null},{"id":"kb_414","title":"連想ネットワーク","summary":"関連する記憶がつながり、一つから別の記憶を思い出すという考え方。\n相手の名前と趣味を一緒に覚えると、趣味の話題から名前が出てくる場合など。新しい知識を、すでに知る具体例と結びつける視点になる。","quotation":null},{"id":"kb_531","title":"ツァイガルニク効果","summary":"終えた作業より、途中で止めた作業が頭に残りやすいこと。\n終えていない連絡や作業が、別のことをしていても気になる場面など。次にする一歩を書き残すと、頭の中だけで抱え続けずに済む場合がある。","quotation":null},{"id":"kb_965","title":"注意資源理論","summary":"注意には限りがあり、作業を同時に抱えると出来が落ちるという考え方。\n会議を聞きながら難しい文章を書くと、両方の情報を取りこぼすことがある。集中が必要な作業は重ねず、切り替える時刻を決める方法が考えられる。","quotation":null},{"id":"kb_967","title":"注意残余","summary":"別の仕事に移っても前の仕事が頭に残り、集中しにくくなること。\nメールを途中で閉じても、返信のことを考え続けて仕事に戻れない場面など。切り替える前に、残りの作業や再開地点を短く記録しておく。","quotation":null},{"id":"kb_968","title":"注意の捕捉","summary":"今の目的とは別の音や光などに、注意を奪われること。\n通知音や点滅に気づくたび、読んでいた文章から意識が離れる場面など。集中したい時間は、目立つ合図が出る環境そのものを調整できる。","quotation":null},{"id":"kb_970","title":"選択的注意","summary":"多くの情報の中から、必要なものに注意を向けること。\n探し物の色や形を決めると、それに合うものが目に入りやすい。目的を持つ便利さと、目的外の情報を見落とす可能性の両方を意識する。","quotation":null},{"id":"kb_972","title":"スキーマ理論","summary":"経験でできた知識の枠組みが、新しいことの理解や記憶を助けるという理論。\n初めての店でも、知っている店の仕組みを頼りに利用する場面など。理解を助ける一方、新しい例にも前の型を当てはめすぎることがある。","quotation":null},{"id":"kb_973","title":"スクリプト理論","summary":"よくある出来事の流れを覚えておき、次を予測するという考え方。\n飲食店では、入店、注文、食事、会計という流れを予想して動く。慣れない手順を伝えるときは、いつもの流れと違う場所を先に示すと分かりやすい。","quotation":null},{"id":"kb_974","title":"展望記憶","summary":"予定していたことを、必要なタイミングで思い出すための記憶。\n帰りに品物を受け取る、約束の時刻に連絡するなどに使う。予定を覚えるだけでなく、場所や時刻に結びつけた通知を用意すると補える。","quotation":null},{"id":"kb_976","title":"舌先現象","summary":"知っている言葉を、もう少しで思い出せそうなのに思い出せない状態。\n人の名前が出なくても、最初の音や会った場所は思い出せる場合がある。無理に同じ探し方を続けず、別の手がかりをたどることができる。","quotation":null},{"id":"kb_978","title":"回想バンプ","summary":"人生を振り返ると、青年期から成人初期の経験を多く思い出すこと。\n初めての就職や恋愛など、その後の自分像に関わる経験が多い時期でもある。思い出の多さを、その時期だけが価値ある人生だったという判断に直結させない。","quotation":null},{"id":"kb_979","title":"偽記憶","summary":"実際にはない出来事や違う内容を、本当に覚えていると感じること。\n聞いた話や想像した場面を、自分が経験したと思い出すことがある。記憶の鮮明さだけを証拠にせず、記録や他の情報とも照らし合わせる。","quotation":null},{"id":"kb_980","title":"プルースト効果","summary":"においをきっかけに、過去の経験と当時の気持ちがよみがえること。\n昔使った香りや料理のにおいで、その頃の場所や人を思い出す場面など。言葉以外にも、自分の経験へつながる手がかりがあると分かる。","quotation":null},{"id":"kb_904","title":"最近接発達領域","summary":"一人では難しくても、助けがあればできる課題の範囲。\n少し助言があれば解ける課題に、支援を添えて取り組む場面など。全部代わりに行うより、どこまで一人ででき、どこで助けが必要かを見極める。","quotation":null},{"id":"kb_909","title":"社会的時計","summary":"就職や結婚などを、何歳ごろにするべきかという社会の期待。\n同年代の結婚や昇進を見て、自分は遅れていると感じる場面など。社会の目安と、自分の事情や望む順番を分けて考える。","quotation":null},{"id":"kb_910","title":"生涯発達理論","summary":"人の成長や変化は、子ども時代だけでなく生涯続くという考え方。\n年齢が上がっても、新しい役割や経験によって考え方や能力は変化する。得意なことが増える変化と、補う必要が出る変化の両方に目を向ける。","quotation":null},{"id":"kb_911","title":"選択・最適化・補償モデル","summary":"大切な目標を選び、力を集中し、できなくなったことを別の方法で補う考え方。\n体力が限られたら活動を絞り、経験を活かし、道具や支援で補う場面など。すべてを以前どおりに続ける以外の、目標の守り方を考えられる。","quotation":null},{"id":"kb_912","title":"社会情動的選択性理論","summary":"残された時間をどう感じるかで、人間関係に求めるものが変わるという理論。\n先が長いと感じると新しい出会いを、時間が限られると親しい関係を重視する場合がある。年齢だけで決めず、本人の時間の感じ方に目を向ける。","quotation":null},{"id":"kb_913","title":"成人形成期","summary":"青年期と安定した成人生活の間で、仕事や恋愛、自分の価値観を探る時期。\n仕事や住む場所を試しながら、どんな生活を望むかを探す時期として考える。誰もが同じ年齢で同じ経路を通るという基準ではない。","quotation":null},{"id":"kb_914","title":"生態学的システム理論","summary":"人の成長を、家庭や学校、職場、制度や文化との関わりから考える理論。\n本人への声かけだけでなく、家庭の事情や制度の使いやすさも行動に関わる。困り事を一人の性格へ閉じ込めず、周囲の条件も整理する。","quotation":null},{"id":"kb_915","title":"ライフコース理論","summary":"人生の道筋を、時代、出来事の時期、人とのつながり、本人の選択から考える理論。\n同じ転職でも、景気や家族の状況、起きた年齢によって意味は変わる。人生を努力だけで説明せず、時代と関係の中の選択として振り返る。","quotation":null},{"id":"kb_1011","title":"遅延満足","summary":"目先の小さな満足を待ち、後の大きな満足を選ぶこと。\n今すぐ動画を見るか、課題を終えてから楽しむかを選ぶ場面など。意志の強さだけに任せず、誘惑を遠ざけたり、待つ見通しをつくったりして支えられる。","quotation":null},{"id":"kb_918","title":"ヘッブの法則","summary":"繰り返し一緒に働く神経細胞同士は、結びつきが強まるという考え方。\n関連する情報を繰り返し一緒に扱うと、学びの結びつきが育つことを考える基礎になる。ただし「何回で脳が変わる」といった回数を直接決める法則ではない。","quotation":null},{"id":"kb_919","title":"長期増強","summary":"神経細胞の間で、情報が伝わりやすくなった状態が長く続くこと。\n経験によって神経のつながりの働きが変わる、学習の基礎として研究されている仕組み。覚えた手応えを、特定の神経変化として自分で判定できるわけではない。","quotation":null},{"id":"kb_920","title":"敏感期","summary":"ある経験が、能力の発達にとくに強く影響する時期。\n言語など、学ぶ経験を受けやすい時期を考える際に使う。時期を過ぎたら一切学べないという境界ではなく、その後の経験や支援も重要になる。","quotation":null},{"id":"kb_921","title":"睡眠と記憶の固定化","summary":"睡眠中に、学んだ記憶が整理され、安定していくこと。\n学んだ後の休息も、記憶を保つ過程の一部として捉える。夜更かしで詰め込む量だけを増やさず、学習と睡眠を含む予定を考える手がかりになる。","quotation":null},{"id":"kb_922","title":"アロスタティック負荷","summary":"ストレスへの体の対応が繰り返され、心身に負担が蓄積すること。\n緊張した場面が終わっても休めない生活では、回復する時間を取りにくい。忙しさの一時的な山だけでなく、負担と回復の積み重なりを見る言葉になる。","quotation":null},{"id":"kb_1012","title":"実行機能","summary":"目標に向けて、注意、記憶、衝動や行動を調整する力。\n途中の誘惑を抑え、必要な情報を保ち、予定が変われば手順を切り替える働きなど。段取りの困難は意欲だけで判断せず、メモや環境で補う余地も考える。","quotation":null},{"id":"kb_754","title":"限定合理性","summary":"情報や時間に限りがあるため、最善よりも十分と思える案を選ぶという考え方。\n店選びで全店を調べず、予算と場所を満たす店に決める場面など。調べる時間も負担に含め、十分な条件と探す期限を先に決めておける。","quotation":null},{"id":"kb_756","title":"期待効用理論","summary":"結果の起こる確率と得られる満足を合わせ、最も価値の高い案を選ぶという理論。\n同じ見込み額でも、確実さや失う痛みへの感じ方によって選択は変わる。金額や点数だけでなく、自分にとって結果が持つ価値を考える枠組み。","quotation":null},{"id":"kb_755","title":"期待値","summary":"起こり得る結果に確率を掛けて足した、平均的な見込みのこと。\n成功時の成果が大きくても、起こる可能性が小さければ平均の見込みは変わる。一回だけの結果を保証する数字ではなく、比較の材料として使う。","quotation":null},{"id":"kb_887","title":"ソマティック・マーカー仮説","summary":"経験に結びついた体の感覚が、選択の手がかりになるという考え方。\n以前失敗した案を前に、理由を言葉にする前に胸がざわつく場合など。感覚を無視せず、その反応につながった経験や現在との違いも確かめる。","quotation":null},{"id":"kb_895","title":"コミットメントのエスカレーション","summary":"悪い結果が出ても、自分で決めた方針にさらに時間やお金を注ぐこと。\n「自分の判断が間違いだった」と認めづらく、成果の出ない企画を拡大する場面など。続ける条件と見直す時点を、結果が出る前に決めておく。","quotation":null},{"id":"kb_176","title":"双曲割引","summary":"目前の利益を特別に重く見るため、時間が近づくと選択が逆転すること。\n来月のためなら待てても、今日もらえるものを前にすると気持ちが変わる場合など。未来の自分も今の計画を守れるよう、誘惑との距離を調整する。","quotation":null},{"id":"kb_758","title":"曖昧性回避／エルズバーグ・パラドックス","summary":"起こる確率が分からないものを、確率が分かるものより避けること。\n中身の割合が分かる箱と分からない箱なら、前者を選びたくなる場合など。危険が大きいのか、情報が足りなくて落ち着かないのかを分ける。","quotation":null},{"id":"kb_835","title":"アレのパラドックス","summary":"確実な結果を特別に重く見て、選択の基準が一貫しなくなること。\n確実にもらえる選択肢があるかどうかで、他の案との比べ方が変わることに注目する。条件を変えて比べ直すと、自分が確実さをどれほど重く見たかが分かる。","quotation":null},{"id":"kb_191","title":"意思決定疲れ","summary":"決断を繰り返して疲れ、楽な選択や先送りが増えること。\n細かな選択が続いた後に、大事な判断を先延ばしする場面など。毎回考えなくてよいことは手順化し、重要な判断には余裕のある時間を残す。","quotation":null},{"id":"kb_844","title":"確率無視","summary":"結果への恐怖や期待に引っぱられ、起こる確率を十分に考えないこと。\n怖い出来事を想像しただけで、起こりやすさに関係なく避けたくなる場面など。結果の重大さと発生の見込みを、別々に確かめる視点になる。","quotation":null},{"id":"kb_840","title":"希少性マインドセット／トンネリング","summary":"時間やお金が足りないと、目先の問題に集中し、他の大切なことを見落とすこと。\n目先の期限に追われ、次の準備や休息まで削ってしまう場面など。本人の注意力だけを責めず、余白や支援をつくる必要にも目を向ける。","quotation":null},{"id":"kb_713","title":"ギャンブラーの誤謬","summary":"偶然の結果が続くと、次は反対が出やすいと思うこと。\n公正なコインで表が続いても、次の裏が出やすくなるわけではない。前の結果が次に影響する仕組みか、独立した試行かを見分ける。","quotation":null},{"id":"kb_442","title":"顕示選好","summary":"本当の好みを、言葉だけでなく実際の選択から読み取る考え方。\n「学びたい」と話すことと、実際に時間を使う対象が違う場合など。ただし選択には予算や事情もあるため、行動一つで本音を決めつけない。","quotation":null},{"id":"kb_808","title":"行動バイアス","summary":"待つほうがよくても、何かしたい気持ちで行動を選ぶこと。\n結果を待つべき時期にも、不安から方針を何度も変える場合など。何もしない時間も選択肢に入れ、動けば何が改善するかを確かめる。","quotation":null},{"id":"kb_836","title":"識別可能な被害者効果","summary":"大勢の被害の数字より、顔や名前の分かる一人を助けたくなること。\n一人の体験談に強く心を動かされ、より多くの人への支援を見落とす場合など。共感を入口にしつつ、全体の必要性や届け方も考える。","quotation":null},{"id":"kb_839","title":"情報回避／オーストリッチ効果","summary":"不快さや対応の負担を避けるため、役立つ情報も見ないこと。\n未読の連絡や残額の確認を、怖くて後回しにする場面など。見ないことで短く安心できても、対応できる時間が減っていないかを振り返る。","quotation":null},{"id":"kb_807","title":"省略バイアス","summary":"同じ損害でも、何もせず起きた場合を、行動して起こした場合より軽く見ること。\n自分が提案して失敗するより、放置して同じ損が出るほうが責められにくく感じる場合など。動かない場合に何が起きるかも、比較の中へ入れる。","quotation":null},{"id":"kb_711","title":"生存者バイアス","summary":"成功して残った事例だけを見て、失敗して見えなくなった事例を数えないこと。\n成功者の習慣だけを集めても、同じ習慣で成功しなかった人は見えていない。残った事例と、途中で消えた事例を合わせて考える。","quotation":null},{"id":"kb_809","title":"ゼロリスク・バイアス","summary":"全体の危険を大きく減らすより、一つの危険を完全になくす案を好むこと。\n小さな危険をゼロにする案が、より大きな危険を減らす案より魅力的に見える場合など。安心の形だけでなく、全体で減る負担も比べる。","quotation":null},{"id":"kb_843","title":"分母無視","summary":"全体に対する割合より、目立つ個数だけで多さを判断すること。\n「十人が成功」と聞いても、試した人が百人か一万人かで意味は違う。人数を見たら、全体の数も一緒に確かめる。","quotation":null},{"id":"kb_714","title":"ホットハンド効果","summary":"成功が続くと、次も成功しやすい流れにあると感じること。\n連勝を見て勢いを感じても、それだけで次の成功確率は分からない。能力や条件が変わったのか、結果の並びに意味を読み込んだのかを分ける。","quotation":null},{"id":"kb_757","title":"メンタル・アカウンティング","summary":"同じ金額でも、入った経緯や使い道によって別のお金として扱うこと。\n臨時収入は気軽に使い、給料は慎重に使う場面など。お金に付けたラベルと、生活全体の収支を並べると、使い方の偏りを見直せる。","quotation":null},{"id":"kb_715","title":"連言錯誤","summary":"条件が増えた詳しい話のほうを、単純な話より起こりやすいと考えること。\n「会社員で、地域活動にも熱心な人」のほうが「会社員」より多くいるとは言えない。話の具体性や納得感と、条件の範囲の広さを区別する。","quotation":null},{"id":"kb_138","title":"アンカリング効果","summary":"最初に示された数字や情報を基準に、その後も判断すること。\n最初に見た高い価格が基準になると、その後の価格を割安に感じやすい。比較前に自分の予算や必要条件を持つと、提示された基準から距離を取れる。","quotation":null},{"id":"kb_137","title":"フレーミング効果","summary":"同じ内容でも、得する話か損する話かという示し方で選択が変わること。\n「成功率九割」と「失敗率一割」は同じ数字でも、受ける印象が違う。反対の表現に言い換えても、同じ選択になるかを確かめる。","quotation":null},{"id":"kb_140","title":"おとり効果","summary":"見劣りする比較用の選択肢が加わると、特定の案が魅力的に見えること。\n二つの案に、片方より明らかに不利な案が加わると、比較の基準が変わる。自分に必要な条件へ戻り、比較用の案に引っぱられていないかを見る。","quotation":null},{"id":"kb_141","title":"妥協効果","summary":"両極端を避け、真ん中の選択肢を無難だと感じること。\n大・中・小が並ぶと、中なら失敗しないと感じる場面など。真ん中という位置より、自分に必要な量や機能を先に決めて比べる。","quotation":null},{"id":"kb_136","title":"現状維持バイアス","summary":"変える利点があっても、今の選択をそのまま続けようとすること。\n使わない契約でも、手続きの面倒さから更新し続ける場合など。「今初めて選ぶとしても契約するか」と考えると、続ける理由を見直しやすい。","quotation":null},{"id":"kb_135","title":"保有効果","summary":"自分が持っているものを、持っていないときより高く評価すること。\n売る側では高く手放したくなり、買う側ではそこまで払いたくない場面など。愛着と、今必要な機能や他の選択肢の価値を分けて考える。","quotation":null},{"id":"kb_759","title":"確実性効果","summary":"「ほぼ確実」と「確実」の違いを、とくに大きく感じること。\nわずかな不確実さでも、完全な保証がなくなると大きく損に感じる場合がある。「確実」という言葉だけでなく、そのために何を差し出すかも比べる。","quotation":null},{"id":"kb_837","title":"IKEA効果","summary":"自分で手間をかけて完成させたものを、高く評価すること。\n組み立てた家具や、自分でまとめた資料に強い愛着を持つ場面など。手間をかけた実感と、使う人から見た品質を分けて点検する。","quotation":null},{"id":"kb_514","title":"希少性価値","summary":"手に入る量や機会が少ないものに、高い価値を感じること。\n限定品や少ない予約枠は、手に入れること自体が魅力になりやすい。少なさに気づいたら、もともと何に価値を感じていたかへ戻ってみる。","quotation":null},{"id":"kb_102","title":"希少性の原理","summary":"手に入りにくいほど、価値があると感じること。\n「残りわずか」という案内で、必要性を考える前に焦る場面など。買う側では、今しかないかどうかと、本当に欲しいかを別々に確かめる。","quotation":null},{"id":"kb_401","title":"限界効用逓減","summary":"同じものを得るほど、一つ増える喜びは小さくなりやすいという原理。\n一杯目の飲み物ほど、二杯目や三杯目に大きな喜びを感じない場合など。量を増やすだけでなく、種類やタイミングを変える余地も考えられる。","quotation":null},{"id":"theory-1789620805420-wbuepmtu","title":"ゴルディロックス効果","summary":"三段階の選択肢では、極端を避けて真ん中を選びやすいこと。\n小・中・大のプランで、中なら不足も無駄も少なそうと感じる場面など。真ん中が自分に合うかは、実際の使用量や予算で確かめる。","quotation":null},{"id":"kb_761","title":"支払いの痛み","summary":"お金を払うときに感じる、心理的な負担や不快感のこと。\n現金で払う場合と、後払いでまとめる場合では支出の実感が違うことがある。買う瞬間の負担感だけに頼らず、総額を見返す機会を持つ。","quotation":null},{"id":"kb_760","title":"ゼロ価格効果","summary":"無料になると、値下げ幅以上に魅力を感じて選びやすくなること。\n不要な物でも、無料と言われると受け取りたくなる場面など。代金以外にかかる時間、場所、手続きも含めて選ぶとよい。","quotation":null},{"id":"kb_521","title":"選択支持バイアス","summary":"自分で選んだものの長所を高く見て、選択を正当化すること。\n購入後に長所ばかり探し、比較していた品の欠点を強調する場合など。選ぶ前の条件を残しておくと、後の納得と実際の使い心地を比べられる。","quotation":null},{"id":"kb_897","title":"選択盲","summary":"自分の選択をすり替えられても気づかず、その理由まで説明すること。\n選んだ理由の説明は、後から作られる場合もあるという示唆がある。自分の記憶に頼りすぎず、大切な選択では選んだ対象と理由をその場で残す。","quotation":null},{"id":"kb_275","title":"選択のパラドックス","summary":"選択肢が多すぎると、迷いや後悔が増え、満足が下がること。\n候補を比べ続け、決めた後も他の案が気になる場面など。最初に必要条件で絞り、比較する数や期限を決めると選択の負担を減らせる。","quotation":null},{"id":"kb_139","title":"対比効果","summary":"同じものでも、直前に見たものとの違いで評価が変わること。\nとても高い商品を見た後では、普段なら高い商品も安く感じる場合など。並ぶ順番から離れ、共通の条件で比較し直す。","quotation":null},{"id":"kb_842","title":"単位バイアス","summary":"示された一つ分を適量と思い、その大きさに使う量が引っぱられること。\n大きな袋でも小さな袋でも、「一袋」が食べる量の目安になる場面など。使う量を変えたいときは、一回分として見える大きさも見直せる。","quotation":null},{"id":"kb_838","title":"ディドロ効果","summary":"新しく買ったものに合わせて、周りのものまで買い替えたくなること。\n新しい机に合わせて椅子や照明も買いたくなる場面など。追加の買い替えまで含む範囲を考え、最初の購入だけで判断しない。","quotation":null},{"id":"kb_1013","title":"左端数字効果","summary":"数字の左端の桁が変わると、実際以上に大きな差を感じること。\n千円と九百九十九円は一円差でも、千円未満という印象が生まれる。見た目の桁に加え、差額そのものを読み直すと比べやすい。","quotation":null},{"id":"kb_1014","title":"貨幣錯覚","summary":"物価の変化を考えず、お金の額面だけで価値を判断すること。\n収入の数字が増えても、物価がそれ以上に上がれば買える量は減る。額面の増減と、生活で使える実質的な量を分けて見る。","quotation":null},{"id":"kb_1015","title":"指数成長バイアス","summary":"一定の割合で増えるものの将来の増加を、小さく見積もること。\n利用者数や作業量が一定割合で増えると、後になるほど増分も大きくなる。直線での延長だけに頼らず、表や計算で先の量を確かめる。","quotation":null},{"id":"kb_1016","title":"顕著性バイアス","summary":"目立つ情報を重く扱い、目立たない重要な情報を見落とすこと。\n目立つ割引表示に注意を取られ、継続費用を見落とす場合など。大きく書かれた項目以外にも、選ぶうえで必要な条件を確認する。","quotation":null},{"id":"kb_1017","title":"選好逆転","summary":"同じ選択肢でも、選ぶか値段をつけるかで好みの順番が変わること。\n「どちらが欲しいか」と「いくらまで払うか」では、注目する特徴が違う場合がある。一つの聞き方で出た好みだけを、固定した本音と考えない。","quotation":null},{"id":"kb_1018","title":"リスク感情理論","summary":"危険の冷静な見積もりより、その場の不安が行動を左右するという理論。\n数字では小さい危険だと理解していても、鮮明な映像で強く避けたくなる場合など。感情を無視せず、見積もりと行動のずれがどこから来るかを見る。","quotation":null},{"id":"kb_1019","title":"参照価格効果","summary":"今の価格を、以前の価格や通常価格と比べて高いか安いか判断すること。\n通常価格の表示が高いと、今の価格がお得に見える。比較の基準が実際に使われた価格か、他の店ではどうかも確かめる。","quotation":null},{"id":"kb_1020","title":"分割価格効果","summary":"本体代と手数料などを分けて示すと、総額の感じ方や選択が変わること。\n料金本体が安く見えても、手数料や送料を加えると違う比較になる場合がある。最後に支払う総額と、必要な条件を同じ基準で並べる。","quotation":null},{"id":"kb_1021","title":"スノッブ効果","summary":"他の人が多く持つほど、そのものの魅力を感じなくなること。\n流行していると知って、かえって欲しくなくなる場面など。珍しさを求める気持ちと、品物の使いやすさや好みを分けて考える。","quotation":null},{"id":"kb_1022","title":"ヴェブレン効果","summary":"価格の高さ自体が、地位や豊かさを示す魅力になること。\n高い品を持つことが、品質以上に周囲へ何かを示す役割を持つ場合がある。価格が高いことと、自分にとって有用なことを分けて見る。","quotation":null},{"id":"kb_1023","title":"ディスポジション効果","summary":"利益が出たものは早く売り、損したものは取り戻すまで持ち続けること。\n「買った額に戻るまで待つ」という基準に、今後の判断が縛られる場合など。過去の購入額と、これから持つ理由を別々に考えるための言葉になる。","quotation":null},{"id":"kb_1024","title":"近視眼的損失回避","summary":"損失を嫌い、結果を頻繁に確かめるため、長期よりも慎重な選択に偏ること。\n短い間隔で結果を見ると、小さな下振れも何度も損として感じられる。目的の期間と、結果を見て評価する期間が合っているかを点検する視点になる。","quotation":null},{"id":"kb_1025","title":"確率マッチング","summary":"結果の出る頻度に合わせて、予想や選択の割合を分けること。\n左が七割当たる場面で、左を七割、右を三割選ぶような対応など。次の一回を当てたいのか、頻度を再現したいのかで望ましい選び方は変わる。","quotation":null},{"id":"kb_1038","title":"投影バイアス","summary":"今の好みや体の状態が、未来の自分にも続くと思うこと。\n空腹で買い物をして、後では食べきれない量を選ぶ場面など。未来の自分が置かれる時間や状態を、今と分けて想像する。","quotation":null},{"id":"kb_1039","title":"認識ヒューリスティック","summary":"片方だけを知っているとき、知っているほうが優れていると判断すること。\n聞いたことのある名前を、知らない名前より信頼してしまう場面など。知名度が何を示す情報なのか、その場面でも有効かを確かめる。","quotation":null},{"id":"kb_1040","title":"Take-the-bestヒューリスティック","summary":"重要な手がかりから比べ、最初に差がついたところで決める方法。\nまず安全性を比べ、差がなければ使いやすさを比べるように、順番を決める。速く選べる一方、後の条件の大きな違いを見落とさないかにも注意する。","quotation":null},{"id":"kb_1041","title":"側面ごとの消去法","summary":"大切な条件から順に、合わない選択肢を除いていく方法。\n住まい探しなら、予算、通勤時間、広さの順に候補を絞る方法など。必須条件と、妥協できる条件を最初に分けておくと使いやすい。","quotation":null},{"id":"kb_1042","title":"スラッジ","summary":"必要な行動を妨げる、過剰な手続きや分かりにくさ、待ち時間のこと。\n解約窓口が見つからない、同じ情報を何度も入力させるといった負担など。利用者が諦めたことを、不要だった証拠と考えないための視点になる。","quotation":null},{"id":"kb_1043","title":"不平等回避","summary":"自分が得でも損でも、相手との取り分の不公平を嫌うこと。\n取り分が多くても、不公平だと感じて分け直したくなる場合がある。利益の総量だけでなく、配分の基準や説明も納得感に関わる。","quotation":null},{"id":"kb_1044","title":"生態学的合理性","summary":"判断方法のよしあしを、複雑さよりも使う環境との相性で考えること。\n情報が少なく時間も短い場では、単純な目安のほうが役立つ場合もある。いつでも精密に考えるのではなく、その環境で誤りを減らせる方法を選ぶ。","quotation":null},{"id":"kb_750","title":"期待価値理論","summary":"やる気を、「できそうか」と「やる価値があるか」の組み合わせで考える理論。\n役立つと分かっていても、できる見込みが持てなければ始めにくい。意欲を促すには、目的を示すことと、最初の課題を取り組める大きさにすることを考える。","quotation":null},{"id":"kb_168","title":"期待理論","summary":"やる気を、努力が成果になる見込み、成果が報われる見込み、報いの魅力から考える理論。\n努力しても評価に反映されないと感じれば、報酬が魅力的でも意欲は出にくい。どのつながりが切れているかを分けて見ると、働きかけを考えやすい。","quotation":null},{"id":"kb_751","title":"時間的動機づけ理論","summary":"成功への期待、成果の魅力、衝動の強さ、締切までの時間から、やる気を考える理論。\n大切な課題でも、締切が遠いと目先の楽しみを選びやすい。小さな中間期限や、進んだ手応えを設けることで、遠い結果を今の行動へつなげられる。","quotation":null},{"id":"kb_183","title":"目標勾配効果","summary":"ゴールが近づくほど、そこへ向かう努力が強まること。\nスタンプが残り一個になると、利用する気持ちが強まる場面など。大きな目標を小さな区切りに分ければ、途中にも到達の見通しをつくれる。","quotation":null},{"id":"kb_260","title":"アイデンティティに基づく動機づけ","summary":"自分らしいと感じる行動ほど、実行しやすくなるという理論。\n「自分は学び続ける人だ」と感じると、短い勉強にも意味を持ちやすい。ただし一度できなかっただけで、その自分像全体を否定しないことも大切になる。","quotation":null},{"id":"kb_261","title":"希望理論","summary":"希望を、目標への道筋を考える力と、そこへ進もうとする意思で捉える理論。\n「頑張りたい」だけでなく、進み方と、行き詰まったときの別ルートを持つ。励ますときも、気合を求めるだけでなく、一緒に道筋を探せる。","quotation":null},{"id":"kb_833","title":"自己一致モデル","summary":"自分の関心や価値観に合う目標ほど、努力が続きやすいという考え方。\n他人への見栄で始めた目標と、自分が大切だと感じる目標では取り組み方が違うことがある。始める前に、なぜその目標を選ぶのかを言葉にする。","quotation":null},{"id":"kb_184","title":"新鮮なスタート効果","summary":"年始や誕生日などの区切りで、気持ちを切り替えて始めやすくなること。\n月曜や引っ越しを、以前の失敗と区切るきっかけにする場面など。区切りの高揚だけに頼らず、翌日も続ける小さな手順を決めておく。","quotation":null},{"id":"kb_185","title":"進捗原理","summary":"意味のある仕事が少しでも進むと、意欲や満足が高まるという原理。\n完成していなくても、難所が一つ解ければ次に進む気持ちが生まれる。振り返りでは残りの量だけでなく、今日進んだ点も記録する。","quotation":null},{"id":"kb_186","title":"小さな勝利","summary":"小さな達成を重ね、自信と次の行動への勢いを育てること。\n苦手な作業を一つ終えた経験が、次の挑戦の足場になる。達成の数を増やすだけでなく、大きな目的に近づいた点を確かめる。","quotation":null},{"id":"kb_170","title":"目標階層理論","summary":"日々の行動、中間の目標、大きな目的をつなげて考える理論。\n「資格を取る」の下に「毎週復習する」、上に「どんな仕事をしたいか」を置く考え方など。手段に行き詰まっても、上の目的から別の道を探せる。","quotation":null},{"id":"kb_188","title":"接近目標・回避目標","summary":"望む結果を得る目標と、望まない結果を避ける目標の違い。\n「間違えない」だけより、「要点を一つ伝える」と決めたほうが、することが明確になる場合がある。避けたい結果も確認しつつ、取る行動を言葉にする。","quotation":null},{"id":"kb_171","title":"制御理論","summary":"現在と目標の差を確かめ、その差を縮めるよう行動を調整するという理論。\n予定より遅れていると分かったら、作業量や期限を調整する場面など。目標を立てるだけでなく、途中の状態を確かめる仕組みも必要になる。","quotation":null},{"id":"kb_537","title":"フィードバックループ","summary":"行動の結果を見て、次の行動を修正する繰り返しのこと。\n説明して相手の反応を見て、分かりにくかった箇所を直す流れなど。結果を集めるだけでなく、次の行動へどう戻すかまで決めると働く。","quotation":null},{"id":"kb_832","title":"ゴール・シールディング","summary":"一つの目標に集中すると、競合する別の目標が意識に上りにくくなること。\n試験勉強に集中すると、別の誘いが気になりにくくなる場合など。集中は助けになる一方、休息や大切な用事まで見えなくなっていないかも点検する。","quotation":null},{"id":"kb_572","title":"目標調整理論","summary":"達成が難しい目標から離れ、新しい目標へ力を向けるという考え方。\n方法を変えても難しいなら、目標の規模や期限を見直す選択肢もある。諦めたかどうかだけでなく、浮いた力を何に向けるかまで考える。","quotation":null},{"id":"kb_539","title":"プロセス目標","summary":"結果だけでなく、続ける行動や手順を目標にすること。\n「評価される」ではなく、「提出前に一度確認する」を目標にする場面など。自分で実行できる行動を決め、結果とのつながりを後から振り返る。","quotation":null},{"id":"kb_834","title":"エピソード的未来思考","summary":"未来の出来事を具体的に想像し、今の選択や計画に活かすこと。\n来週の朝、どこで何をしているかまで思い描くと、必要な準備に気づける。望む結果だけでなく、途中で困りそうな場面も含めて想像する。","quotation":null},{"id":"kb_1026","title":"意図と行動のギャップ","summary":"やるつもりでいることと、実際に行動することの間にある隔たり。\n読みたい本があっても、置き場所や始める時刻が決まらず手が伸びない場合など。意思を強くするだけでなく、行動の直前に何が欠けているかを見る。","quotation":null},{"id":"kb_1027","title":"計画的行動理論","summary":"行動への考え、周囲の期待、できる感覚が、実行の意思をつくるという理論。\n運動をよいと思っても、周囲の協力や実行できる場所がなければ意思は育ちにくい。態度、期待、できる感覚のどこが壁かを整理する。","quotation":null},{"id":"kb_535","title":"文脈依存習慣","summary":"時間や場所、直前の行動などが合図になって、習慣が起こること。\n朝の飲み物を用意したら本を開くなど、日常の合図と行動が結びつく。続けたい習慣には、毎回考えなくても始められる同じきっかけを置ける。","quotation":null},{"id":"kb_541","title":"アイデンティティ・ベース習慣","summary":"続けたい行動を、なりたい自分の姿に結びつける方法。\n「本を一冊読む」だけでなく、「毎日少し読む人でありたい」と位置づける。大きな宣言より、その姿に合う小さな行動を繰り返す。","quotation":null},{"id":"kb_534","title":"連続性原理","summary":"続けやすく、中断しても戻りやすい流れを整えること。\n忙しい日は短い版に切り替え、翌日に戻れる形を用意する。毎日同じ量を守ることより、完全にやめず再開できる仕組みとして考える。","quotation":null},{"id":"kb_178","title":"選択アーキテクチャ","summary":"選択肢の並べ方や初期設定など、選ぶ環境を設計すること。\n申込画面の順番や初期設定も、人の選びやすさを変える。望む行動を促す際は、他の選択肢も分かりやすく選べるようにしておく。","quotation":null},{"id":"kb_528","title":"環境デザイン","summary":"物や情報の配置を変え、望む行動を起こしやすくすること。\n読みたい本を机に置き、気になる通知は見えなくする工夫など。意志が弱いと責める前に、手を伸ばしやすい物や情報を変えられる。","quotation":null},{"id":"kb_177","title":"デフォルト効果","summary":"変更できても、最初から選ばれた設定をそのまま使いやすいこと。\n登録時の設定を、その後も見直さず使う場面など。利用する側は初期設定を確認し、設計する側は意図と変更方法を分かりやすく示す。","quotation":null},{"id":"kb_438","title":"刺激統制","summary":"行動のきっかけになる刺激を調整し、その行動を増減させること。\n寝る前に動画を見続けるなら、寝床に端末を持ち込まないなどの工夫がある。行動の最中だけを我慢するより、始まる合図を探して調整する。","quotation":null},{"id":"kb_943","title":"フォッグ行動モデル","summary":"行動は、やる気、実行のしやすさ、きっかけがそろうと起きるという理論。\nやる気があっても、手順が難しかったり思い出す合図がなければ動きにくい。行動が起きないとき、三つの条件のどれを補うかを考える。","quotation":null},{"id":"kb_1028","title":"習慣不連続性仮説","summary":"環境が変わると習慣の合図が途切れ、行動を見直しやすくなるという考え方。\n引っ越しで通る道が変わると、立ち寄る店も変わる場合など。環境の節目に、新しい合図と続けたい行動を組み直せる。","quotation":null},{"id":"kb_1029","title":"行動の波及効果","summary":"一つの行動の変化が、別の行動にも影響すること。\n歩く習慣が他の健康行動にもつながる場合も、満足して別の行動を減らす場合もある。一つの成功だけで判断せず、その後の生活全体を確かめる。","quotation":null},{"id":"kb_1030","title":"社会規範フィードバック","summary":"自分の行動と、周囲の実態や望ましい基準との違いを知らせる方法。\n自分の利用量を同じ条件の人と比べると、見直す目安になる。実態の説明が、好ましくない行動を「皆もしている」と正当化させないかにも注意する。","quotation":null},{"id":"kb_1032","title":"COM-Bモデル","summary":"行動を、能力、機会、動機の三つから考える理論。\n学びが続かないなら、やり方を知る力、使える時間、やる理由を分けて点検する。「やる気がない」の一言で終えず、補える条件を探す。","quotation":null},{"id":"kb_1034","title":"健康信念モデル","summary":"健康への行動を、危険の感じ方、行動の利点、負担から考える理論。\n行動の利点を知っていても、費用や時間の負担が大きければ始めにくい。危険を強調するだけでなく、本人が感じる壁や実行のきっかけを確かめる。","quotation":null},{"id":"kb_1035","title":"保護動機理論","summary":"身を守る意欲は、脅威の大きさと、対処できる見込みで変わるという理論。\n怖さだけを強めても、どう対処するか分からなければ行動につながらないことがある。伝える際は、具体的な対応と、実行できる条件も一緒に示す。","quotation":null},{"id":"kb_1036","title":"健康行動プロセスアプローチ","summary":"健康行動を、始めたいと思う段階と、計画して続ける段階に分ける考え方。\n始める理由ができた後も、いつどこで行い、途切れたらどう戻るかの計画が要る。意欲をつくる支援と、継続を助ける支援を分けて考える。","quotation":null},{"id":"kb_536","title":"オペラント条件づけ","summary":"行動の後の結果によって、その行動を繰り返しやすくなる学習のこと。\n行動の後に感謝されると、その行動を続けやすくなる場面など。何を意図したかだけでなく、実際にどの行動が増えたかを確かめる。","quotation":null},{"id":"kb_900","title":"古典的条件づけ","summary":"二つの刺激が結びつき、片方だけでも反応が起きるようになること。\nいつも緊張する場で聞く音に、音だけでも身構えるようになる場合など。現在の反応を、その場の意味だけでなく過去の結びつきからも理解する。","quotation":null},{"id":"kb_437","title":"強化理論","summary":"行動の後の報酬や不利益が、その行動を増減させるという理論。\n丁寧に引き継いだ行動へ具体的な感謝を返すなど、望む行動に応答する。相手にとって何が報いになるかは違うため、反応を見ながら考える。","quotation":null},{"id":"kb_440","title":"消去理論","summary":"行動を支えていた報酬や反応がなくなると、行動も減るという理論。\n反応が得られなくなると、これまで繰り返した行動が減る場合がある。危険な行動や困っている人の訴えまで、無視すればよいと一般化しない。","quotation":null},{"id":"kb_048","title":"間欠強化","summary":"ときどきしか報われないために、かえって行動をやめにくくなること。\n返信が来るか分からないほど、何度も画面を確かめる場合など。自分を引きつける仕組みを知り、確認する時刻や距離を選び直す視点になる。","quotation":null},{"id":"kb_735","title":"観察学習／社会的学習理論","summary":"他人の行動と結果を見ることで、自分も学ぶという理論。\n先輩の対応を見て、使える言い回しや手順を覚える場面など。結果だけをまねず、どんな状況で何を判断したかまで聞くと応用しやすい。","quotation":null},{"id":"kb_201","title":"望ましい困難","summary":"学ぶときの適度な難しさが、長期の理解や記憶を助けること。\n少し間を空けて思い出すなど、すぐ答えが見えない練習を取り入れる。難しければよいわけではなく、解ける足場と答え合わせが必要になる。","quotation":null},{"id":"kb_747","title":"インターリービング効果","summary":"異なる種類の問題を交ぜて練習すると、見分ける力や応用力が育つこと。\n似た問題を交ぜると、何の方法を使うかから自分で見分ける必要がある。同じ型を繰り返す練習と合わせ、方法を選ぶ練習をつくれる。","quotation":null},{"id":"kb_748","title":"自己説明効果","summary":"学んだ理由や手順を自分の言葉で説明し、理解を深めること。\n「なぜこの手順なのか」「前に知ったこととどうつながるか」を話してみる。言葉が止まった場所が、読み直すべき点を見つける手がかりになる。","quotation":null},{"id":"kb_049","title":"消去バースト","summary":"いつもの報酬や反応がなくなると、直後は一時的に行動が激しくなること。\n反応が変わった直後の激しさだけで、その後も同じ状態だと決まるわけではない。ただし対人場面で危険があるときは、我慢せず安全や支援を優先する。","quotation":null},{"id":"kb_415","title":"精緻化リハーサル","summary":"新しい情報を、知っていることや具体例と結びつけて覚えること。\n用語の意味を、自分の経験や似た知識と結びつけて説明する練習など。単に何度も眺めるより、後で思い出す入口を増やすことを目指す。","quotation":null},{"id":"kb_828","title":"プロテジェ効果","summary":"人に教えるつもりで学んだり実際に教えたりすると、理解が深まること。\n教える相手を想定すると、説明の抜けや曖昧な理解に気づきやすい。教えた後は質問や資料で確かめ、自分の誤解まで広めないよう見直す。","quotation":null},{"id":"kb_945","title":"馴化","summary":"同じ刺激を繰り返すうちに、反応が弱くなること。\n繰り返し聞く通知に、だんだん反応しなくなる場面など。合図を強く増やすだけでなく、重要な通知と普段の通知を分ける視点になる。","quotation":null},{"id":"kb_946","title":"鋭敏化","summary":"強い刺激を経験した後、他の刺激にも強く反応するようになること。\n強い驚きの後に、小さな物音にも身構える場面など。反応を大げさだと責めず、直前の経験や落ち着ける環境も含めて理解する。","quotation":null},{"id":"kb_947","title":"学習性勤勉さ","summary":"努力が報われる経験から、別の課題でも粘り強くなるという理論。\n工夫して課題を終えた経験が、次の難しい課題に取り組む支えになる。努力の量だけを褒めず、使えた方法や進歩にも具体的に応答する。","quotation":null},{"id":"kb_948","title":"足場かけ","summary":"一人では難しい課題を支え、上達に合わせて助けを減らす方法。\n最初は見本やヒントを示し、できる部分が増えたら本人へ任せていく。助けを固定するのでなく、自力で進める範囲に合わせて調整する。","quotation":null},{"id":"kb_1031","title":"行動形成（シェイピング）","summary":"目標に少し近づくたびに報い、まだできない行動を育てる方法。\nいきなり完成を求めず、近づいた行動に具体的な反応を返す。何が進歩かを小さく定め、達成に合わせて次の段階へ移る。","quotation":null},{"id":"kb_766","title":"職務満足","summary":"仕事内容や待遇、人間関係をどう評価するかから生まれる、仕事への満足感。\n仕事内容は好きでも、待遇や関係への不満で満足できない場合がある。転職や改善を考える際は、仕事全体を一括りにせず、何に満足し何が負担かを分ける。","quotation":null},{"id":"kb_767","title":"従業員エンゲージメント","summary":"仕事に活力や熱意を感じ、深く打ち込んでいる状態。\n今の待遇への満足だけでなく、仕事に力を注げる感覚に注目する。熱意の高さを長時間労働と同じにせず、支援や休息を含めて続けられる状態を見る。","quotation":null},{"id":"kb_763","title":"職務要求資源モデル","summary":"仕事の負担と、それを支える裁量や援助の釣り合いから、消耗と意欲を考える理論。\n忙しさが同じでも、手伝いを頼めるか、進め方を選べるかで消耗は違う。負担を減らす工夫と、使える支えを増やす工夫を両方考える。","quotation":null},{"id":"kb_907","title":"職務要求度・コントロールモデル","summary":"仕事の要求が大きく、自分で決める余地が少ないほど負担が強まるという理論。\n厳しい期限に追われ、手順も選べない仕事では身動きが取りにくい。仕事量だけでなく、順番や方法を決める余地も改善の対象になる。","quotation":null},{"id":"kb_540","title":"回復理論","summary":"休息や仕事から離れる時間によって、消耗した心身が回復するという考え方。\n休みの日にも仕事の連絡を追い続けると、仕事から気持ちを離しにくい。時間の長さに加え、緊張を解ける過ごし方や連絡の区切りを考える。","quotation":null},{"id":"kb_772","title":"資源保存理論","summary":"大切なものを失うことや、失いそうなことがストレスを生むという理論。\n収入だけでなく、時間、自信、頼れる人の喪失も負担になる。疲れた状態でさらに余裕を失う循環に気づき、守るものと助けを借りる部分を整理する。","quotation":null},{"id":"kb_130","title":"ジョブ・クラフティング","summary":"仕事の内容、人との関わり、意味づけを自分で調整し、働きやすくすること。\n担当の範囲で手順を工夫したり、相談する相手を増やしたりする方法など。一人で仕事を増やすのでなく、役割や周囲への影響も共有しながら調整する。","quotation":null},{"id":"kb_805","title":"キャリア構築理論","summary":"仕事の経験に意味を与えながら、自分の働く道をつくっていくという理論。\n一見ばらばらな仕事でも、「人の困り事を整理する」など共通の関心を見つけられる。経歴の見栄えだけでなく、経験を今後へどうつなぐかを考える。","quotation":null},{"id":"kb_806","title":"キャリア・アンカー","summary":"仕事を選ぶときに譲れない、自分の価値観や能力、動機の軸。\n専門を深めたい、生活を安定させたい、自由に働きたいなど、譲れない点は人で違う。選択肢の比較前に、失うと納得しにくい条件を確かめる。","quotation":null},{"id":"kb_804","title":"社会的認知キャリア理論","summary":"仕事への興味や選択を、できる感覚、結果への期待、目標から考える理論。\n興味があっても、自信や身近な機会が足りず選ばない仕事もある。向いていないと結論づける前に、試せる経験や支援を増やす余地を見る。","quotation":null},{"id":"kb_131","title":"キャリア資本理論","summary":"知識、技能、人脈、評判の蓄積が、働く道を支えるという考え方。\n身につけた技能と、それを知る人や実績の記録が、次の機会の足場になる。経験を積むだけでなく、何ができるようになったかを伝えられる形に残す。","quotation":null},{"id":"kb_868","title":"境界なきキャリア","summary":"一つの組織にとどまらず、職場や職種を越えて経験を積む働き方のこと。\n異動、転職、副業などを通じて、経験や人脈を別の場でも活かす。移動の自由には条件の差もあるため、動くこと自体を成功の基準にはしない。","quotation":null},{"id":"kb_292","title":"クランボルツの社会的学習理論","summary":"仕事の選択は、本人の特徴、環境、学習経験の組み合わせで決まるという理論。\n偶然任された仕事で得意なことに気づくなど、経験から関心や選択が変わる。最初から適職を当てようとするだけでなく、小さく試して学ぶ余地を持つ。","quotation":null},{"id":"kb_120","title":"自己宣伝のジレンマ","summary":"実績を伝えないと評価されず、強く伝えると自慢に見えるという悩み。\n「自分は優秀」とまとめるより、担った役割、工夫、結果を具体的に伝える方法がある。周囲への感謝と、自分の貢献の説明は両立できる。","quotation":null},{"id":"kb_765","title":"組織コミットメント","summary":"組織に愛着を持ち、関わり続けようとする気持ち。\n好きだから残る場合と、離れる負担が大きくて残る場合では意味が違う。在籍の長さだけで判断せず、何が関係を支えているかを確かめる。","quotation":null},{"id":"kb_585","title":"転移可能スキル","summary":"職場や職種が変わっても使える技能のこと。\n説明力、課題の整理、調整力などは、異なる仕事にも活かせることがある。職名だけでなく、実際に行った行動と得た技能の単位で経験を振り返る。","quotation":null},{"id":"kb_867","title":"プロティアン・キャリア","summary":"自分の価値観を軸に、学び方や働き方を更新する考え方。\n会社が用意する昇進だけでなく、自分が望む生活や学びを基準に進路を考える。価値観を軸にしながら、使える機会や生活の条件とも照らし合わせる。","quotation":null},{"id":"kb_940","title":"努力報酬不均衡モデル","summary":"努力に対して、報酬や承認、雇用の安定が少ないとストレスが増すという理論。\n高い負担が続くのに感謝や見通しも得られないと、働き続ける意味を失いやすい。賃金だけでなく、承認や安定も含めて釣り合いを見る。","quotation":null},{"id":"kb_777","title":"共有メンタルモデル","summary":"仕事の目的や役割、進め方を、チームで共通に理解していること。\nトラブル時に誰が連絡し、誰が判断するかを互いに分かっている状態など。言葉だけで合意せず、具体的な場面を想定して理解のずれを確かめる。","quotation":null},{"id":"kb_087","title":"トランザクティブ・メモリー","summary":"「誰が何を知っているか」を共有し、集団で記憶や知識を分担すること。\n全員が同じことを覚える代わりに、詳しい担当者や記録の場所を共有する。「誰に聞けばよいか」が分かることも、チームの知識になる。","quotation":null},{"id":"kb_065","title":"集団極性化","summary":"話し合いによって、集団の意見がもとより極端になること。\n似た意見ばかり話し合うと、慎重な人も大胆な結論へ寄る場合がある。異なる情報を先に集め、反対理由を検討する機会を設ける。","quotation":null},{"id":"kb_074","title":"期待状態理論","summary":"能力への期待が発言や活躍の機会を変え、さらに期待を強めるという理論。\n期待される人に難しい仕事が集まり、その経験でさらに能力が見える場面など。最初の期待が、経験を積む機会の差を生んでいないかを見る。","quotation":null},{"id":"kb_454","title":"社会的促進","summary":"人に見られると、慣れた作業はよくでき、難しい作業は失敗しやすくなること。\n慣れた演奏は人前で力が出ても、練習中の操作は焦って崩れる場合など。公開の場で試すか、落ち着いて練習するかを習熟度に合わせて考える。","quotation":null},{"id":"kb_455","title":"集団規範","summary":"集団の中で共有される、望ましい振る舞いや許されないことの基準。\n会議での発言や休みの取り方には、明文化されていない基準もある。新しく入った人の戸惑いを、本人の理解不足だけにせず、暗黙の期待を共有する。","quotation":null},{"id":"kb_453","title":"集団規模効果","summary":"人数によって、発言のしやすさや責任感、親密さが変わること。\n人数が増えると、一人の発言時間や互いに気づく機会も変わる。会議や相談の目的に合わせ、全体で話す部分と小人数に分ける部分を選べる。","quotation":null},{"id":"kb_069","title":"少数派影響","summary":"少数でも一貫した意見を示すことで、多数派の考えが変わること。\n同じ懸念を理由とともに示し続けることで、後から論点が見直される場合がある。頑固に繰り返すだけでなく、相手の問いに応じる柔軟さも必要になる。","quotation":null},{"id":"kb_771","title":"従業員の発言行動","summary":"組織をよくするため、自分から提案や懸念、異論を伝えること。\n現場で気づいた無駄や危険を、改善のために伝える行動など。発言を促す側は、受け取った後の応答や不利益の有無まで整える。","quotation":null},{"id":"kb_773","title":"変革型リーダーシップ","summary":"理想や仕事の意味を示し、仲間の意欲や成長を引き出すリーダーシップ。\n何をするかに加え、「なぜこの仕事が大切か」を共有する。理想を語るだけでなく、個々の成長や問い直す機会にも配慮する。","quotation":null},{"id":"kb_774","title":"取引型リーダーシップ","summary":"目標と報酬を明確にし、確認や修正を通じて成果を導くリーダーシップ。\n達成する基準や役割を明確にし、結果を確認して応答する。報酬だけを強くすると数字のための行動も増え得るため、望む成果の定義が大切になる。","quotation":null},{"id":"kb_845","title":"サーバント・リーダーシップ","summary":"権力を振るうより、仲間を支え、その成長を助けるリーダーシップ。\nメンバーの障害を取り除き、必要な情報や機会を届ける関わりなど。何でも代わりに引き受けるのでなく、本人が力を発揮できる条件をつくる。","quotation":null},{"id":"kb_775","title":"状況対応型リーダーシップ","summary":"相手の技能や意欲に合わせ、指示と支援の量を変える考え方。\n初めての仕事には具体的な手順を、慣れた仕事には裁量を多くする方法など。相手を固定的に分類せず、その課題で今どんな助けが必要かを確かめる。","quotation":null},{"id":"kb_893","title":"フィードラーのコンティンジェンシー理論","summary":"リーダーのよしあしは、その人の特徴と状況の相性で変わるという理論。\n指示が通りやすいか、仕事が明確かなどの条件で、同じリーダーの働き方も変わる。人選だけでなく、その人が力を発揮できる状況を整える発想につながる。","quotation":null},{"id":"kb_776","title":"パス・ゴール理論","summary":"目標への道を示し、障害を減らし、相手に合う支援をするという理論。\n優先順位が曖昧なら整理し、手順が分からないなら具体的に示す。励ますだけでなく、目標に向かう途中のどこが障害かを確かめる。","quotation":null},{"id":"kb_125","title":"リーダー・メンバー交換理論","summary":"上司と部下の一対一の関係が、得られる情報や機会を左右するという理論。\n上司と話す機会が多い人ほど、情報や挑戦を得やすくなる場合がある。信頼を深めることと、機会を公平に渡す仕組みの両方を考える。","quotation":null},{"id":"kb_598","title":"心理的契約","summary":"書かれた契約とは別に、会社や上司と交わしたと本人が感じる約束。\n「頑張れば育ててもらえる」と期待していたのに、機会がなく不信を感じる場合など。口にしていない期待も、節目に確かめ合うとすれ違いに気づける。","quotation":null},{"id":"kb_127","title":"組織支援理論","summary":"組織から大切にされている実感が、愛着や貢献意欲を高めるという理論。\n困ったときに事情を聞いてもらえる経験が、組織への信頼の土台になる。制度があるだけでなく、必要なときに実際に使えるかを見る。","quotation":null},{"id":"kb_118","title":"組織市民行動","summary":"決められた役割を越えて、同僚や組織を自発的に助ける行動。\n新しい同僚を手伝う、共有場所を整えるといった行動など。自発的な助け合いを、断れない暗黙の義務に変えない配慮も必要になる。","quotation":null},{"id":"kb_770","title":"組織沈黙","summary":"問題に気づいていても、危険や無駄を感じて、集団で発言を控えること。\n「言っても変わらない」と思うと、現場の問題が上へ届かなくなる。発言者の勇気だけに頼らず、受け止め方と改善の返答を整える。","quotation":null},{"id":"kb_506","title":"組織学習","summary":"個人の経験を共有し、組織の手順や仕組みを変えていくこと。\n一人だけが知る失敗を、チェック方法や引き継ぎの改善へつなぐ。報告を集めるだけで終えず、次の行動や仕組みに残すところまで含める。","quotation":null},{"id":"kb_892","title":"ダブルループ学習","summary":"やり方だけでなく、その目的や前提まで問い直して学ぶこと。\nミスを減らす確認を増やすだけでなく、その作業自体が必要かを問う場面など。「うまくやる方法」と「何をすべきか」の両方を学び直す。","quotation":null},{"id":"kb_894","title":"ゴミ箱モデル","summary":"問題、解決策、参加者、決定の機会が、偶然結びついて組織の決定が生まれるという理論。\n先に考えていた解決策が、たまたま開かれた会議の議題と結びつく場合など。意思決定を合理的な順番だけで捉えず、参加者や時機にも注目する。","quotation":null},{"id":"kb_507","title":"標準化","summary":"やり方や基準をそろえ、結果のばらつきや判断の手間を減らすこと。\n毎回一から迷わないよう、引き継ぎの項目や確認順をそろえる。例外が出たときに対応できる余地と、基準を更新する手順も持っておく。","quotation":null},{"id":"kb_497","title":"統制範囲","summary":"一人の管理者が、直接見て支えられる部下や仕事の範囲。\n仕事の複雑さや支援する相手の経験によって、見られる人数は変わる。人数の多さだけで管理力を測らず、必要な対話や判断に時間を使えるかを見る。","quotation":null},{"id":"kb_510","title":"信頼性理論","summary":"仕組みが、一定の間、求める働きを保てるかを考える理論。\n一部分がよく動いても、別の部分の故障で全体が止まる場合がある。個々の性能だけでなく、故障のつながりや代わりの手段も含めて設計する。","quotation":null},{"id":"kb_846","title":"心理的所有感","summary":"法的に持っていなくても、「自分たちのもの」と感じること。\n自分が育てた企画や共有の場所に、責任や愛着を持つ場面など。大切にする気持ちが、他の人の参加や改善を拒む方向へ向かっていないかも見る。","quotation":null},{"id":"kb_516","title":"知識共有","summary":"経験や手順、判断の基準を、他の人も使えるように伝えること。\n手順書には、何をするかとともに、迷いやすい条件や失敗例も残せる。受け手が使ってみて、分からなかった部分を更新すると共有が実用になる。","quotation":null},{"id":"kb_456","title":"文化的適合理論","summary":"自分の価値観や振る舞いと、組織の文化との相性を考える理論。\n丁寧な相談を好む人が、即断を求める場で疲れるような場合など。能力がないと決める前に、評価される行動や意思決定の習慣との相性を見る。","quotation":null},{"id":"kb_195","title":"目標代替","summary":"本来の目的より、測りやすい数字や手段を優先すること。\n学びのための読書で、内容より冊数だけを追う場面など。指標が増えたことと、本来ほしかった変化が起きたことを分けて見る。","quotation":null},{"id":"kb_508","title":"目標置換","summary":"目的のためのルールや指標が、守ること自体を目的にしてしまうこと。\n利用者を助ける手続きが、書類をそろえることのために本人を待たせる場合など。ルールを守ったかに加え、その目的が果たせたかを確かめる。","quotation":null},{"id":"kb_768","title":"分配的公正","summary":"報酬や負担、機会の分け方が、公平だと感じられること。\n同じ成果でも配分が違うと、不公平さが不満につながる場合がある。結果の差をなくすことだけでなく、何を基準に分けたかを説明できるかを見る。","quotation":null},{"id":"kb_769","title":"相互作用的公正","summary":"決定を伝えるとき、敬意と誠実な説明をもって扱われること。\n希望が通らなくても、事情を聞かれ理由を説明されると、納得の余地が残る。決定の中身と、その過程でどう扱われたかの両方に配慮する。","quotation":null},{"id":"kb_132","title":"ピーターの法則","summary":"昇進を重ねた結果、得意ではない役割まで任されるという考え方。\n優秀な担当者が、未経験の管理職でも同じように活躍できるとは限らない。昇進を報酬だけにせず、役割の違いと準備の機会を考える。","quotation":null},{"id":"kb_129","title":"人・職務適合理論","summary":"能力や望みと、仕事の要求や条件が合うほど、成果や満足が高まるという理論。\n話す力が高い人でも、一人で細かく検証する仕事が合うとは限らない。強みと担当業務の条件を並べ、配置や支援を見直す手がかりになる。","quotation":null},{"id":"kb_128","title":"人・組織適合理論","summary":"自分の価値観と組織文化が合うほど、満足し、続けやすいという理論。\n同じ仕事内容でも、競争を重んじる場か協力を重んじる場かで働きやすさは違う。会社の理念だけでなく、日々どんな行動が評価されるかを見る。","quotation":null},{"id":"kb_584","title":"人的資本","summary":"知識、技能、経験、健康など、自分が成果を生む土台となる力。\n資格の数だけでなく、経験から判断できることや、働き続ける健康も土台になる。今の成果と、将来も使える力の蓄積を分けて振り返れる。","quotation":null},{"id":"kb_571","title":"人的資本論","summary":"学習や経験、健康への取り組みを、将来の働く力への投資と見る理論。\n学びに使う時間や費用と、その後に広がる仕事や選択肢を考える。収入だけで価値を決めず、使える場面や本人の望む生活とも照らし合わせる。","quotation":null},{"id":"kb_395","title":"特性称賛と過程称賛","summary":"能力そのものを褒めることと、工夫や努力の過程を褒めることの違い。\n「才能があるね」と「説明の順番を工夫したね」では、何が評価されたかが違う。本人が次にも使える行動を具体的に伝えると、再現の手がかりになる。","quotation":null},{"id":"kb_501","title":"アウトカム評価","summary":"行った量より、実際に生まれた変化や結果で効果を評価すること。\n研修を何回行ったかに加え、現場で何ができるようになったかを見る。結果は環境にも左右されるため、活動量と変化の両方を残すと検討しやすい。","quotation":null},{"id":"kb_509","title":"インセンティブ設計","summary":"報酬や評価、権限を工夫し、望む行動が選ばれやすくすること。\n件数だけを評価すると、難しい案件を避ける行動が増える場合がある。人に頑張ってほしい方向と、得になる行動が一致するかを確かめる。","quotation":null},{"id":"kb_116","title":"可視性バイアス","summary":"目立つ成果を高く評価し、準備や予防など見えにくい貢献を軽く見ること。\n起きた問題を解いた人は目立ち、問題を防いだ人は見えにくい。準備、保守、相談対応など、成果になる前の仕事も記録して評価に含める。","quotation":null},{"id":"kb_117","title":"成果帰属問題","summary":"共同の成果から、誰がどれだけ貢献したかを切り分けにくいこと。\n発表した人だけでなく、調査や調整を担った人も成果を支えている。役割を途中から共有しておくと、最後に手柄の印象だけで決めずに済む。","quotation":null},{"id":"kb_491","title":"強み理論","summary":"弱点の修正だけでなく、得意なことを活かすほうへ力を向ける考え方。\n苦手をすべて平均へ直すより、得意を使える役割に時間を配る。最低限必要な弱点への対処と、強みを伸ばすことを組み合わせて考える。","quotation":null},{"id":"kb_119","title":"能力・好感トレードオフ","summary":"能力を強く示すと冷たく、親しみを強く示すと能力が低く見える場合があること。\n強い主張をする際に相手への関心も示せば、伝わる印象は変わり得る。固定した二者択一とせず、実績と配慮を具体的な行動で伝える。","quotation":null},{"id":"kb_941","title":"心理的エンパワーメント","summary":"仕事に意味があり、自分で選べ、力を発揮し、結果に影響できると感じること。\n裁量があっても、仕事の意味や結果への手応えがなければ力を感じにくい。任せる側は、権限とともに目的、情報、相談先も渡す。","quotation":null},{"id":"kb_942","title":"センスメイキング","summary":"曖昧な出来事を、話し合いや行動から理解できる形にしていくこと。\n予想外の失敗が起きたとき、手がかりを持ち寄り、何が起きたかを組み立てる。最初の説明を正解と固定せず、次の行動から得た情報で更新する。","quotation":null},{"id":"kb_081","title":"社会関係資本","summary":"信頼、人脈、助け合いなど、人とのつながりから得られる資源。\n知り合いの人数だけでなく、頼める関係や情報が届くつながりも資源になる。必要なときだけ利用するより、普段の小さな協力を大切にする。","quotation":null},{"id":"kb_085","title":"ネットワーク中心性","summary":"人間関係の網の中で、どれほど中心的な位置にいるかということ。\n知り合いが多い、違う集団をつなぐなど、中心的である形には違いがある。目立つ人だけでなく、情報がどこを通って届くかを見る。","quotation":null},{"id":"kb_083","title":"構造的空隙","summary":"つながっていない集団の間を結ぶ位置が、情報や交渉の強みになること。\n別々の部署を知る人が、片方の課題にもう片方の知識を結びつける場面など。情報を独占するより、違いを理解して橋渡しする価値に注目する。","quotation":null},{"id":"kb_084","title":"ブローカー理論","summary":"異なる人や集団を仲介し、価値や影響力を得るという理論。\n専門家と依頼者をつなぎ、互いの言葉を訳す役割など。紹介だけでなく、期待や条件の食い違いを整えることも仲介の価値になる。","quotation":null},{"id":"kb_086","title":"コア・ペリフェリー構造","summary":"集団を、密につながる中心と、つながりの薄い周辺から捉える考え方。\n中心では情報が共有されやすく、周辺には別の視点や情報がある場合もある。中心に入ることだけでなく、周辺から意見が届く経路も大切になる。","quotation":null},{"id":"kb_466","title":"ネットワーク冗長性","summary":"人脈が多くても、同じ情報や同じ人に重なってつながっていること。\n同じ職場の仲間が増えても、届く話題は似たままという場合など。関係の数と、異なる経験や情報への入口の数を分けて見る。","quotation":null},{"id":"kb_090","title":"ゴシップ理論","summary":"第三者についての会話が、評判や協力相手の判断に役立つという考え方。\n誰が約束を守るかを知る手がかりになる一方、誤ったうわさや排斥も広げ得る。伝聞を事実と混ぜず、本人の行動で確かめる視点を持つ。","quotation":null},{"id":"kb_113","title":"評判形成理論","summary":"直接の経験や伝聞、過去の行動から、その人への評判ができるという理論。\n一度の大きな成果だけでなく、締切や連絡を守る小さな行動も評判をつくる。伝わった印象と実際の記録がずれたら、具体的な事実で補う。","quotation":null},{"id":"kb_512","title":"評判ネットワーク","summary":"評価が、人同士の会話や紹介を通じて広がる仕組み。\n直接会わない相手にも、紹介者を通じて印象が届く。よい評判も悪い評判も変形し得るため、話の出所や実際の接点を確かめる。","quotation":null},{"id":"kb_465","title":"社会的埋め込み","summary":"取引や選択は、既存の信頼や人間関係の中で行われるという考え方。\n同じ条件の依頼でも、以前に協力した相手を選ぶ場面など。合理的な条件比較と、人間関係が生む安心や偏りの両方を見る。","quotation":null},{"id":"kb_088","title":"信用獲得理論","summary":"集団への貢献や実績が、後に独自の行動を認めてもらう信用になること。\n日頃の貢献が見えていれば、新しい提案や異論も受け取られやすい場合がある。信用は無制限の許可ではなく、他者への配慮とともに扱う。","quotation":null},{"id":"kb_126","title":"スポンサーシップ理論","summary":"有力者が推薦や後押しをして、本人の機会を広げるという考え方。\n助言をする人に加え、機会のある場へ推薦してくれる人の存在に注目する。後押しを受ける際は、何を任され、どんな期待があるかを確かめる。","quotation":null},{"id":"kb_089","title":"特異性信用","summary":"集団への貢献によって得られる、多少の独自性を認めてもらう信用。\n役割を果たしてきた人の新しいやり方が、試す価値のある提案として受け取られる場合など。貢献の蓄積と、独自の行動が許容される範囲の関係を見る。","quotation":null},{"id":"kb_091","title":"評判カスケード","summary":"初めの評判が人から人へ伝わり、根拠以上に強まること。\n皆が同じ一件を聞いているだけでも、多くの証言があるように見えることがある。評価の数を数える前に、それぞれ独立した経験かを確かめる。","quotation":null},{"id":"kb_467","title":"役割限定性","summary":"人との関係が、特定の仕事や役割の中に限られていること。\n同じ案件が終わると、それまで頻繁に会っていた人との接点も減る場合など。関係を続けたいなら、役割以外の関心や交流の機会も大切にできる。","quotation":null},{"id":"kb_079","title":"権力依存理論","summary":"相手の持つものに頼るほど、その相手の力が強くなるという理論。\n仕事の紹介を一人に頼りきると、その人の依頼を断りにくくなる。関係を壊すか従うかの前に、他の情報源や選択肢を増やす余地を探す。","quotation":null},{"id":"kb_075","title":"地位特性理論","summary":"年齢や学歴などが、実力とは別に、発言力や地位に影響するという理論。\n詳しい人より、年長者の意見が先に採用される場面など。発言者の属性と、その課題で持っている知識を分けて扱う。","quotation":null},{"id":"kb_076","title":"地位一般化","summary":"一つの分野の高い評価が、別の分野の評価にまで広がること。\n優れた研究者だから、経営や私生活の助言も正しいと感じる場合など。その評価はどの範囲の実績によるものかを確かめる。","quotation":null},{"id":"kb_445","title":"権力の脱抑制","summary":"権力を持つと周囲への警戒が弱まり、欲求や偏見が行動に出やすくなること。\n断られにくい立場になると、自分の頼みが相手の負担だと気づきにくい。権限を持つ側ほど、断る余地や異論が届く経路を意識する。","quotation":null},{"id":"kb_513","title":"代替可能性","summary":"ある人や資源を、他の選択肢で置き換えられる度合い。\n他にも頼める人や調達先があれば、一つの関係への依存を減らせる。代わりがいるかだけでなく、切り替えに必要な時間や品質も考える。","quotation":null},{"id":"kb_518","title":"代替困難性","summary":"技能や知識、関係の組み合わせが特別で、簡単に置き換えられないこと。\n技能だけでなく、現場の事情と人を知る組み合わせが強みになる場合など。価値を高めることと、情報を抱え込んで組織を困らせることは区別する。","quotation":null},{"id":"kb_077","title":"マタイ効果","summary":"すでに評価や資源のある人ほど、さらに機会を得やすくなること。\n有名な人に依頼が集まり、実績がさらに増える場面など。現在の実績だけを比較すると、機会の得やすさの差を見落とすことがある。","quotation":null},{"id":"kb_078","title":"累積優位","summary":"小さな初めの差が、機会や資源の偏りで大きく育つこと。\n最初に得た経験が次の仕事を呼び、その差が後から大きくなる。結果の差を才能だけで説明せず、どんな機会が重なったかも振り返る。","quotation":null},{"id":"kb_474","title":"非言語的地位表示","summary":"姿勢や視線、空間の使い方などで、地位や自信を示すこと。\n広く場所を使う、落ち着いて視線を向けるといった振る舞いが手がかりになる場合がある。文化や状況で意味が違うため、一つの姿勢で地位や性格を決めない。","quotation":null},{"id":"kb_847","title":"組織的両利き","summary":"今ある強みを磨くことと、新しい可能性を探ることを両立する力。\n既存の仕事を改善する時間と、新しい方法を試す時間を両方確保する。短期の効率だけで試行を止めず、試行のために本業を崩さない配分を考える。","quotation":null},{"id":"kb_850","title":"コア・コンピタンス","summary":"他社がまねしにくく、複数の仕事で価値を生む中核の強み。\n単一の商品ではなく、複数の製品に活きる設計力や顧客理解などを指す。今売れている物と、その裏で価値を生む力を分けて捉える。","quotation":null},{"id":"kb_848","title":"資源ベース理論","summary":"価値があり、希少で、まねされにくい資源が、競争の強みになるという理論。\n知識、信頼、仕組みなど、他では簡単に得られない組み合わせが強みになり得る。持っているだけでなく、現在の課題に価値を生むかを確かめる。","quotation":null},{"id":"kb_849","title":"ダイナミック・ケイパビリティ","summary":"変化に気づき、機会をつかみ、組織の資源を組み替える力。\n顧客の変化を見つけ、試し、既存の役割や資源を組み直す流れなど。変化に反応するだけでなく、動き直せる仕組みがあるかを見る。","quotation":null},{"id":"kb_197","title":"制約理論","summary":"全体の成果を妨げる一番の制約を見つけ、集中して改善する考え方。\n確認待ちが全体を止めているなら、他の作業を速めても成果は増えにくい。制約を見つけて改善し、次にどこが詰まるかを再び確かめる。","quotation":null},{"id":"kb_196","title":"ボトルネック理論","summary":"全体の進み具合は、最も処理が遅い部分に制限されるという考え方。\n準備は早く終わっても、承認が一か所に集まれば全体が滞る。個々人の忙しさより、仕事が待っている場所を見つけることが入口になる。","quotation":null},{"id":"kb_527","title":"取引費用理論","summary":"取引には価格以外にも、探索、交渉、確認などの費用がかかるという理論。\n安い依頼先でも、探す時間や説明、確認の手間を含めると負担が大きい場合がある。見積額だけでなく、やり取り全体に必要な手間を比べる。","quotation":null},{"id":"kb_854","title":"規模の経済","summary":"規模を大きくすることで、一つ当たりの費用が下がること。\n設備や準備の費用を、多くの製品で分け持つと単価を下げられる。規模を増やせば常に有利とは限らず、調整や保管の負担も含めて見る。","quotation":null},{"id":"kb_855","title":"範囲の経済","summary":"複数の仕事で資源を共有すると、別々に行うより費用を抑えられること。\n同じ設備や配送網を、複数の商品で活かす場面など。種類を増やす利点と、複雑になって管理が増える負担を合わせて比べる。","quotation":null},{"id":"kb_783","title":"ネットワーク効果","summary":"利用する人が増えるほど、他の利用者にも価値が増すこと。\n連絡アプリは、連絡したい相手も使っているほど便利になる。利用者数そのものより、誰と何ができるようになるかに価値の理由を見る。","quotation":null},{"id":"kb_852","title":"メトカーフの法則","summary":"人同士がつながれる組み合わせが増えるほど、ネットワークの価値が高まるという考え方。\n人数が増えると接点の組み合わせも大きく増える、という見方を示す。すべてのつながりが等しく有益とは限らず、実際の交流の質も重要になる。","quotation":null},{"id":"kb_593","title":"機会認識","summary":"変化や満たされていない必要に気づき、自分が動ける機会を見つけること。\n皆が仕方ないと受け入れている不便に、改善の入口を見つける場面など。気づいた仮説を小さく確かめ、誰がどの程度困っているかを知る。","quotation":null},{"id":"kb_853","title":"経験曲線／学習曲線","summary":"経験を重ねるほど、作業時間や一つ当たりの費用が下がること。\n繰り返すうちに手順が定まり、確認や作業にかかる時間が減る場面など。回数だけで上達すると考えず、何を学び直したかも見る。","quotation":null},{"id":"kb_519","title":"スラック資源","summary":"通常の仕事を回す最低限を超えた、時間や人員、資金などの余裕。\n予定の空きや予備の人員があれば、急な問題や新しい試みに対応しやすい。使われていないものをすべて無駄とせず、備えの役割も評価する。","quotation":null},{"id":"kb_110","title":"プリンシパル＝エージェント理論","summary":"頼む側と任される側の目的や情報が違い、行動のずれが生まれるという理論。\n依頼者は品質を求めても、担当者は評価される件数を優先する場合など。相手の善意だけに頼らず、目標、情報、評価のずれを共有する。","quotation":null},{"id":"kb_543","title":"リーン・スタートアップ","summary":"小さく試し、結果から学び、続けるか変えるかを決めて事業を育てる方法。\n完成品を大きく作る前に、必要な価値だけを試して反応を見る。「何を確かめる試みか」と、次の判断に使う結果を先に決めておく。","quotation":null},{"id":"kb_109","title":"情報の非対称性","summary":"取引や関係の当事者で、知っている情報に差があること。\n売る側は修理歴を知っていても、買う側には見えないといった場面など。相手が知る範囲と、自分が確認できる範囲を整理することが取引の入口になる。","quotation":null},{"id":"kb_107","title":"シグナリング理論","summary":"見えない能力や意図を、行動や資格など見える手がかりで伝えるという理論。\n口で「丁寧」と言うだけでなく、見本や過去の仕事で示す場面など。手がかりが実力と本当に結びついているかを、受け取る側も確かめる。","quotation":null},{"id":"kb_108","title":"スクリーニング","summary":"条件や選択肢を示し、相手の選び方から性質や能力を見分ける方法。\n実技課題や複数のプランから、何ができ何を重視するかを知る方法など。試す条件が、見たい能力以外の事情で不利を生まないかも考える。","quotation":null},{"id":"kb_800","title":"逆選択","summary":"相手の質を見分けられないため、望ましくない相手が取引に残りやすくなること。\n品質の違いが価格に反映されないと、よい品を出す側が離れる場合など。誰が残る仕組みかを考え、情報の確かめ方や条件を整える。","quotation":null},{"id":"kb_801","title":"モラルハザード","summary":"行動が見られず、損を他人に負わせられるため、慎重さが失われること。\n本人が結果の負担を負わず、過程も確かめられないと、行動のずれが起きやすい。人格を責める前に、情報、責任、評価の仕組みを点検する。","quotation":null},{"id":"kb_802","title":"レモン市場","summary":"品質を見分けられない市場では、よい品が減り、取引が縮むという理論。\n買い手が低い品質を警戒して価格を下げると、よい品の売り手が離れる流れ。記録や保証など、品質を確かめられる仕組みの意味が分かる。","quotation":null},{"id":"kb_717","title":"平均への回帰","summary":"極端によい結果や悪い結果の後は、普段の水準に近づきやすいこと。\nたまたま非常によかった成績が、次にはいつもの水準へ戻ることがある。間に行った叱責や助言だけを、変化の原因と早合点しない。","quotation":null},{"id":"kb_545","title":"パレートの法則","summary":"成果や問題の大部分が、少数の原因に集中するという経験則。\n問い合わせの多くが、少数の分かりにくい手順から生まれている場合など。比率を決めつけず、実際の件数から力を注ぐ場所を探す。","quotation":null},{"id":"kb_449","title":"ベースレート思考","summary":"個別の印象だけでなく、一般にどれほど起こるかも判断に入れること。\n目立つ一人の成功例を見る前に、同じ条件の人は普段どれくらい成功するかも見る。個別の事情を、全体の割合と合わせて判断する。","quotation":null},{"id":"kb_570","title":"ベイズ更新","summary":"新しい証拠を得るたびに、それまでの見込みを修正すること。\n最初の予想を守り続けず、新しい情報がどれほど確かかを見て見込みを変える。一件の強い印象で全てを逆転させず、情報の重さに応じて更新する。","quotation":null},{"id":"kb_825","title":"再認主導意思決定モデル","summary":"熟練者が経験のある型を見つけ、思いついた案を頭で試して決めるという理論。\n経験のある人が、似た状況を見て最初の対応案を絞る場面など。慣れた型が使える環境かを確かめ、違う条件では立ち止まることも必要になる。","quotation":null},{"id":"kb_154","title":"客観的基準","summary":"市場価格や共通のルールなど、当事者の言い分と独立した判断の基準。\n報酬を話し合うなら、相場、担当範囲、過去の実績などを並べる。「自分はこうしたい」だけの押し合いを減らすため、どの基準を使うかも合意する。","quotation":null},{"id":"kb_522","title":"統合型交渉","summary":"互いの優先順位の違いを活かし、双方の得を増やす交渉。\n一方は金額を、他方は期限を重視するなら、組み合わせで合意の余地が生まれる。要求の表面だけでなく、なぜその条件が大切かを尋ねる。","quotation":null},{"id":"kb_151","title":"パッケージ交渉","summary":"複数の条件をまとめて扱い、全体で譲歩と獲得を調整する方法。\n金額だけを争わず、期限、範囲、回数を含む案として比較する。条件を一つずつ決めるより、双方が重視するものを交換しやすくなる。","quotation":null},{"id":"kb_152","title":"MESO","summary":"自分には同じくらい価値のある複数案を示し、相手の好みを探る方法。\n短納期で範囲を絞る案と、余裕を持って範囲を広げる案などを示す。押しつけるためでなく、相手の優先順位を知って調整する材料にする。","quotation":null},{"id":"kb_153","title":"条件付き合意","summary":"将来の条件ごとに対応を先に決めて、今の合意をつくること。\n結果の予想が違うなら、「この条件ならこうする」と分けて決める方法がある。後でもめないよう、条件を確かめる方法と時点も明らかにする。","quotation":null},{"id":"kb_161","title":"調停理論","summary":"中立の第三者が対話を助け、当事者による合意を目指す考え方。\n当事者だけでは感情的になる話を、第三者が整理し、互いの希望を確認する。解決を押しつける役割と、本人たちの合意を助ける役割は区別する。","quotation":null},{"id":"kb_156","title":"二重関心理論","summary":"対立への対応を、自分の利益と相手の利益への関心で考える理論。\n押し通す、譲る、避ける、歩み寄る、協力するなど、複数の対応を比べられる。いつも同じ対応を選ぶより、重要性と関係に合う方法を考える。","quotation":null},{"id":"kb_486","title":"公正フレーミング","summary":"提案を、自分の得ではなく、双方に公平な基準から説明すること。\n負担を頼む際に、全員に共通の順番や条件を示す場面など。「公平」と呼ぶだけでなく、基準が相手にも自分にも同じように適用されるかを確かめる。","quotation":null},{"id":"kb_524","title":"限界点シグナリング","summary":"譲れない条件や撤退の線を、言葉や行動で相手に伝えること。\n受けられる範囲を「この期日までなら対応できる」と具体的に伝える。実行できない脅しを重ねるより、守れる線と代わりの案を示す。","quotation":null},{"id":"kb_145","title":"固定パイ・バイアス","summary":"相手の得は自分の損だと思い、双方の得を増やす余地を見落とすこと。\n金額の取り合いだと思っていても、相手は支払時期を重視しているかもしれない。譲れない部分と変えられる部分を尋ね、利害の違いを探す。","quotation":null},{"id":"kb_160","title":"デエスカレーション","summary":"対立の激しさを抑え、冷静に話せる状態へ戻すこと。\n声を落とす、いったん休む、論点を一つに戻すなどの対応がある。正しさの決着を急ぐ前に、安全に話せる条件を整える。","quotation":null},{"id":"kb_146","title":"反応的価値下げ","summary":"対立する相手が出した案だからという理由で、価値を低く見ること。\n同じ提案でも、味方から聞くとよく見え、対立相手から聞くと疑う場合など。誰が出したかを一度外し、案の条件だけで比べ直す。","quotation":null},{"id":"kb_159","title":"面子保存","summary":"自分や相手の面子を傷つけず、話し合いの余地を守ること。\n相手が訂正できる言い方や、人前を避けた確認の場を選ぶ。誤りを隠すのでなく、認めた後に関係を続けられる余地を残す。","quotation":null},{"id":"kb_515","title":"比較優位","summary":"他の活動を諦める負担が、相対的に小さい分野に持つ強み。\n両方の作業で得意な人でも、より大きな成果を失わずに担える役割は違う。作業単体の上手さだけでなく、分担した全体の成果を考える。","quotation":null},{"id":"kb_289","title":"ロックイン効果","summary":"切り替えの手間や慣れのため、今の製品や仕組みから離れにくくなること。\nデータ移行や使い方の覚え直しが重く、今の道具を使い続ける場合など。導入時には、便利さとともに、出力や移行のしやすさも確かめられる。","quotation":null},{"id":"kb_476","title":"相互抑止","summary":"攻撃すれば不利益が返ると互いに分かり、攻撃を控えること。\n双方が限界と結果を理解していることで、逸脱を控える状況を考える。脅しを強めれば安全になるとは限らず、誤解を減らす対話も必要になる。","quotation":null},{"id":"kb_525","title":"勝者の呪い回避","summary":"競争に勝てたこと自体が、価値を高く見積もりすぎた兆候だと考えること。\n価値が不確かな競りで、一番高い見積もりの人が勝つ状況など。勝つことを目的にせず、上限や前提を事前に決めておくための視点。","quotation":null},{"id":"kb_791","title":"支配戦略","summary":"相手が何を選んでも、他の案以上の利益になる戦略。\n相手の反応を一つに決めず、各場合で選択肢を比較して確かめる。現実には、そのような一つの最善手がない状況も多い。","quotation":null},{"id":"kb_790","title":"ナッシュ均衡","summary":"相手が今の選択を続けるなら、自分だけ変えても得にならない状態。\n双方が今の対応を変えない状態でも、全員にとって望ましいとは限らない。動きにくさの理由を、個人の意思だけでなく互いの利害から考える。","quotation":null},{"id":"kb_864","title":"サブゲーム完全均衡","summary":"どの途中段階から考え直しても、選び直す理由のない戦略の組み合わせ。\n実際にその段階へ来れば実行しない脅しを、計画から取り除く考え方。先の宣言より、各時点で本当に何を選ぶかを確かめる。","quotation":null},{"id":"kb_792","title":"後方帰納法","summary":"最後に起きることから逆にたどり、今の選択を考える方法。\n最後に相手がどちらを選ぶかを考え、そこへ進む前の自分の行動を選ぶ。現実では相手の情報や感情も違うので、推測の前提は残しておく。","quotation":null},{"id":"kb_796","title":"協調ゲーム","summary":"選択が互いにそろうこと自体に、利益がある状況。\n連絡手段や集合場所をそろえることは、どちらの案か以上に価値がある場合がある。よい案を争う前に、合わせる基準や決め方を共有する。","quotation":null},{"id":"kb_797","title":"スタグハント","summary":"協力すれば大きく得られるが、相手への不安から小さな安全を選ぶ状況。\n大きな共同作業も、相手が参加する確信がなければ一人で済む案へ戻りやすい。段階的に約束を確かめ、協力の見通しをつくることを考えられる。","quotation":null},{"id":"kb_165","title":"チキンゲーム","summary":"双方が譲らないと最悪になるが、先に譲るのも不利に見える対立。\n双方が「先に譲れば負け」と考えると、争いを止める入口がなくなる。勝敗の言い方から離れ、同時に引ける条件や第三の案を探す。","quotation":null},{"id":"kb_798","title":"最後通牒ゲーム","summary":"一方が取り分を提案し、他方が拒めば双方とも何も得られない実験のこと。\n少しでも得になる提案でも、不公平だと感じれば拒まれる場合がある。分け方の判断には金額だけでなく、尊重や公平感も関わることが分かる。","quotation":null},{"id":"kb_799","title":"公共財ゲーム","summary":"皆に利益が返る共通の仕組みに、各自がどれだけ出すかを考える実験のこと。\n各自は出さずに利益だけ受け取りたいが、それが重なると全体の利益が減る。負担の見え方や、協力が続くルールを考えるための枠組み。","quotation":null},{"id":"kb_794","title":"共通知識","summary":"全員が知り、その事実を全員が知っていることも互いに理解している状態。\n全員の前で変更を確認すると、「他の人も変更を知っている」と分かる。個別に伝えた情報と、互いの理解まで共有できた状態の違いに注目する。","quotation":null},{"id":"kb_863","title":"パレート効率性","summary":"誰かを悪くせずに、他の人をさらによくする余地がない状態。\n改善の余地がないことと、配分が公平なことは同じではない。全体の無駄を減らす議論と、誰がどれだけ得るかの議論を分ける。","quotation":null},{"id":"kb_865","title":"メカニズム・デザイン","summary":"各自が自分の得を選んでも、望む結果につながるルールを考える理論。\n本音を隠すほうが得な仕組みなら、正直さを頼むだけでは変わりにくい。情報の出し方や報い方を変え、望む行動が選びやすい条件を考える。","quotation":null},{"id":"kb_866","title":"オークション理論","summary":"競りのルールや情報が、価格や参加者の戦略をどう変えるか考える理論。\n入札が見えるか、価格をどう決めるかで、同じ品でも参加者の振る舞いは変わる。競争の結果だけでなく、その結果を生むルールを見る。","quotation":null},{"id":"kb_778","title":"共有地の悲劇","summary":"皆が自分の利益のために使いすぎ、共通の資源を損なうこと。\n共有の予算や場所を、各自が少しずつ使いすぎる場面など。資源が共通でも、利用の基準や相談の仕組みを持てば、協力して守る余地はある。","quotation":null},{"id":"kb_166","title":"コミットメント戦略","summary":"自分の選択肢をあえて狭め、本気度を伝えて相手の行動を変える戦略。\n期限や使える手段を自分で決めることで、方針を変えにくくする。引き返す余地も失うため、本気に見せることより、条件が変わった場合の負担を考える。","quotation":null},{"id":"kb_793","title":"シェリングの焦点","summary":"相談できなくても、共通の習慣や目立つ特徴から同じ選択に集まること。\n場所を詳しく決められなくても、目立つ入口に集まると予想する場面など。共通の手がかりが違えば外れるため、連絡できるなら明確に確認する。","quotation":null},{"id":"kb_780","title":"集合行為問題","summary":"共通の利益があっても、各自が負担を避けるため協力できないこと。\n全員が望む改善でも、誰が時間を出すか決まらず進まない場合など。目的への賛成と、必要な役割や負担を引き受ける仕組みを分けて考える。","quotation":null},{"id":"kb_779","title":"フリーライダー問題","summary":"自分は費用を負担せず、他の人が生んだ利益だけを得ようとすること。\n共有の片づけをいつも同じ人に任せるような場面など。協力しない人を責めるだけでなく、負担の見える化や無理のない分担を整える。","quotation":null},{"id":"kb_555","title":"リスク・オブ・ルイン","summary":"損失によって基盤を失い、活動を続けられなくなる危険。\n一度の失敗で生活や次の活動の土台まで失うなら、平均的な得だけでは判断できない。続けられなくなる結果を、他の損と区別して扱う。","quotation":null},{"id":"kb_542","title":"破滅回避","summary":"取り戻せない損失を避け、次も挑戦できる状態を守ること。\n一度で全力を使い切らず、生活や再挑戦の余地を残しておく。小さな損まで避け続けることとは分け、どこまでなら回復できるかを考える。","quotation":null},{"id":"kb_286","title":"撤退戦略","summary":"どの条件でやめるか、縮小するかを先に決めておくこと。\n成果が出なければいつ見直すかを、感情が強くなる前に決める。やめた後の引き継ぎや残す資源まで考えておくと、判断を実行に移しやすい。","quotation":null},{"id":"kb_281","title":"冗長性","summary":"予備や別の経路を持ち、一部の失敗でも全体を保てること。\n連絡先の予備や、担当者が不在でも使える手順書などが例になる。複数あっても同じ原因で止まるなら、独立した備えになっているか見直す。","quotation":null},{"id":"kb_280","title":"分散戦略","summary":"一つに集中せず複数へ分け、一つの失敗の影響を小さくすること。\n仕事の依頼先や情報源を一か所に頼りすぎない工夫など。分ける数だけでなく、同じ原因で一緒に失われないかを確かめる。","quotation":null},{"id":"kb_567","title":"ポートフォリオ理論","summary":"性質の違う資産を組み合わせ、全体の利益と危険を調整する理論。\n一つずつの良し悪しに加え、同時にどう動くかが全体の危険を左右する。数を増やすだけで安心せず、性質や共通する条件の違いを見る考え方。","quotation":null},{"id":"kb_278","title":"オプション価値","summary":"今決めず、後で情報が増えてから選べる余地の価値。\n試用期間や短期参加なら、経験してから本格的に決める余地を残せる。決める速さだけでなく、後の選択肢を保つために何を払うかも考える。","quotation":null},{"id":"kb_279","title":"リアル・オプション理論","summary":"小さく投資して選択権を持ち、見通しが立ってから本格的に進むという理論。\n新しい事業を一部の地域で試し、結果を見て広げるかを選ぶ方法など。小さな試みで何を学び、どの条件で次へ進むかを明確にする。","quotation":null},{"id":"kb_283","title":"アンチフラジャイル","summary":"変動や失敗に耐えるだけでなく、それを通じて強くなること。\n小さな試行の失敗から仕組みを改善し、次に同じ問題が起きにくくなる例など。どんな打撃でもよいという意味ではなく、回復できる範囲の学びを重視する。","quotation":null},{"id":"kb_282","title":"バーベル戦略","summary":"大部分を安全に保ち、一部で大きな可能性のある挑戦をする戦略。\n生活を支える基盤を守りつつ、失っても立て直せる範囲で新しい活動を試す考え方。安全と挑戦の線を曖昧にせず、最悪の場合の影響も確かめる。","quotation":null},{"id":"kb_841","title":"リスク補償／ペルツマン効果","summary":"安全対策で安心した分、行動が大胆になり、効果が相殺されること。\n安全装置を付けたことで、以前より確認を省く場面など。対策の性能だけでなく、その後に行動がどう変わるかまで含めて効果を見る。","quotation":null},{"id":"kb_284","title":"OODAループ","summary":"観察、状況判断、決定、行動を繰り返し、変化に対応する方法。\n行動したら終わりにせず、その反応を次の観察へ戻す。速く回すこと以上に、状況の捉え方が古くなっていないかを更新する。","quotation":null},{"id":"kb_548","title":"適応的計画","summary":"新しい情報や結果に合わせ、手順や期限を変えていく計画のこと。\n目的は保ちながら、途中の結果を見て順番や規模を変える。変更が行き当たりばったりにならないよう、見直す時点と判断の材料を決めておく。","quotation":null},{"id":"kb_285","title":"創発戦略","summary":"初めから決めるのでなく、現場での行動と学びから戦略ができるという考え方。\n顧客への小さな対応が重なり、当初とは違う事業の強みになる場合など。現場で起きている工夫を拾い、続ける価値のある方向を見つける。","quotation":null},{"id":"kb_288","title":"経路依存性","summary":"過去の選択や偶然が、今の選択肢を狭め、同じ方向へ進ませること。\n昔導入した仕組みに合わせて、今も別の選択が難しい場合など。最初に選んだ理由が今も有効か、切り替える費用と分けて考える。","quotation":null},{"id":"kb_488","title":"漸進主義","summary":"一度に大きく変えず、小さく変えて確かめながら進む考え方。\nいきなり全体を変えず、一部の手順を変えて反応を確かめる。小さな改善では届かない問題もあるため、目的に足りる変化かも点検する。","quotation":null},{"id":"kb_544","title":"選択と集中","summary":"限られた力を、重要な少数の分野へ集中させること。\nやらない仕事を決め、重要な課題に時間や人を配る。集中しすぎて代案や将来の学びを失わないよう、見直す余地も残す。","quotation":null},{"id":"kb_561","title":"バックキャスティング","summary":"望む未来から逆算して、今必要な行動を考える方法。\n一年後に望む状態を置き、半年後に必要な準備、今月の行動へたどる。今の延長だけでは見つからない、途中の課題や別の道を探せる。","quotation":null},{"id":"kb_495","title":"反復開発","summary":"小さく作り、試して直すことを繰り返す方法。\nまず使える小さな形を見せ、反応を得て次の版へ直す。毎回すべてを変えるのでなく、何を確かめた結果の変更かを残す。","quotation":null},{"id":"kb_546","title":"レバレッジ","summary":"仕組みや技術、人の力を使い、少ない追加の手間で大きな成果を得ること。\n同じ説明を毎回する代わりに、共有できる資料を一度つくる方法など。増幅されるのは誤りや損も同じなので、広げる前の確認も必要になる。","quotation":null},{"id":"kb_932","title":"反証可能性","summary":"主張が間違いなら、何を確かめれば分かるかを示せること。\n「うまくいかなければ努力不足」と何でも説明できる主張は、確かめにくい。どんな結果なら考えを変えるかを先に示すと、議論の足場になる。","quotation":null},{"id":"kb_938","title":"シンプソンのパラドックス","summary":"集団ごとに見える傾向が、全体をまとめると逆転すること。\n難しい案件の多い担当者は、案件の種類ごとには成績がよくても、全体では低く見える場合がある。割合を比較するときは、集団の内訳も確かめる。","quotation":null},{"id":"kb_016","title":"呼び名の活用","summary":"相手の名前や望む呼び方を使い、関心や親しみを伝えること。\n大勢への一括した呼びかけより、本人が望む呼び方で話すと、誰に向けた言葉かが伝わる。呼ぶ回数を増やすより、呼び間違いやなれなれしさに気を配る。","quotation":null},{"id":"kb_408","title":"価値観推定","summary":"繰り返す言葉や選択、喜怒から、相手の大切なものを推測すること。\n「自由にできたのがうれしい」と繰り返す人なら、裁量を重視しているかもしれない。推測は仮に置き、本人への確認で修正していく。","quotation":null},{"id":"kb_101","title":"イエス・セット","summary":"同意しやすい問いを重ね、肯定的な返答の流れをつくる方法。\n話し合いの最初に、互いに確認できる事実や目的をそろえる使い方がある。前の同意が次の提案への同意を意味するわけではなく、条件ごとに意思を確かめる。","quotation":null},{"id":"kb_409","title":"言語的顕著性","summary":"繰り返したり強調したりする言葉を、相手の関心の手がかりにすること。\n「安心」「早さ」など、繰り返される語には本人の優先事項が表れる場合がある。口癖だけで決めず、どの場面で何を強調したかを聞いて理解を深める。","quotation":null},{"id":"kb_417","title":"認知的承認","summary":"以前の話を覚えて触れることで、「あなたの話を受け止めた」と伝えること。\n「前に話していた試験はどうだった？」と自然に尋ねる場面など。知っている情報を披露するより、相手が大切にした話を丁寧に扱う。","quotation":null},{"id":"kb_464","title":"会話ターン取得","summary":"視線や息継ぎ、語尾などの合図を読み、話す順番を取ること。\n話が一段落したところで、短い相づちとともに入る方法など。大きな声で割り込む前に、相手が続けたいのか、順番を渡そうとしているのかを見る。","quotation":null},{"id":"kb_463","title":"タイミング効果","summary":"同じ言葉でも、伝える時機や会話の流れによって影響が変わること。\n忙しい直前の相談と、余裕のある時刻の相談では受け取る負担が違う。内容を磨くとともに、「今話して大丈夫か」を確かめる。","quotation":null},{"id":"kb_1049","title":"動機づけ面接","summary":"変化を押しつけず、本人の理由や価値観を引き出す対話の方法。\n「変えたほうがよい」と説くより、変えたい理由と迷っている理由の両方を聴く。本人の選択を尊重し、話す中から自分で進む方向を見つけるのを助ける。","quotation":null},{"id":"kb_1053","title":"SCQA","summary":"共通の状況、問題、問い、答えの順で、説明を組み立てる方法。\n「今はこうなっている」「ここに困り事がある」「ではどうするか」「こう提案する」とつなぐ。聞き手が答えを知る前に、なぜその問いが必要かを理解できる。","quotation":null},{"id":"kb_1054","title":"SPIN話法","summary":"状況、問題、その影響、解決の価値を、質問で明らかにする方法。\n困り事を尋ねた後、それが何に影響するか、解消できると何がよいかを聴く。用意した問いを押し通さず、本人が実際に困る場面を理解するために使う。","quotation":null},{"id":"kb_448","title":"境界尊重テスト","summary":"小さな断りへの反応から、相手が自分の意思を尊重するか確かめること。\n「今日は難しい」と伝えたときに、理由を尊重するか、責めて従わせるかを見る。わざと試すのでなく、必要な境界を伝えたときの繰り返しの反応を手がかりにする。","quotation":null},{"id":"kb_432","title":"接触頻度管理","summary":"疲れや負担も考え、人と会う回数や連絡の間隔を調整すること。\n会う回数を減らす、返せる時刻を伝えるなど、続けられる関わり方を選ぶ。連絡の多さだけを親しさの基準にせず、双方の負担も話し合える。","quotation":null},{"id":"kb_471","title":"負の紐帯管理","summary":"敵意や不信のある関係で、距離や接点を調整して負担を減らすこと。\n必要な連絡を文面にし、第三者のいる場で話すなどの工夫がある。無理に親しくなることを目指さず、安全と用事の範囲に合う接点を考える。","quotation":null},{"id":"kb_557","title":"手段の目的化","summary":"本来の目的を忘れ、手段を続けること自体が目的になること。\n健康のための記録で、記入を埋めることばかり気になる場面など。続けている理由へ戻り、その手段が今も目的を助けているかを確かめる。","quotation":null},{"id":"kb_568","title":"最適化の罠","summary":"最善を求め続けたために、時間や機会を失い、満足も下がること。\n道具を比べ続け、始めたかった勉強の時間がなくなる場合など。比較でよくなる見込みと、その時間にできたことを合わせて考える。","quotation":null},{"id":"kb_554","title":"後悔最小化","summary":"将来何を後悔しそうかを考え、長い目で納得できる選択をする方法。\n挑まない後悔だけでなく、準備不足で失うものや、大切な人との時間も含めて考える。未来の自分は変わり得るので、やり直せる余地も判断に入れる。","quotation":null},{"id":"kb_591","title":"評価の時間的不確実性","summary":"出来事のよしあしは、その後の展開によって変わるという見方。\n不採用が別の進路への入口になったとしても、当時のつらさは消えない。すぐに成功か失敗かを決めず、時点によって評価が違う余地を残す。","quotation":null},{"id":"kb_1057","title":"なぜなぜ分析（5 Whys）","summary":"「なぜ」を重ね、表面の問題から対処できる原因を探す方法。\n「確認が抜けた」の次に、確認する場所や担当が決まっていたかをたどる。五回という回数にこだわらず、根拠を確かめ、本人を責めるだけの問いにしない。","quotation":null},{"id":"kb_1058","title":"ロジックツリー","summary":"大きな問題を、小さな論点や要因へ枝分かれさせて整理する方法。\n売上の問題なら、利用者数と一人当たりの購入などに分けて考える。枝を作ることが目的にならないよう、確かめられる情報や対策へつなげる。","quotation":null},{"id":"kb_1059","title":"MECE","summary":"分類するとき、重なりと抜けをなくすという考え方。\n費用を分けるとき、同じ支出を二重に数えず、どこにも入らない支出を残さない。現実には境界が曖昧なものもあるため、分類の目的と基準を明示する。","quotation":null},{"id":"kb_1060","title":"意思決定ジャーナル","summary":"決めたときの根拠や予想を記録し、後で結果と比べる方法。\n予想、迷った案、重視した条件を、結果を知る前に短く残す。後で「最初から分かっていた」と記憶を変えず、判断の進め方を見直せる。","quotation":null},{"id":"kb_1061","title":"意思決定マトリクス","summary":"選択肢を共通の基準で並べ、何を重視するか明らかにして比べる方法。\n費用、使いやすさ、期限などを同じ表に並べ、基準ごとの重要度も決める。点数を足せば正解になるのではなく、何を重視したかを見えるようにする。","quotation":null},{"id":"kb_529","title":"スモールステップ","summary":"大きな課題を、すぐできる小さな行動に分けて進める方法。\n「資料を完成する」を「見出しを三つ書く」まで小さくする方法など。小ささは人や状態に合わせ、終えたら次の一歩を選ぶ。","quotation":null},{"id":"kb_532","title":"作業興奮","summary":"作業を始めると、後からやる気が湧き、続けやすくなること。\n片づけを一分だけ始めたら、次の作業にも手が伸びる場合など。始めれば必ず続くと考えず、着手しやすい準備や終える目安も用意する。","quotation":null},{"id":"kb_592","title":"確率的機会","summary":"試す回数や人との接点を増やせば、機会にも出会いやすいという考え方。\n作品を見せる、違う場へ参加するなど、出会いの入口を増やす発想。数を増やせば成功する保証ではないため、負担と学びを見ながら試す。","quotation":null},{"id":"kb_594","title":"幸運の表面積","summary":"活動する量と、それを知る人を増やし、幸運が届く入り口を広げるという考え方。\n黙って準備するだけでなく、作ったものや関心を周囲に伝える。機会が来たときに、誰が何をしている人か分かる状態をつくる考え方。","quotation":null},{"id":"kb_1075","title":"タイムブロッキング","summary":"やることごとに、取り組む時間を予定表へ確保する方法。\n「午前は何となく資料作り」ではなく、取り組む時間を具体的に置く。予定外の対応や休息の余白も確保し、埋め尽くすことを目標にしない。","quotation":null},{"id":"kb_1077","title":"コーネル式ノート","summary":"記録、問い、要約の欄を分け、思い出す練習にも使うノートの取り方。\n右に内容、左に問いや手がかり、下に短い要約を残す形が代表的。左の問いを見て内容を思い出すと、読み返し以外の復習にも使える。","quotation":null},{"id":"kb_1078","title":"記憶の宮殿","summary":"覚えたい情報を、知っている場所に置くイメージで記憶する方法。\n玄関、廊下、机などに情報を置き、頭の中で順にたどって思い出す。場所と内容の結びつきは、自分が思い浮かべやすい具体的な像にする。","quotation":null},{"id":"kb_1079","title":"コンセプトマップ","summary":"概念同士を線と関係を表す言葉で結び、知識を整理する方法。\n用語を並べるだけでなく、「原因になる」「一部である」など、線の意味を書く。つながりを説明できない場所が、理解を確かめ直す手がかりになる。","quotation":null},{"id":"kb_547","title":"タイムボックス","summary":"使う時間の上限を先に決め、その中で仕事を進める方法。\n調査は二十分と決め、その後に分かった範囲で次を選ぶ方法など。締切との違いは、作業に使う時間そのものを先に区切る点にある。","quotation":null},{"id":"kb_192","title":"パーキンソンの法則","summary":"仕事は、与えられた時間を使い切るまで膨らむという経験則。\n余裕があると、細部の修正や比較を増やし続ける場面など。仕事の期限に加え、完成とする条件も決めると終わりを見つけやすい。","quotation":null},{"id":"kb_483","title":"アジェンダ設定","summary":"何をどの順に議論するかを決め、話し合いの範囲を整えること。\n会議前に決めたいことと必要な情報を示すと、話の広がりを整えられる。議題にない大切な問題があれば、拾う方法や別の場も用意する。","quotation":null},{"id":"kb_498","title":"意思決定支援","summary":"情報や選択肢、判断の基準を整理し、本人の納得できる選択を助けること。\n選択肢を説明しても、本人が大切にする条件を知らなければ助けになりにくい。代わりに決めるのではなく、情報を分かる形で渡し、意思を確かめる。","quotation":null},{"id":"kb_435","title":"期待管理","summary":"できる範囲や期限を先に共有し、相手の期待を現実に近づけること。\n依頼を受ける時点で、仕上がりの範囲、期限、連絡する時機を共有する。過大に約束して後で埋め合わせるより、途中でずれを確かめられる関係をつくる。","quotation":null},{"id":"kb_487","title":"責任の明確化","summary":"誰が何をいつまでに担うかを、はっきりさせること。\n「誰かが確認する」ではなく、担当、期限、完了の合図まで決める。担当者へ責任だけを渡さず、必要な情報や権限もそろえる。","quotation":null},{"id":"kb_394","title":"具体的フィードバック","summary":"観察した行動と結果、次に変える点を具体的に伝えること。\n「分かりにくい」より「結論が最後だったので、最初に一文置いてほしい」と伝える。人格への評価を避け、次に変えられる行動へ焦点を合わせる。","quotation":null},{"id":"kb_502","title":"正常性の不可視性","summary":"問題が起きない状態は目立たず、予防や保守の貢献が見えにくいこと。\n故障も混乱もなかった日は、そのための点検や調整が見えにくい。防いだ問題や日々の作業を残すと、支える仕事の価値を共有しやすい。","quotation":null},{"id":"kb_575","title":"複利効果","summary":"得たものを次の土台に加え、増加がさらに増加を生むこと。\n学んだ知識が次の理解を助け、理解がさらに学びを進めるような見方もできる。比喩で使う場合は、毎回同じ割合で伸びると決めつけない。","quotation":null},{"id":"kb_482","title":"独立的同調","summary":"集団と協調しながらも、大切な判断では自分の基準を保つこと。\n場の進め方には協力しつつ、判断に関わる懸念は伝える態度など。合わせる部分と譲れない部分を、自分の中で言葉にしておく。","quotation":null},{"id":"kb_475","title":"服従シグナル","summary":"謝罪や同意が多すぎると、拒否や反論をしない人と見られやすくなること。\n必要以上に謝り続けると、役割の範囲を越える依頼まで引き受ける人と思われる場合がある。謝るべき点と、受けられない条件を分けて伝える。","quotation":null},{"id":"kb_517","title":"第三者証明","summary":"自分の主張だけでなく、他者の評価や実績で信頼を示すこと。\n利用者の感想や担当した実績は、自己評価以外の手がかりになる。誰のどんな経験に基づく評価かを示し、権威だけで納得を迫らない。","quotation":null},{"id":"kb_1062","title":"アフターアクションレビュー","summary":"予定、実際、違いの理由、次の改善を確かめる振り返りの方法。\n活動の直後に、狙いと実際を並べ、次に残す行動を選ぶ。人を評価する場に偏らせず、条件や手順から学ぶことを重視する。","quotation":null},{"id":"kb_1063","title":"KPT振り返り","summary":"続けること、問題、次に試すことの三つで振り返る方法。\nKeepにうまくいったこと、Problemに困ったこと、Tryに次の試みを書く。問題の列挙で終えず、試すことを担当と期限へつなげる。","quotation":null},{"id":"kb_1065","title":"ステークホルダーマップ","summary":"関わる人の関心や影響力を整理し、必要な対話を考える方法。\n決める人、使う人、影響を受ける人を整理すると、誰の声が抜けているかが見える。立場を固定せず、関心や影響の変化に合わせて更新する。","quotation":null},{"id":"kb_1066","title":"PEST分析","summary":"外部の変化を、政治・制度、経済、社会、技術の四つから考える方法。\n制度の変更、物価、生活習慣、新しい技術が、自分の活動へどう影響するかを見る。四つの欄を埋めるだけでなく、具体的に備える変化を選ぶ。","quotation":null},{"id":"kb_1067","title":"AIDAモデル","summary":"広告の働きを、注意、関心、欲求、行動の四つで考える理論。\n目に入っても関心につながらないなら、情報の出し方を見直すなどに使える。実際の行動は一直線とは限らないため、どこで迷うかを観察する。","quotation":null},{"id":"kb_1068","title":"JTBD","summary":"人が商品を選ぶ理由を、その状況で何を成し遂げたいかから考える方法。\n道具の機能より、「忙しい朝に短時間で準備を終えたい」などの用事に注目する。同じ商品でも、使う状況によって必要な価値は違う。","quotation":null},{"id":"kb_1069","title":"STP分析","summary":"利用者を分け、対象を選び、その人に届ける価値を決める方法。\n誰にでも届けようとせず、どんな人のどの困り事を優先するかを決める。その人が他の選択肢と比べて選ぶ理由まで、一貫して考える。","quotation":null},{"id":"kb_1070","title":"マーケティングの4P","summary":"売り方を、製品、価格、流通、販促の四つから組み立てる考え方。\nよい製品でも、価格や入手方法が合わなければ届きにくい。四つを別々に決めず、対象となる人にとって整合しているかを見る。","quotation":null},{"id":"kb_1071","title":"カスタマージャーニーマップ","summary":"利用者の行動や気持ちを時系列に並べ、困る地点を探す方法。\n知る、比べる、使う、使い続けるという流れの中で、不安や手間を探す。作り手の想像だけで埋めず、本人の話や実際の行動で確かめる。","quotation":null},{"id":"kb_538","title":"自己モニタリング","summary":"自分の行動や気持ち、時間の使い方を記録し、実態を知ること。\n「集中できない」と感じたら、作業した時刻や中断のきっかけを短く残す。理想との差を責めるためでなく、変えられる条件を探す材料にする。","quotation":null},{"id":"kb_443","title":"行動的一貫性","summary":"言葉で伝えた価値観や約束と、実際の行動が一致していること。\n「休息を大切に」と言いながら休日の返信を求めると、言葉より行動が伝わる。周囲へ伝えたい基準と、自分が実際に求める行動を照らし合わせる。","quotation":null},{"id":"kb_562","title":"有限性の自覚","summary":"時間や体力、注意には限りがあると理解すること。\n新しいことを始めるなら、何を減らすかも一緒に考える。全てをこなす工夫だけでなく、使える力をどこへ配るかを選ぶ視点。","quotation":null},{"id":"kb_553","title":"役割多元化","summary":"複数の役割を持ち、一つの役割だけで自分の価値を決めないこと。\n仕事、友人、家庭、趣味など、複数の場に自分の居場所を持つ。役割の数を増やすほどよいのでなく、負担と支えの両方を見ながら配分する。","quotation":null},{"id":"kb_499","title":"自己犠牲バイアス","summary":"自分の時間や健康を削ることを、貢献の証拠として高く評価しすぎること。\n無理して対応した人だけが称賛されると、続けられるやり方が評価されにくい。費やした苦しさより、得られた成果と継続できる条件を見直す。","quotation":null},{"id":"kb_551","title":"到達錯誤","summary":"目標を達成すれば、幸せや悩みの解消がずっと続くと思い込むこと。\n資格や昇進を得た後も、日常の悩みや次の課題は残ることがある。到達点だけに生活の満足を預けず、その途中の暮らし方も整える。","quotation":null},{"id":"kb_311","title":"「知らざるを知らずと為す、是れ知るなり」","summary":"知らないことを認める姿勢が、本当の理解につながるという教え。\n会議で分かったふりをするより、分からない点を確認する場面に活かせる。知っている範囲を明らかにすることが、他の人の知恵を借りる入口になる。","quotation":null},{"id":"kb_298","title":"「過ちて改めざる、是を過ちと謂う」","summary":"間違えることより、間違いを直さないことが問題だという教え。\n誤りが分かったら、言い訳の完成より先に、影響の確認と修正へ進む。失敗のない人を目指すより、気づいた後の対応を大切にする視点。","quotation":null},{"id":"kb_304","title":"「巧言令色、鮮なし仁」","summary":"口のうまさや愛想だけで、誠実な人かを判断しないという戒め。\n感じのよい言葉を受け取る際も、約束や不在の人への接し方を合わせて見る。愛想を疑い続けるのでなく、言葉と行動の両方で判断する。","quotation":null},{"id":"kb_624","title":"「己の欲せざる所、人に施すこと勿れ」","summary":"自分がされて嫌なことを、他人にもしないという教え。\n自分が嫌がる催促や詮索を、親しい相手にはしていないか振り返れる。ただし相手の好みが自分と同じとは限らないため、本人の望みも確かめる。","quotation":null},{"id":"kb_622","title":"「三人行えば、必ず我が師あり」","summary":"どんな相手からでも、学べる点は見つかるという教え。\nよい行動は取り入れ、好ましくない行動は自分にもないかを点検する。肩書や好き嫌いだけで学ぶ相手を絞らず、具体的な振る舞いに目を向ける。","quotation":null},{"id":"kb_625","title":"「学びて思わざれば則ち罔し、思いて学ばざれば則ち殆うし」","summary":"知識を得ることと、自分で考えることを両立させるという教え。\n本を読むだけでは、自分の状況に合うかを考えにくい。一方、経験だけで決めず、別の知識で確かめることも、思い込みを見直す助けになる。","quotation":null},{"id":"kb_299","title":"「和して同ぜず」","summary":"人と調和しても、無理に意見まで合わせないという教え。\n相手の目的を尊重しながら、方法への異論を伝える場面など。関係を保つことと意見を一致させることを、一つに結びつけすぎない。","quotation":null},{"id":"kb_623","title":"「過ぎたるは猶及ばざるが如し」","summary":"やりすぎは不足と同じように問題になるという教え。\n助言も気遣いも、多すぎると相手の負担や干渉になる場合がある。善意の量を増やすより、その場で必要な程度を確かめる。","quotation":null},{"id":"kb_617","title":"「自分を知る者は明らかである」","summary":"他人を知るだけでなく、自分を理解することを重んじる教え。\n得意な場面だけでなく、無理をしやすい条件や弱点も知っておく。人との比較に偏るとき、自分が望むことと続けられる範囲へ戻る手がかりになる。","quotation":null},{"id":"kb_618","title":"「足るを知る者は富む」","summary":"すでにあるものに目を向け、十分だと知ることが豊かさになるという教え。\n欲しいものを増やし続ける前に、今使えている時間や支えを数え直す。現状への不満を禁じるのでなく、何があれば十分かを自分で決める視点。","quotation":null},{"id":"kb_619","title":"「人に勝つ者は力があり、自分に勝つ者は強い」","summary":"他人に勝つ力より、自分の欲望や弱さを制する力を重んじる教え。\n言い返したい場面で一度待つ、決めた行動へ戻るといった場面で読める。感情をなくすのでなく、感情があっても振る舞いを選ぶことに力を使う。","quotation":null},{"id":"kb_620","title":"「千里の道も足下から始まる」","summary":"大きな目標も、小さな一歩から始まるという教え。\n遠い目標でも、今日できる行動に直すと着手の場所が見える。最初から全行程を完璧に進めようとせず、次の一歩を確かめながら続ける。","quotation":null},{"id":"kb_621","title":"「柔よく剛を制す」","summary":"強い力への正面対抗より、柔軟な対応が有効な場合もあるという教え。\n押し合いを続けず、時機や話す場所を変えることで解ける問題もある。柔軟さを無条件の譲歩とせず、目的を保ちながら手段を選ぶ。","quotation":null},{"id":"kb_632","title":"無用の用","summary":"すぐ役立たないものにも、余白や自由を生む価値があるという考え方。\n予定を入れない時間や、仕事に直結しない興味が、後の発見や回復につながることがある。今測れる成果だけで、生活の余白を削りきらないための見方。","quotation":null},{"id":"kb_312","title":"「桃李もの言わざれども、下自ずから蹊を成す」","summary":"実力や人柄があれば、強く宣伝しなくても人は集まるという教え。\n宣伝の言葉に加え、日々の誠実な対応や仕事の質が信頼をつくるという読み方ができる。ただ待てば必ず見つけてもらえる保証ではなく、価値を伝える工夫も要る。","quotation":null},{"id":"kb_701","title":"「生きることを引き受けて歩む」","summary":"生きる難しさを受け止め、自分の歩みを続けるという考え方。\n難しさがある中でも、自分が大切にする行動を少しずつ選ぶという読み方ができる。何でも一人で背負うのでなく、頼ることや休むことも歩みの中に含められる。","quotation":null},{"id":"kb_702","title":"「暮らしにくさの中で、視点を探す」","summary":"暮らしにくさに対し、見方や距離を変えて余地を探すという考え方。\nつらい場にとどまって考え続けるだけでなく、離れて眺めると別の道が見えることがある。問題をなかったことにせず、自分が扱える距離や表し方を探す。","quotation":null},{"id":"kb_604","title":"「自分にできることと、できないことを分ける」","summary":"変えられることに力を使い、変えられないことへの執着を減らす考え方。\n相手の評価は決められなくても、準備や伝え方は選べる。力を注ぐ場所を分けることで、結果への心配だけに時間を使わずに済む。","quotation":null},{"id":"kb_579","title":"統制の二分法","summary":"自分で選べることと、自分では決められないことを分ける考え方。\n自分の意見や行動と、他人の反応や偶然の結果を分けて見る。全てを諦めるためでなく、今働きかけられる部分を見つけるために使う。","quotation":null},{"id":"kb_603","title":"「人は物事そのものではなく、それについての判断に悩まされる」","summary":"出来事よりも、それをどう受け取るかが苦しさを左右するという考え方。\n返信が遅れた事実に「嫌われた」という判断を加えると、苦しさが増す場合がある。出来事と解釈を分けることは、現実の被害まで本人の考えのせいにする意味ではない。","quotation":null},{"id":"kb_606","title":"「与えられた役を、よく演じる」","summary":"条件を選べなくても、その中でどう振る舞うかを大切にする考え方。\n任された立場の中で、誠実にできることを選ぶという読み方がある。不当な役割まで黙って受け入れるのでなく、自分の選択や働きかけの範囲も考える。","quotation":null},{"id":"kb_605","title":"「自分で勝てない勝負には入らない」","summary":"努力する前に、勝負する場所を選ぶという教え。\n相手の基準だけで争うより、自分が力を出せる条件へ移る道を探す。避けるべきなのは全ての難しさではなく、目的に見合わない消耗と捉えられる。","quotation":null},{"id":"kb_607","title":"「起きたことから利益を引き出せるかは自分次第である」","summary":"起きたことを選べなくても、どう活かすかは選べるという考え方。\n失敗から準備の抜けを見つけ、次の手順へ残すような読み方ができる。つらい経験を無理によかったことにせず、活かせる部分があるかを自分のペースで考える。","quotation":null},{"id":"kb_615","title":"「運命は、従う者を導き、抗う者を引きずる」","summary":"変えられない現実を受け入れ、適応することを重んじる教え。\n変わらない状況に抵抗し続ける負担と、今できる対応に力を使うことを比べる。現実を認めることと、不正や危険を放置することは分けて考えられる。","quotation":null},{"id":"kb_608","title":"「障害は、行動を前へ進める材料になる」","summary":"邪魔に見えるものも、使い方次第で前進の材料になるという考え方。\n説明が伝わらなかった経験から、伝え方を見直す機会を得る読み方など。障害を称賛するのでなく、今ある条件を次の工夫にどう変えるかを見る。","quotation":null},{"id":"kb_609","title":"「外の出来事より、それに与える判断が自分を動かす」","summary":"出来事への判断や意味づけが、自分の感情や行動を動かすという考え方。\n批判を「全否定」と読むか「直せる点の指摘」と読むかで、次の行動は変わる。自分の判断を確かめる余地を持ち、相手の言葉をそのまま自己評価にしない。","quotation":null},{"id":"kb_611","title":"「他人が何を考えているかより、自分の心を整える」","summary":"他人の評価より、自分で整えられる心や態度に力を向ける考え方。\n他人の本心を推測し続けるより、約束を守る、意見を伝えるなど自分の行動を整える。必要な確認はしつつ、分からない評価を追いかけすぎないために読める。","quotation":null},{"id":"kb_610","title":"「今この瞬間を、最後の行為のように行う」","summary":"先送りせず、今していることを大切にするという教え。\nいつもの会話や作業にも、今向けるべき注意を戻すという読み方がある。急いで全てを終えるのではなく、一つの行動を雑に扱わない姿勢として活かせる。","quotation":null},{"id":"kb_612","title":"「人生が短いのではない。多くを浪費している」","summary":"時間の短さより、使い方を見直すべきだという教え。\n忙しさに押される前に、時間が何に消えているかを見直す。休息まで浪費と決めず、自分で選んだ時間と、流れで使った時間を区別する。","quotation":null},{"id":"kb_613","title":"「正しく使えば、人生は十分に長い」","summary":"限られた時間も、よく使えば十分に生きられるという考え方。\n長さの比較より、自分にとって大切なことへ時間を渡せたかを考える。成果を詰め込むだけでなく、人との関わりや休息も含めて使い方を選べる。","quotation":null},{"id":"kb_614","title":"「苦しむ前から苦しむ者は、必要以上に苦しむ」","summary":"まだ起きていない苦しみを、想像で先取りしないという戒め。\nまだ起きていない失敗を、頭の中で何度も経験する場面に響く。必要な準備と、対策の増えない想像を分け、今できることへ戻る。","quotation":null},{"id":"kb_616","title":"「われわれが恐れるものは、現実より想像の中に多い」","summary":"恐れは、現実より頭の中の想像で膨らむこともあるという見方。\n予想した最悪の場面が、確かに起きる事実のように感じられることがある。分かっていることと想像を分け、確かめられる条件を一つずつ見る。","quotation":null},{"id":"kb_560","title":"目的論","summary":"行動を、過去の原因だけでなく、何を目指しているかから理解する考え方。\n同じ先延ばしでも、休みたいのか、失敗を避けたいのかで対応は変わる。ただし隠れた目的を外から断定せず、本人の事情と目指すものを確かめる。","quotation":null},{"id":"kb_951","title":"テセウスの船","summary":"部分をすべて交換しても、同じものと言えるかを問う思考実験。\n組織の人や仕組みがすべて変わっても、同じ組織なのかを考えられる。形、歴史、役割など、何を同一性の基準にしているかを問い直す入口になる。","quotation":null},{"id":"kb_952","title":"ソクラテス式問答法","summary":"問いを重ねて、言葉の意味や判断の前提、矛盾を明らかにする対話法。\n「よい仕事とは何か」「その基準は他の場面でも使えるか」と問いを進める。相手を追い詰めるのでなく、自分も前提を見直す対話として使う。","quotation":null},{"id":"kb_955","title":"功利主義","summary":"行動のよしあしを、人々にもたらす幸福や苦痛から判断する考え方。\n誰にどんな利益や負担が生じるかを、結果から広く比べる。多数の満足だけで少数の苦痛を見落とさないよう、誰の影響を数えたかも確かめる。","quotation":null},{"id":"kb_956","title":"無知のヴェール","summary":"自分がどんな立場になるか分からない前提で、公平なルールを考える方法。\n自分が強い側か弱い側か分からなくても、その制度を受け入れられるかと考える。立場に都合のよい例を離れ、ルールそのものを検討する手がかりになる。","quotation":null},{"id":"kb_626","title":"「知彼知己、百戦殆うからず」","summary":"自分と相手を知ることで、無謀な争いを避けるという教え。\n相手の要求だけでなく、自分の資源、限界、望む結果も知ることが要点になる。交渉や競争では、対策を練る前に条件を確かめる視点として活かせる。","quotation":null},{"id":"kb_627","title":"「勝兵は先ず勝ちて而る後に戦いを求む」","summary":"戦う前に、勝てる条件を整えるという教え。\n資源や協力者、実行の条件を整えてから動くという順番を重視する。仕事では、始めた後の頑張りだけに頼らず、進められる準備があるかを確かめる。","quotation":null},{"id":"kb_503","title":"「先ず勝つべからざるを為して、以て敵の勝つべきを待つ」","summary":"先に自分が負けない備えを整え、相手に隙ができるのを待つという教え。\n失敗が致命傷にならない備えを先に持ち、動く時機を見極める。待つことを放置にせず、何を観察し、どの条件なら動くかを決めておく。","quotation":null},{"id":"kb_628","title":"「善く戦う者は、勝ち易きに勝つ」","summary":"難しい勝負で勝つより、勝ちやすい状況をつくるという教え。\n難しい状況を力で突破する姿より、有利な条件をつくる工夫に価値を見る。得意な役割を選ぶ、先に協力を得るなど、勝負の前を見直せる。","quotation":null},{"id":"kb_504","title":"「善く戦う者の勝つや、智名無く、勇功無し」","summary":"危機を未然に防いだ優れた仕事ほど、派手な手柄に見えにくいという教え。\n問題を起こさず終えた仕事にも、準備や予防の力が隠れている。目立つ救出だけで評価せず、何を未然に防いだかを見返す視点になる。","quotation":null},{"id":"kb_490","title":"「戦わずして人の兵を屈するは、善の善なる者なり」","summary":"争って相手を傷つけるより、戦わずに目的を果たすことを重んじる教え。\n目的は相手を打ち負かすことか、それとも必要な結果を得ることかを問い直せる。話し合いや条件の変更で、争いの負担を減らせないかを考える。","quotation":null},{"id":"kb_505","title":"「善く戦う者は、不敗の地に立ちて、敵の敗を失わざるなり」","summary":"自分が崩れない備えを保ちながら、訪れた好機を逃さないという教え。\n普段は基盤を守りながら、条件が変わったら機会をつかむという両面を持つ。慎重さだけでも勢いだけでもなく、備えと判断の組み合わせとして読める。","quotation":null},{"id":"kb_496","title":"「兵は拙速を聞くも、未だ巧久を睹ざるなり」","summary":"巧みに長引かせるより、損が膨らむ前に決着させることを重んじる教え。\n長引くことで資源や関係が消耗するなら、決着までの負担も判断に入る。確認を省いて急ぐのではなく、必要な準備と長期化の損を比べる。","quotation":null},{"id":"kb_630","title":"「小敵の堅は、大敵の擒なり」","summary":"力の差を見ずに意地で争うと、大きな損をするという戒め。\n引くことを恥と考えると、目的以上の損を負う場合がある。力量と条件を見て、撤退や別の場を選ぶことも戦略として捉える。","quotation":null},{"id":"kb_629","title":"「兵に常勢なく、水に常形なし」","summary":"固定したやり方に頼らず、状況に合わせて変えるという教え。\n前にうまくいった型も、相手や環境が変われば通じないことがある。目的は保ちながら、その場の条件に合わせて手段を組み替える。","quotation":null},{"id":"kb_333","title":"「人間万事塞翁が馬」","summary":"幸運か不運かは、後の展開を見なければ分からないという教え。\n望まない変化が別の機会へつながることも、その逆もある。出来事をすぐ人生全体の結論にせず、その後に選べる行動を見る。","quotation":null},{"id":"kb_334","title":"「禍福は糾える縄の如し」","summary":"幸せと災いは、絡み合いながら移り変わるという教え。\nよい知らせにも新しい負担が伴い、つらい経験にも別の出会いがある。幸不幸を一色にせず、一つの変化の中にある複数の面を捉える。","quotation":null},{"id":"kb_336","title":"「明日は明日の風が吹く」","summary":"今の不安が、そのまま明日も続くとは限らないという教え。\n今夜の気分だけで、明日の自分や関係を決めつけないための言葉として読める。必要な準備をした後は、まだ分からない展開を残して休む余地も持つ。","quotation":null},{"id":"kb_335","title":"「案ずるより産むが易し」","summary":"始める前に恐れたほどは、実際は難しくないこともあるという教え。\n頭の中で難しさを膨らませるより、小さく試すと実際の負担が分かることがある。危険を無視する教えではなく、準備と実行の間で立ち止まり続けない視点。","quotation":null},{"id":"kb_301","title":"「雨降って地固まる」","summary":"困難を乗り越えることで、関係や基盤が強くなる場合があるという教え。\n問題を話し合い、今後の約束を変えることで、関係を立て直す場合がある。争い自体が関係をよくするのでなく、その後の対応が大切になる。","quotation":null},{"id":"kb_300","title":"「親しき仲にも礼儀あり」","summary":"親しい相手にも、敬意や配慮が必要だという教え。\n返事や感謝、予定変更の連絡を、親しさを理由に省いていないかを振り返れる。遠慮を増やすより、相手の時間や気持ちを尊重する基本を保つ。","quotation":null},{"id":"kb_296","title":"「情けは人の為ならず」","summary":"人への親切は、巡り巡って自分にも返るという教え。\n小さな協力が信頼を育て、後に別の支えへつながるという読み方ができる。必ず同じ相手から返るとは考えず、見返りを取り立てる親切にしない。","quotation":null},{"id":"kb_631","title":"「井の中の蛙、大海を知らず」","summary":"狭い環境だけを基準にすると、外の可能性を見失うという戒め。\n身近な職場や友人の基準を、世の中全体の基準と思い込む場合など。違う分野や立場の話に触れると、自分の当たり前を見直せる。","quotation":null},{"id":"kb_351","title":"狡兎三窟","summary":"逃げ道や拠点を複数持ち、一つを失っても備えるという教え。\n一つの仕事や居場所を失っても、戻れる関係や選択肢を持つという読み方。数をそろえるだけでなく、それぞれが同じ原因で失われない備えを考える。","quotation":null},{"id":"kb_352","title":"臥薪嘗胆","summary":"失敗や屈辱を忘れず、目標のために準備を続けるという教え。\n悔しさを繰り返し味わうことより、必要な練習や準備へ力を変える視点として読める。目標のために、健康や生活まで削り続けることとは分けて考える。","quotation":null},{"id":"kb_353","title":"捲土重来","summary":"一度敗れても、力を蓄え直して再挑戦するという教え。\n失敗した時点の条件を見直し、技能や資源を整えて再び挑む。前と同じことを繰り返すだけでなく、何を変えて戻るかが大切になる。","quotation":null},{"id":"kb_327","title":"「継続は力なり」","summary":"小さな行動も、長く続ければ力になるという教え。\n一回の大きな努力より、日々の小さな練習が土台になるという読み方。続ける対象や方法が目的に合うかは、途中でも確かめ直す。","quotation":null},{"id":"kb_324","title":"「巧遅は拙速に如かず」","summary":"完璧で遅い対応より、十分な形で早く動くほうがよい場合もあるという教え。\n見せて確かめられる初稿なら、細部を磨き続けるより早く出す価値がある。安全や正確さが必須の場面では、必要な確認を省く理由にはしない。","quotation":null},{"id":"kb_315","title":"「鶏口となるも牛後となるなかれ」","summary":"大組織の末端より、小さな場でも主導できる立場を重んじる教え。\n名前の大きさだけで所属を選ばず、自分が判断し成長できる範囲を見る。小さな場にも大きな場にも利点があるため、自分の目的と役割を比べる。","quotation":null},{"id":"kb_469","title":"「狡兎死して走狗烹らる」","summary":"共通の敵や課題がなくなると、協力関係の利害も変わるという戒め。\n同じ問題の解決に協力していても、その後の望みは一致しない場合がある。過去の協力を永久の保証にせず、節目ごとに互いの利害を確かめる。","quotation":null},{"id":"kb_468","title":"「鳥尽きて良弓蔵れ」","summary":"役割の必要がなくなれば、功労者でも立場を失う場合があるという教え。\n一つの役割だけに立場を預けると、その役割の終わりが生活を大きく揺らす。貢献を続けながら、次に活かせる技能や関係も育てる視点になる。","quotation":null},{"id":"kb_359","title":"「一つの籠にすべての卵を盛るな」","summary":"すべてを一つに託さず、失敗に備えて分けて持つという教え。\n情報源、依頼先、居場所などを一つに頼りきらない工夫として読める。分けた先が同じ条件で失われるなら、備えの違いも見直す。","quotation":null},{"id":"kb_329","title":"「完璧は善の敵」","summary":"完璧を求めるあまり、十分によい成果まで完成できなくなるという戒め。\n必要な水準に達しても細部を直し続け、届ける時機を逃す場面など。完成とする条件を決め、残る改善は次の版へ回す余地を持つ。","quotation":null},{"id":"kb_326","title":"「為せば成る、為さねば成らぬ何事も」","summary":"物事を実現するには、まず自分が着手する必要があるという教え。\nできるかを考えるだけでは、経験から学ぶ材料も増えない。努力すれば必ず叶うという保証ではなく、自分が動かせる最初の一歩へ目を向ける言葉。","quotation":null},{"id":"theory-8989915e-3d28-4fad-9521-1bdece206b3f","title":"「墨で書いた嘘は、血で書かれた事実を決して覆い隠せない。」","summary":"「墨で書いた嘘は、血で書かれた事実を決して覆い隠せない。」\n— 魯迅\n無花の薔薇 その二（華蓋集続編）\n\n都合のよい言葉で取り繕っても、虐殺の事実や犠牲は消せないという告発。\n被害の記録と、それを消そうとする言い分を同列に置かない強い表現として読める。身近な問題でも、説明の巧さに流されず、起きた事実と受けた影響を確かめる視点につながる。","quotation":{"work":"無花の薔薇 その二（華蓋集続編）","author":"魯迅","locator":"第8節、1926年3月18日","checkedOn":"2026-10-15","sourceUrls":["https://zh.wikisource.org/wiki/無花的薔薇之二"],"candidateId":"07","contextNote":"都合のよい言葉で取り繕っても、虐殺の事実や犠牲は消せないという告発。\n被害の記録と、それを消そうとする言い分を同列に置かない強い表現として読める。身近な問題でも、説明の巧さに流されず、起きた事実と受けた影響を確かめる視点につながる。","rightsBasis":"著者1936年没、原語作品は1926年までに公表済み。日本の旧保護期間に戦時加算の最大約11年を安全側に加えても2018年より前に満了し、延長による復活なし。原語本文のみ使用し現代の翻訳・編集文を除外。日本語は独自訳。","originalText":"墨寫的謊說，決掩不住血寫的事實。","rightsStatus":"cleared","verification":"verified","authorDeathYear":1936,"publicationYear":1926,"translationKind":"independent_translation","translationText":"墨で書いた嘘は、血で書かれた事実を決して覆い隠せない。","originalLanguage":"zh"}},{"id":"theory-4a83dca9-828a-4f93-8c7c-f945b36de56a","title":"「自由は山頂の空気に似ている。どちらも弱い者には堪えることはできない。」","summary":"「自由は山頂の空気に似ている。どちらも弱い者には堪えることはできない。」\n— 芥川龍之介\n侏儒の言葉\n\n自由には、選択の喜びだけでなく、結果を引き受ける責任もあるという言葉。\n自由を望むとき、選べる喜びとともに、迷いや結果の負担も考えさせる。弱い人に自由は不要という結論ではなく、自由を支える力や助けも問う言葉として読める。","quotation":{"work":"侏儒の言葉","author":"芥川龍之介","locator":"「自由」・「又」","checkedOn":"2026-10-15","sourceUrls":["https://www.aozora.gr.jp/cards/000879/files/43751_27955.html"],"candidateId":"09","contextNote":"自由には、選択の喜びだけでなく、結果を引き受ける責任もあるという言葉。\n自由を望むとき、選べる喜びとともに、迷いや結果の負担も考えさせる。弱い人に自由は不要という結論ではなく、自由を支える力や助けも問う言葉として読める。","rightsBasis":"著者1927年没。日本語原著は1927年までに公表済み。旧法の死後50年期間が2018年以前に満了し復活しない。日本著作物のため戦時加算なし。底本の新しい解説・校注を使用しない。","originalText":"自由は山巓の空気に似てゐる。どちらも弱い者には堪えることは出来ない。","rightsStatus":"cleared","verification":"verified","authorDeathYear":1927,"publicationYear":1927,"translationKind":"classical_transcription","translationText":"自由は山頂の空気に似ている。どちらも弱い者には堪えることはできない。","originalLanguage":"ja"}},{"id":"theory-b16cc75c-68d0-4873-b989-2ed788bd404b","title":"「人気者になるには、凡庸でなければならない。」","summary":"「人気者になるには、凡庸でなければならない。」\n— オスカー・ワイルド\nドリアン・グレイの肖像\n\n誰にでも好かれようとすれば、個性や鋭さを保ちにくいという皮肉。\n誰にも角を立てない表現だけを選ぶと、自分が伝えたい点まで薄れることがある。人気を求めることと、誰に何を届けたいかを分けて考えるきっかけになる。","quotation":{"work":"ドリアン・グレイの肖像","author":"オスカー・ワイルド","locator":"第17章、ヘンリー卿の台詞","checkedOn":"2026-10-15","sourceUrls":["https://www.gutenberg.org/cache/epub/174/pg174.txt"],"candidateId":"10","contextNote":"誰にでも好かれようとすれば、個性や鋭さを保ちにくいという皮肉。\n誰にも角を立てない表現だけを選ぶと、自分が伝えたい点まで薄れることがある。人気を求めることと、誰に何を届けたいかを分けて考えるきっかけになる。","rightsBasis":"著者1900年没、原語作品は1891年までに公表済み。日本の旧保護期間に戦時加算の最大約11年を安全側に加えても2018年より前に満了し、延長による復活なし。原語本文のみ使用し現代の翻訳・編集文を除外。日本語は独自訳。","originalText":"To be popular one must be a mediocrity.","rightsStatus":"cleared","verification":"verified","authorDeathYear":1900,"publicationYear":1891,"translationKind":"independent_translation","translationText":"人気者になるには、凡庸でなければならない。","originalLanguage":"en"}},{"id":"theory-c83321fd-d076-4d5c-b270-6af925c204a5","title":"「人は、自分が幸福だと知らないから不幸なのだ。ただそれだけのために。」","summary":"「人は、自分が幸福だと知らないから不幸なのだ。ただそれだけのために。」\n— ドストエフスキー\n悪霊\n\nすでにある幸せに気づかないことが、不幸を感じる理由になるという言葉。\n欠けているものに注意が向くと、すでに支えてくれる日常が見えにくくなる。現実の苦しみを気の持ちようで片づけず、今ある支えも見直す問いとして受け取れる。","quotation":{"work":"悪霊","author":"ドストエフスキー","locator":"第2部第1章「夜」、キリーロフの台詞","checkedOn":"2026-10-15","sourceUrls":["https://ru.wikisource.org/wiki/Бесы_(Достоевский)/Часть_2/Глава_1"],"candidateId":"14","contextNote":"すでにある幸せに気づかないことが、不幸を感じる理由になるという言葉。\n欠けているものに注意が向くと、すでに支えてくれる日常が見えにく